+    public override void OnDamage(int amount, Mobile from, bool willKill)
+    {
+        base.OnDamage(amount, from, willKill);
+
+        if (Hits < 15000 && from != null)
+        {
+            TurnIntoAttacker(from);
+        }
+    }
+
+    private void TurnIntoAttacker(Mobile from)
+    {
+        if (Map == null || from.Combatant is not { } m)
+        {
+            return;
+        }
+
+        if (m.Body == 51)
+        {
+            m.Say("Your soul is now mine!");
+        }
+
+        if (m.Body == from.Body)
+        {
+            return;
+        }
+
+        if (m.Mounted)
+        {
+            m.FindItemOnLayer(Layer.Mount)?.Delete();
+        }
+
+        m.BoltEffect(0);
+        m.Body = from.Body;
+        m.Hue = from.Hue;
+        Warmode = true;
+        m.BoltEffect(0);
+        m.Say(_taunts.RandomElement());
+    }
+
+    public override void OnSpeech(SpeechEventArgs e)
+    {
+        if (!e.Handled && e.Mobile == ControlMaster && e.Mobile.InRange(Location, 5))
+        {
+            var speech = e.Speech;
+
+            if (speech == "change help")
+            {
+                foreach (var line in _help)
+                {
+                    Say(line);
+                }
+
+                Say(LastHelpLine);
+                Say("Check your journal for everything I just said!");
+            }
+            else if (speech == "change color")
+            {
+                Say("As you wish!");
+                Hue = Utility.Random(2, 1200);
+            }
+            else if (speech == "change color normal")
+            {
+                Say("As you wish!");
+                Hue = 0;
+            }
+            else if (_forms.TryGetValue(speech, out var body))
+            {
+                Say("As you wish!");
+                Body = body;
+            }
+        }
+
+        base.OnSpeech(e);
+    }
