+    public override bool OnBeforeDeath()
+    {
+        var abomination = new AbominationOfMondain
+        {
+            Team = Team,
+            Combatant = Combatant,
+            NoKillAwards = false
+        };
+
+        if (abomination.Backpack == null)
+        {
+            abomination.AddItem(new Backpack { Movable = false });
+        }
+
+        var luck = LootPack.GetLuckChanceForKiller(this);
+
+        for (var i = 0; i < 2; i++)
+        {
+            LootPack.FilthyRich.Generate(this, abomination.Backpack, true, luck);
+            LootPack.FilthyRich.Generate(this, abomination.Backpack, false, luck);
+        }
+
+        Effects.PlaySound(this, GetDeathSound());
+        Effects.SendLocationEffect(Location, Map, 0x3709, 30, 0x835);
+        abomination.MoveToWorld(Location, Map);
+
+        Delete();
+        return false;
+    }
