+[SerializationGenerator(0)]
+public partial class AbominationOfMondain : BaseCreature
+{
+    private static readonly Dictionary<Mobile, ColdWind> _coldWinds = new();
+
+    [Constructible]
+    public AbominationOfMondain() : base(AIType.AI_Mage)
+    {
+        Body = 252;
+        BaseSoundID = 0x482;
+        Kills = 10;
+        SetSpeed(0.2, 0.4);
+
+        SetStr(1340, 1390);
+        SetDex(180, 230);
+        SetInt(1360, 1600);
+
+        SetHits(1800, 2500);
+
+        SetDamage(20, 35);
+
+        SetResistance(ResistanceType.Physical, 55, 65);
+        SetResistance(ResistanceType.Fire, 25, 30);
+        SetResistance(ResistanceType.Cold, 50, 60);
+        SetResistance(ResistanceType.Poison, 50, 60);
+        SetResistance(ResistanceType.Energy, 25, 30);
+
+        SetSkill(SkillName.EvalInt, 140, 140.0);
+        SetSkill(SkillName.Magery, 120, 120.0);
+        SetSkill(SkillName.MagicResist, 180.0, 180.0);
+        SetSkill(SkillName.Tactics, 100.0, 100.0);
+        SetSkill(SkillName.Wrestling, 100.0, 100.0);
+
+        Fame = 24000;
+        Karma = -24000;
+
+        PackReg(3);
+        PackItem(new Necklace());
+
+        if (Utility.RandomDouble() < 0.20)
+        {
+            PackItem(new PowderOfTemperament());
+        }
+    }
+
+    public override string CorpseName => "weird looking corpse";
+    public override string DefaultName => "Abomination of Mondain";
+    public override bool BleedImmune => true;
+    public override bool CanRummageCorpses => true;
+    public override int TreasureMapLevel => 4;
+
+    public override int GetDeathSound() => 0x288;
+
+    public override void GenerateLoot()
+    {
+        AddLoot(LootPack.FilthyRich);
+        AddLoot(LootPack.SuperBoss, 6);
+    }
+
+    // Cold wind: 2 damage a second for 5 seconds; a fresh hit restarts it.
+    public override void OnGaveMeleeAttack(Mobile defender, int damage)
+    {
+        base.OnGaveMeleeAttack(defender, damage);
+
+        if (Utility.RandomDouble() >= 0.1)
+        {
+            return;
+        }
+
+        if (_coldWinds.Remove(defender, out var running))
+        {
+            running.Stop();
+            defender.SendLocalizedMessage(1070831); // The freezing wind continues to blow!
+        }
+        else
+        {
+            defender.SendLocalizedMessage(1070832); // An icy wind surrounds you, freezing your lungs as you breathe!
+        }
+
+        var wind = new ColdWind(defender, this);
+        _coldWinds[defender] = wind;
+        wind.Start();
+    }
+
+    private class ColdWind : Timer
+    {
+        private readonly Mobile _mobile;
+        private readonly Mobile _from;
+
+        public ColdWind(Mobile m, Mobile from) : base(TimeSpan.FromSeconds(1.0), TimeSpan.FromSeconds(1.0), 5)
+        {
+            _mobile = m;
+            _from = from;
+        }
+
+        protected override void OnTick()
+        {
+            if (!_mobile.Alive)
+            {
+                Expire();
+                return;
+            }
+
+            _mobile.Damage(2, _from);
+
+            if (Index + 1 >= Count)
+            {
+                Expire();
+                _mobile.SendLocalizedMessage(1070830); // The icy wind dissipates.
+            }
+        }
+
+        private void Expire()
+        {
+            Stop();
+
+            if (_coldWinds.TryGetValue(_mobile, out var current) && current == this)
+            {
+                _coldWinds.Remove(_mobile);
+            }
+        }
+    }
+}
