+// DFI Network orcs, ported from DFI RunUO Scripts/Custom/Mobiles/Monsters/Humanoid/Melee/OrcChopper.cs
+// and OrcScout.cs. Both spare players wearing an orcish kin mask and burn the mask off whoever attacks
+// them in one.
+
+using System;
+using ModernUO.Serialization;
+using Server.Items;
+using Server.Misc;
+
+namespace Server.Mobiles;
+
+[SerializationGenerator(0)]
+public partial class OrcChopper : BaseCreature
+{
