+// kopia 2012's skill ball: pick seven skills; every skill is wiped and the seven are set to 100.
+[SerializationGenerator(0)]
+public partial class TemplateSkillBall : Item
+{
+    private const int Picks = 7;
+
+    // As on kopia, the "Tracking" box sets Peacemaking.
+    private static readonly (string Label, SkillName Skill)[] _choices =
+    [
+        ("Tactics", SkillName.Tactics), ("Anatomy", SkillName.Anatomy), ("Swordsmanship", SkillName.Swords),
+        ("Fencing", SkillName.Fencing), ("Archery", SkillName.Archery), ("Macefighting", SkillName.Macing),
+        ("Parry", SkillName.Parry), ("Arms Lore", SkillName.ArmsLore), ("Wrestling", SkillName.Wrestling),
+        ("Blacksmithing", SkillName.Blacksmith), ("Carpentry", SkillName.Carpentry), ("Tinkering", SkillName.Tinkering),
+        ("Tailoring", SkillName.Tailoring), ("Fishing", SkillName.Fishing), ("Cooking", SkillName.Cooking),
+        ("Fletching", SkillName.Fletching), ("Mining", SkillName.Mining), ("Lumberjacking", SkillName.Lumberjacking),
+        ("Alchemy", SkillName.Alchemy), ("Inscription", SkillName.Inscribe), ("Magery", SkillName.Magery),
+        ("Spirit Speak", SkillName.SpiritSpeak), ("Evaluating Intelligence", SkillName.EvalInt),
+        ("Meditation", SkillName.Meditation), ("Hiding", SkillName.Hiding), ("Stealth", SkillName.Stealth),
+        ("Snooping", SkillName.Snooping), ("Stealing", SkillName.Stealing), ("Lockpicking", SkillName.Lockpicking),
+        ("Detecting Hidden", SkillName.DetectHidden), ("Remove Trap", SkillName.RemoveTrap),
+        ("Tracking", SkillName.Peacemaking), ("Poisoning", SkillName.Poisoning), ("Animal Taming", SkillName.AnimalTaming),
+        ("Animal Lore", SkillName.AnimalLore), ("Camping", SkillName.Camping), ("Musicianship", SkillName.Musicianship),
+        ("Provocation", SkillName.Provocation), ("Peacemaking", SkillName.Peacemaking),
+        ("Item Identification", SkillName.ItemID), ("Taste Identification", SkillName.TasteID),
+        ("Foresic Evaluation", SkillName.Forensics), ("Begging", SkillName.Begging), ("Healing", SkillName.Healing),
+        ("Herding", SkillName.Herding), ("Resisting Spells", SkillName.MagicResist), ("Veterinary", SkillName.Veterinary),
+        ("Cartography", SkillName.Cartography)
+    ];
+
+    [Constructible]
+    public TemplateSkillBall() : base(0xE73)
+    {
+        Weight = 1.0;
+        Hue = 1161;
+        Movable = false;
+    }
+
+    public override string DefaultName => "skill ball";
+
+    public override void OnDoubleClick(Mobile m)
+    {
+        if (!IsChildOf(m.Backpack))
+        {
+            m.SendMessage(" You need to have the skill ball in your backpack.");
+            return;
+        }
+
+        m.SendMessage("Please choose  your 7 skills to set to 7x GM.");
+        m.CloseGump<SkillPickGump>();
+        m.SendGump(new SkillPickGump(this));
+    }
+
+    public void Apply(Mobile m, ReadOnlySpan<int> switches)
+    {
+        var skills = m.Skills;
+
+        for (var i = 0; i < skills.Length; ++i)
+        {
+            skills[i].Base = 0;
+        }
+
+        foreach (var s in switches)
+        {
+            if (s >= 0 && s < _choices.Length)
+            {
+                skills[_choices[s].Skill].Base = 100;
+            }
+        }
+
+        Delete();
+    }
+
+    private class SkillPickGump : DynamicGump
+    {
+        private readonly TemplateSkillBall _ball;
+
+        public SkillPickGump(TemplateSkillBall ball) : base(0, 0) => _ball = ball;
+
+        protected override void BuildLayout(ref DynamicGumpBuilder builder)
+        {
+            builder.AddPage();
+            builder.AddBackground(30, 25, 600, 480, 9200);
+            builder.AddLabel(67, 41, 1153, "Please select your 7 skills");
+
+            for (var i = 0; i < _choices.Length; i++)
+            {
+                var x = 55 + 185 * (i / 16);
+                var y = 65 + 25 * (i % 16);
+
+                builder.AddCheckbox(x, y, 210, 211, false, i);
+                builder.AddLabel(x + 25, y, 0, _choices[i].Label);
+            }
+
+            builder.AddButton(530, 470, 247, 248, 1);
+        }
+
+        public override void OnResponse(NetState state, in RelayInfo info)
+        {
+            var m = state.Mobile;
+
+            if (info.ButtonID != 1 || _ball.Deleted)
+            {
+                return;
+            }
+
+            if (info.Switches.Length < Picks)
+            {
+                m.SendGump(new SkillPickGump(_ball));
+                m.SendMessage(0, $"You must pick {Picks - info.Switches.Length} more skills.");
+            }
+            else if (info.Switches.Length > Picks)
+            {
+                m.SendGump(new SkillPickGump(_ball));
+                m.SendMessage(0, $"Please get rid of {info.Switches.Length - Picks} skills, you have exceeded the 7 skills that are allowed.");
+            }
+            else
+            {
+                _ball.Apply(m, info.Switches);
+            }
+        }
+    }
+}
