+// Sets strength, dexterity and intelligence, each 10-100, to totals equal to the stat cap.
+[SerializationGenerator(0)]
+public partial class StatBall : Item
+{
+    [Constructible]
+    public StatBall() : base(0xE73)
+    {
+        Movable = false;
+        Weight = 1.0;
+        Hue = 1153;
+        LootType = LootType.Blessed;
+    }
+
+    public override string DefaultName => "Stat ball";
+    public override bool DisplayLootType => false;
+
+    public override void OnDoubleClick(Mobile from)
+    {
+        if (!IsChildOf(from.Backpack))
+        {
+            from.SendLocalizedMessage(1042001); // That must be in your pack for you to use it.
+            return;
+        }
+
+        if (from is PlayerMobile)
+        {
+            from.SendGump(new StatBallGump(this, from.StatCap));
+        }
+    }
+
+    public bool TryApply(Mobile from, int str, int dex, int intel)
+    {
+        if (str + dex + intel != from.StatCap || str is < 10 or > 100 || dex is < 10 or > 100 || intel is < 10 or > 100)
+        {
+            from.SendMessage("Your choice totals are invalid.  Please try again!");
+            return false;
+        }
+
+        from.RawStr = str;
+        from.RawDex = dex;
+        from.RawInt = intel;
+        Delete();
+        return true;
+    }
+
+    private class StatBallGump : DynamicGump
+    {
+        private readonly StatBall _ball;
+        private readonly int _statCap;
+
+        public StatBallGump(StatBall ball, int statCap) : base(50, 50)
+        {
+            _ball = ball;
+            _statCap = statCap;
+        }
+
+        protected override void BuildLayout(ref DynamicGumpBuilder builder)
+        {
+            builder.SetNoResize();
+            builder.AddPage();
+            builder.AddBackground(60, 50, 430, 210, 9200);
+            builder.AddLabel(200, 67, 1160, "Stat Ball Selection");
+            builder.AddLabel(114, 96, 1160, "Choose your Strength, Dexterity, and Intelligence");
+            builder.AddLabel(84, 156, 1152, "STR");
+            builder.AddLabel(228, 156, 1152, "DEX");
+            builder.AddLabel(368, 156, 1152, "INT");
+            builder.AddTextEntry(134, 156, 50, 20, 1359, 0, "50");
+            builder.AddTextEntry(278, 156, 50, 20, 1359, 1, "50");
+            builder.AddTextEntry(411, 156, 50, 20, 1359, 2, "50");
+            builder.AddButton(405, 221, 238, 240, 4);
+            builder.AddLabel(114, 200, 1152, "* Stat totals should equal ");
+            builder.AddLabel(282, 200, 1152, $"{_statCap}");
+            builder.AddLabel(313, 200, 1152, "*");
+        }
+
+        public override void OnResponse(NetState sender, in RelayInfo info)
+        {
+            var from = sender.Mobile;
+
+            if (_ball.Deleted || info.ButtonID != 4)
+            {
+                return;
+            }
+
+            if (!int.TryParse(info.GetTextEntry(0), out var str))
+            {
+                from.SendMessage("Bad strength entry. A number was expected.");
+            }
+
+            if (!int.TryParse(info.GetTextEntry(1), out var dex))
+            {
+                from.SendMessage("Bad dexterity entry. A number was expected.");
+            }
+
+            if (!int.TryParse(info.GetTextEntry(2), out var intel))
+            {
+                from.SendMessage("Bad intelligence entry. A number was expected.");
+            }
+
+            if (str > 0 && dex > 0 && intel > 0)
+            {
+                _ball.TryApply(from, str, dex, intel);
+            }
+        }
+    }
+}
