+// Player deeds from the kopia 2012 RunUO shard (Scripts/Custom/Pozostale) and DFI RunUO
+// (Scripts/Custom/Items/Deeds). Where both shards had a deed, it follows DFI's rules with kopia's look.
+
+using System;
+using ModernUO.Serialization;
+using Server.Factions;
+using Server.Gumps;
