+// The shared shape of these deeds: blessed, in the pack to use, then a target or a gump.
+[SerializationGenerator(0)]
+public abstract partial class DfiDeed : Item
+{
+    public DfiDeed(int hue) : base(0x14F0)
+    {
+        Weight = 1.0;
+        Hue = hue;
+        LootType = LootType.Blessed;
+    }
+
+    public override bool DisplayLootType => false;
+
+    public override void OnDoubleClick(Mobile from)
+    {
+        if (!IsChildOf(from.Backpack))
+        {
+            from.SendLocalizedMessage(1042001); // That must be in your pack for you to use it.
+            return;
+        }
+
+        Use(from);
+    }
+
+    protected abstract void Use(Mobile from);
+
+    protected sealed class DeedTarget : Target
+    {
+        private readonly DfiDeed _deed;
+        private readonly Action<Mobile, object> _onTarget;
+
+        public DeedTarget(DfiDeed deed, int range, Action<Mobile, object> onTarget) : base(range, false, TargetFlags.None)
+        {
+            _deed = deed;
+            _onTarget = onTarget;
+        }
+
+        protected override void OnTarget(Mobile from, object targeted)
+        {
+            if (!_deed.Deleted && _deed.IsChildOf(from.Backpack))
+            {
+                _onTarget(from, targeted);
+            }
+        }
+    }
+}
