+        else
+        {
+            sash.Layer = Layer.Earrings;
+            sash.Name = sash.Name != null ? $"{sash.Name} [Layered]" : "a body sash [Layered]";
+            from.SendMessage("You layer the sash!");
+            Delete();
+        }
+    }
