+[SerializationGenerator(0)]
+public partial class SpellChannelingDeed : DfiDeed
+{
+    [Constructible]
+    public SpellChannelingDeed() : base(1175)
+    {
+    }
+
+    public override string DefaultName => "a Spell Channeling deed";
+
+    protected override void Use(Mobile from)
+    {
+        from.SendMessage("What item would you like to add spell channeling to?");
+        from.Target = new DeedTarget(this, 1, OnTarget);
+    }
+
+    private void OnTarget(Mobile from, object targeted)
+    {
+        var (attributes, kind) = targeted switch
+        {
+            BaseWeapon w => (w.Attributes, "weapon"),
+            BaseShield s => (s.Attributes, "shield"),
+            _            => (null, null)
+        };
+
+        if (attributes == null)
+        {
+            from.SendMessage("You cannot put spell channeling on that");
+        }
+        else if (attributes.SpellChanneling == 1)
+        {
+            from.SendMessage("That already has spell channeling!");
+        }
+        else if (((Item)targeted).RootParent != from)
+        {
+            from.SendMessage("You cannot put spell channeling on that!");
+        }
+        else
+        {
+            attributes.SpellChanneling = 1;
+            from.SendMessage($"You magically add spell channeling to your {kind}....");
+            Delete();
+        }
+    }
+}
