+// As on kopia, the deed is spent when the prompt opens, whatever is typed.
+[SerializationGenerator(0)]
+public partial class TitleChangeDeed : DfiDeed
+{
+    [Constructible]
+    public TitleChangeDeed() : base(0) => LootType = LootType.Regular;
+
+    public override string DefaultName => "Title change deed";
+
+    protected override void Use(Mobile from)
+    {
+        from.SendMessage("Enter your desired Title.");
+        from.Prompt = new RetitlePrompt();
+        Delete();
+    }
+
+    private class RetitlePrompt : Prompt
+    {
+        public override void OnResponse(Mobile from, string text)
+        {
+            text = text.Trim();
+
+            if (!NameVerification.Validate(text, 2, 16, true, true, true, 1, NameVerification.SpaceDashPeriodQuote))
+            {
+                return;
+            }
+
+            from.Title = text;
+            from.SendMessage($"Your Title be hence forth know as {text}");
+        }
+    }
+}
