+[SerializationGenerator(0)]
+public partial class PetResurrectionDeed : DfiDeed
+{
+    [Constructible]
+    public PetResurrectionDeed() : base(2216) => Weight = 0;
+
+    public override string DefaultName => "a pet Resurrection deed";
+
+    protected override void Use(Mobile from)
+    {
+        from.SendMessage("Choose the pet you wish to bring back to life.");
+        from.Target = new DeedTarget(this, 1, OnTarget);
+    }
+
+    private void OnTarget(Mobile from, object targeted)
+    {
+        if (targeted is not BaseCreature pet)
+        {
+            from.SendMessage("That is not a valid traget.");
+        }
+        else if (!pet.IsDeadPet)
+        {
+            from.SendMessage("That pet is already living!");
+        }
+        else if (pet.ControlMaster != from)
+        {
+            from.SendMessage("That is not your pet!");
+        }
+        else if (pet.Map?.CanFit(pet.Location, 16, false, false) != true)
+        {
+            from.SendLocalizedMessage(501042); // Target can not be resurrected at that location.
+        }
+        else if (from.InRange(pet, 3))
+        {
+            from.SendLocalizedMessage(503255); // You are able to resurrect the creature.
+            pet.PlaySound(0x214);
+            pet.FixedEffect(0x376A, 10, 16);
+            pet.ResurrectPet();
+            Delete();
+        }
+    }
+}
