+        {
+            builder.SetNoResize();
+            builder.AddPage();
+            builder.AddBackground(0, 0, 300, 110, 9200);
+            builder.AddLabel(28, 15, 255, "Changing sex involves intense magic.");
+            builder.AddLabel(28, 31, 255, "Your facial hair, if any, will dissapear.");
