+            builder.AddButton(130, 70, 4005, 4007, 0);
+            builder.AddLabel(182, 70, 255, "No");
+        }
+
+        public override void OnResponse(NetState state, in RelayInfo info)
+        {
+            var from = state.Mobile;
+
+            if (info.ButtonID != 1 || _deed.Deleted || from?.Backpack == null)
