+
+    private class ItemIDDeedGump : DynamicGump
+    {
+        private const int FirstSwitch = 50;
+        private readonly ItemIDDeed _deed;
+
+        public ItemIDDeedGump(ItemIDDeed deed) : base(0, 0) => _deed = deed;
+
+        protected override void BuildLayout(ref DynamicGumpBuilder builder)
+        {
+            builder.SetNoResize();
+            builder.AddPage();
+            builder.AddBackground(212, 21, 436, 576, 9270);
+            builder.AddImageTiled(216, 25, 428, 568, 9354);
+
+            for (var i = 0; i < _looks.Length; i++)
+            {
+                var x = i < 18 ? 232 : 454;
+                var y = 66 + 27 * (i < 18 ? i : i - 18);
+
+                builder.AddCheckbox(x, y, 10810, 10830, false, FirstSwitch + i);
+                builder.AddLabel(x + 36, y + 4, 27, _looks[i].Label);
+            }
+
+            builder.AddButton(271, 539, 10800, 10820, 1);
+            builder.AddLabel(304, 516, 1160, "START");
+        }
+
