+            }
+
+            if (info.Switches.Length != 1)
+            {
+                from.SendMessage(38, "You cant do this");
+                return;
+            }
+
+            var index = info.Switches[0] - FirstSwitch;
+
+            if (index < 0 || index >= _looks.Length)
+            {
+                return;
+            }
+
+            var itemID = _looks[index].ItemID;
+            var deed = _deed;
+            from.Target = new DeedTarget(deed, -1, (m, t) => deed.OnTarget(m, t, itemID));
+        }
+    }
