+            if (info.ButtonID < 1 || info.ButtonID > _books.Length || _deed.Deleted || !_deed.IsChildOf(from.Backpack))
+            {
+                return;
+            }
+
+            from.AddToBackpack(_books[info.ButtonID - 1].Create());
+            _deed.Delete();
+        }
+    }
+}
