+// Artifact, champion artifact and minor artifact deeds: the user picks one item from a category list
+// and receives it blessed. The lists and labels are kopia 2012's, its mismatched labels included.
+[SerializationGenerator(0)]
+public abstract partial class ArtifactChoiceDeed : DfiDeed
+{
+    public ArtifactChoiceDeed(int hue) : base(hue)
+    {
+    }
+
+    protected abstract string Title { get; }
+    protected abstract (string Category, (string Label, Type Type)[] Items)[] Choices { get; }
+
+    protected override void Use(Mobile from)
+    {
+        from.CloseGump<ArtifactChoiceGump>();
+        from.SendGump(new ArtifactChoiceGump(this));
+    }
+
+    private void Give(Mobile from, Type type)
+    {
+        if (type.CreateInstance<Item>() is not { } item)
+        {
+            return;
+        }
+
+        item.LootType = LootType.Blessed;
+        from.AddToBackpack(item);
+        Delete();
+    }
+
+    private class ArtifactChoiceGump : DynamicGump
+    {
+        private readonly ArtifactChoiceDeed _deed;
+
+        public ArtifactChoiceGump(ArtifactChoiceDeed deed) : base(0, 0) => _deed = deed;
+
+        protected override void BuildLayout(ref DynamicGumpBuilder builder)
+        {
+            var choices = _deed.Choices;
+
+            builder.AddPage();
+            builder.AddBackground(0, 0, 300, 400, 9200);
+            builder.AddLabel(40, 12, 0, _deed.Title);
+
+            for (var c = 0; c < choices.Length; c++)
+            {
+                builder.AddButton(12, 40 + 20 * c, 4005, 4007, 0, GumpButtonType.Page, c + 1);
+                builder.AddLabel(52, 40 + 20 * c, 0, choices[c].Category);
+            }
+
+            builder.AddButton(12, 340, 4017, 4019, 0);
+            builder.AddLabel(52, 340, 0, "Close");
+
+            var button = 1;
+
+            for (var c = 0; c < choices.Length; c++)
+            {
+                builder.AddPage(c + 1);
+                builder.AddBackground(0, 0, 300, 400, 9200);
+                builder.AddLabel(40, 12, 0, choices[c].Category);
+
+                var items = choices[c].Items;
+
+                for (var i = 0; i < items.Length; i++)
+                {
+                    builder.AddButton(12, 40 + 20 * i, 4005, 4007, button++);
+                    builder.AddLabel(52, 40 + 20 * i, 0, items[i].Label);
+                }
+
+                builder.AddButton(12, 360, 4014, 4016, 0, GumpButtonType.Page, 0);
+                builder.AddLabel(52, 360, 0, "Back");
+            }
+        }
+
+        public override void OnResponse(NetState state, in RelayInfo info)
+        {
+            var from = state.Mobile;
+
+            if (info.ButtonID <= 0 || _deed.Deleted || !_deed.IsChildOf(from.Backpack))
+            {
+                return;
+            }
+
+            var index = info.ButtonID - 1;
+
+            foreach (var (_, items) in _deed.Choices)
+            {
+                if (index < items.Length)
+                {
+                    _deed.Give(from, items[index].Type);
+                    return;
+                }
+
+                index -= items.Length;
+            }
+        }
+    }
+}
+
