+// Runic tools from the kopia 2012 RunUO shard (Scripts/Custom/Runic Tools): ready-made runic hammers,
+// saws, fletcher and tinker tools in eight metals and sewing kits in three leathers, their bags and the
+// two stones that hand the bags out. The Valorite and Barbed tools carry 5000 uses, the rest 50.
+
+using ModernUO.Serialization;
+using Server.Engines.Craft;
+
+namespace Server.Items;
+
+[Flippable(0x13E4, 0x13E3)]
+[SerializationGenerator(0)]
+public abstract partial class RunicHammer1 : BaseRunicTool
+{
+    public RunicHammer1(CraftResource resource, int uses) : base(resource, uses, 0x13E3) =>
+        Hue = CraftResources.GetHue(resource);
+
+    public override double DefaultWeight => 8.0;
+    public override CraftSystem CraftSystem => DefBlacksmithy.CraftSystem;
+
+    public override void AddNameProperties(IPropertyList list)
+    {
+        base.AddNameProperties(list);
+
+        var index = CraftResources.GetIndex(Resource);
+
+        if (index is >= 1 and <= 8 || CraftResources.IsStandard(Resource))
+        {
+            return;
+        }
+
+        var num = CraftResources.GetLocalizationNumber(Resource);
+
+        if (num > 0)
+        {
+            list.Add(num);
+        }
+        else
+        {
+            list.Add(CraftResources.GetName(Resource));
+        }
+    }
+}
