diff --git a/Projects/UOContent.Tests/Tests/Custom/DfiSpawnTests.cs b/Projects/UOContent.Tests/Tests/Custom/DfiSpawnTests.cs
new file mode 100644
index 000000000..74ff48cb1
--- /dev/null
+++ b/Projects/UOContent.Tests/Tests/Custom/DfiSpawnTests.cs
@@ -0,0 +1,77 @@
+using System.Collections.Generic;
+using System.IO;
+using System.Text.Json;
+using Server;
+using Server.Engines.Spawners;
+using Xunit;
+
+namespace UOContent.Tests.Custom;
+
+[Collection("Sequential UOContent Tests")]
+public class DfiSpawnTests
+{
+    private static string SpawnRoot => Path.Combine(Core.BaseDirectory, "Data", "Spawns");
+
+    private static List<SpawnerDto> Load(string relative) =>
+        JsonSerializer.Deserialize<List<SpawnerDto>>(
+            File.ReadAllText(Path.Combine(SpawnRoot, relative)),
+            SpawnerJsonSerializer.Options
+        );
+
+    [Theory]
+    [InlineData("dfi/felucca.json", 900)]
+    [InlineData("dfi/ilshenar.json", 300)]
+    [InlineData("dfi/malas.json", 130)]
+    [InlineData("dfi/dfi-boss-arena.json", 13)]
+    [InlineData("dfi/kopia-faction-extras.json", 13)]
+    [InlineData("dfi/dfi-custom-monsters.json", 12)]
+    [InlineData("dfi/dfi-town-rares.json", 4)]
+    public void DfiSpawnFile_LoadsAtLeastTheConvertedSpawners(string file, int minimum)
+    {
+        var dtos = Load(file);
+
+        Assert.True(dtos.Count >= minimum, $"{file}: {dtos.Count} spawners, expected at least {minimum}");
+        Assert.All(dtos, d => Assert.NotEmpty(d.EntryView));
+    }
+
+    // The importer replaces a same-type spawner on the same tile, so a hand-placed spawner sharing a tile
+    // with a layout spawner silently disappears when the layout file loads after it.
+    [Fact]
+    public void DfiCustomSpawners_ShareNoTileWithTheLayouts()
+    {
+        var taken = new HashSet<(string, Point3D)>();
+
+        foreach (var file in new[] { "felucca", "ilshenar", "malas", "dfi-boss-arena", "kopia-faction-extras" })
+        {
+            foreach (var dto in Load($"dfi/{file}.json"))
+            {
+                taken.Add((dto.Map.Name, dto.Location));
+            }
+        }
+
+        foreach (var placed in new[] { "dfi-custom-monsters", "dfi-town-rares" })
+        {
+            Assert.All(
+                Load($"dfi/{placed}.json"),
+                dto => Assert.False(taken.Contains((dto.Map.Name, dto.Location)), $"{placed}: {dto.Location} is already a layout spawner")
+            );
+        }
+    }
+
+    [Fact]
+    public void DfiSpawnSwap_EveryReplacedFileExists()
+    {
+        var replaced = (string[])typeof(Server.Custom.Dfi.DfiSpawnSwap)
+            .GetField("_replaced", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Static)!
+            .GetValue(null);
+
+        Assert.All(
+            replaced,
+            name => Assert.True(
+                File.Exists(Path.Combine(SpawnRoot, "shared", $"{name}.json")) ||
+                File.Exists(Path.Combine(SpawnRoot, "post-uoml", $"{name}.json")),
+                $"{name}.json is in neither shared nor post-uoml"
+            )
+        );
+    }
+}
diff --git a/Projects/UOContent/Custom/DFI/Spawns/DfiSpawnSwap.cs b/Projects/UOContent/Custom/DFI/Spawns/DfiSpawnSwap.cs
new file mode 100644
index 000000000..54c43e5ee
--- /dev/null
+++ b/Projects/UOContent/Custom/DFI/Spawns/DfiSpawnSwap.cs
@@ -0,0 +1,193 @@
+// [DfiSpawns swaps ModernUO's classic monster and wildlife spawners on Felucca, Ilshenar and Malas for the
+// DFI Network layouts (DFI's 2008 ESpawner exports) and the staff-placed setups recovered from the DFI and
+// kopia 2012 world saves, all in Data/Spawns/dfi. Vendors, townspeople, reagents, sea life and the newer
+// Mondain's Legacy areas stay, since DFI's layouts have none of them. Running it again changes nothing:
+// the replaced spawners are found by guid and the DFI ones re-import onto their own guids.
+
+using System;
+using System.Collections.Generic;
+using System.IO;
+using System.Text.Json;
+using Server.Commands;
+using Server.Engines.Spawners;
+using Server.Logging;
+
+namespace Server.Custom.Dfi;
+
+public static class DfiSpawnSwap
+{
+    private static readonly ILogger logger = LogFactory.GetLogger(typeof(DfiSpawnSwap));
+
+    private static readonly string[] _replaced =
+    [
+        "felucca/BritainSewer", "felucca/Covetous", "felucca/Deceit", "felucca/Despise", "felucca/Destard",
+        "felucca/FelCropsLS", "felucca/Fire", "felucca/Graveyards", "felucca/Hythloth", "felucca/Ice",
+        "felucca/Khaldun", "felucca/LostLands", "felucca/OrcCaves", "felucca/Outdoors", "felucca/PaintedCaves",
+        "felucca/Shame", "felucca/SolenHive", "felucca/TerathanKeep", "felucca/TownsLife",
+        "felucca/TrinsicPassage", "felucca/WildLife", "felucca/Wrong",
+        "ilshenar/Ancientlair", "ilshenar/Ankh", "ilshenar/Blood", "ilshenar/Exodus", "ilshenar/Outdoors",
+        "ilshenar/Ratmancave", "ilshenar/Rock", "ilshenar/Sorcerers", "ilshenar/Spectre", "ilshenar/Towns",
+        "ilshenar/Wisp",
+        "malas/Doom", "malas/North", "malas/OrcForts", "malas/South"
+    ];
+
+    private static readonly string[] _eras = ["shared", "post-uoml", "uoml"];
+
+    // Setups the owner chose not to run; their spawners, and what they spawned, are removed.
+    private static readonly string[] _retiredNamePrefixes = ["kopia-free-items"];
+
+    public static void Configure()
+    {
+        CommandSystem.Register("DfiSpawns", AccessLevel.Administrator, OnCommand);
+    }
+
+    [Usage("DfiSpawns")]
+    [Description("Replaces the classic world spawners on Felucca, Ilshenar and Malas with DFI Network's.")]
+    private static void OnCommand(CommandEventArgs e)
+    {
+        var from = e.Mobile;
+        var guids = ReplacedGuids();
+
+        var doomed = new List<Item>();
+
+        foreach (var item in World.Items.Values)
+        {
+            if (item is ISpawner spawner && (guids.Contains(spawner.Guid) || IsRetired(item.Name)))
+            {
+                doomed.Add(item);
+            }
+        }
+
+        foreach (var item in doomed)
+        {
+            item.Delete();
+        }
+
+        from.SendMessage($"DfiSpawns: removed {doomed.Count} classic spawners ({guids.Count} listed).");
+        logger.Information("{User} removed {Count} classic spawners for the DFI layouts", from, doomed.Count);
+
+        CommandSystem.Handle(from, $"{CommandSystem.Prefix}GenerateSpawners Data/Spawns/dfi/*.json");
+        ReportCustomSpawns(from);
+        ReportRares(from);
+    }
+
+    private static void ReportRares(Mobile from)
+    {
+        var byType = new SortedDictionary<string, int>();
+        int spawners = 0, filled = 0;
+
+        foreach (var item in World.Items.Values)
+        {
+            if (item is Server.Items.IStealable && item.Parent == null)
+            {
+                var name = item.GetType().Name;
+                byType[name] = byType.GetValueOrDefault(name) + 1;
+            }
+            else if (item is BaseSpawner spawner)
+            {
+                var holdsRare = false;
+
+                foreach (var entry in spawner.Entries)
+                {
+                    var type = AssemblyHandler.FindTypeByName(entry.SpawnedName);
+
+                    if (type != null && typeof(Server.Items.IStealable).IsAssignableFrom(type))
+                    {
+                        holdsRare = true;
+                        break;
+                    }
+                }
+
+                if (holdsRare)
+                {
+                    spawners++;
+
+                    if (spawner.Spawned?.Count > 0)
+                    {
+                        filled++;
+                    }
+                }
+            }
+        }
+
+        var total = 0;
+
+        foreach (var (name, count) in byType)
+        {
+            total += count;
+            logger.Information("rare {Name}: {Count} on the ground", name, count);
+        }
+
+        logger.Information("{Total} rares on the ground; {Filled}/{Spawners} rare spawners holding one", total, filled, spawners);
+        from.SendMessage($"DfiSpawns: {total} rares on the ground; {filled}/{spawners} rare spawners holding one.");
+    }
+
+    // The custom-monster spawners were placed by hand; one that spawned nothing sits where nothing can stand.
+    private static void ReportCustomSpawns(Mobile from)
+    {
+        foreach (var item in World.Items.Values)
+        {
+            if (item is BaseSpawner spawner && spawner.Name?.StartsWith("dfi-custom", StringComparison.Ordinal) == true)
+            {
+                var spawned = spawner.Spawned?.Count ?? 0;
+                logger.Information(
+                    "{Name} at {Location} ({Map}): {Spawned}/{Count} spawned",
+                    spawner.Name,
+                    spawner.Location,
+                    spawner.Map,
+                    spawned,
+                    spawner.Count
+                );
+                from.SendMessage($"{spawner.Name}: {spawned}/{spawner.Count} spawned");
+            }
+        }
+    }
+
+    private static bool IsRetired(string name)
+    {
+        if (name == null)
+        {
+            return false;
+        }
+
+        foreach (var prefix in _retiredNamePrefixes)
+        {
+            if (name.StartsWith(prefix, StringComparison.Ordinal))
+            {
+                return true;
+            }
+        }
+
+        return false;
+    }
+
+    private static HashSet<Guid> ReplacedGuids()
+    {
+        var guids = new HashSet<Guid>();
+
+        foreach (var era in _eras)
+        {
+            foreach (var name in _replaced)
+            {
+                var path = Path.Combine(Core.BaseDirectory, "Data", "Spawns", era, $"{name}.json");
+
+                if (!File.Exists(path))
+                {
+                    continue;
+                }
+
+                using var doc = JsonDocument.Parse(File.ReadAllText(path));
+
+                foreach (var spawner in doc.RootElement.EnumerateArray())
+                {
+                    if (spawner.TryGetProperty("guid", out var g) && Guid.TryParse(g.GetString(), out var guid))
+                    {
+                        guids.Add(guid);
+                    }
+                }
+            }
+        }
+
+        return guids;
+    }
+}
MUO_EOF_0
chmod 0644 $BASE/patches/0010-dfi-spawns.patch
install -d "$(dirname $BASE/patches/0011-dfi-rares.patch)"
cat > $BASE/patches/0011-dfi-rares.patch <<'MUO_EOF_0'
diff --git a/Projects/UOContent.Tests/Tests/Custom/DfiRareTests.cs b/Projects/UOContent.Tests/Tests/Custom/DfiRareTests.cs
new file mode 100644
index 000000000..b4f06a7c3
--- /dev/null
+++ b/Projects/UOContent.Tests/Tests/Custom/DfiRareTests.cs
@@ -0,0 +1,114 @@
+using System;
+using System.Collections.Generic;
+using Server;
+using Server.Custom.Dfi;
+using Server.Items;
+using Server.Misc;
+using Server.Mobiles;
+using Xunit;
+
+namespace UOContent.Tests.Custom;
+
+[Collection("Sequential UOContent Tests")]
+public class DfiRareTests : IDisposable
+{
+    private readonly List<IEntity> _created = new();
+
+    // The shared test server never runs the skill system's start-up, which installs the skill checks.
+    public DfiRareTests() => SkillCheck.Initialize();
+
+    public static TheoryData<Type> Rares =>
+    [
+        typeof(SRDriedOnions), typeof(SRDriedHerbs), typeof(SRDriedFlowers), typeof(SRHorseShoes), typeof(SRArrowShafts),
+        typeof(SREIronWire), typeof(SRESilverWire), typeof(SREGoldWire), typeof(SRECopperWire), typeof(SRDRBloodyWater),
+        typeof(SRDRCocoon), typeof(SRDRDamagedBooks), typeof(SRDRRuinedBooks), typeof(SRDRBottle), typeof(SRDRBrazier),
+        typeof(SRDRLampPost), typeof(SRDRRuinedPainting), typeof(SRDRSaddle), typeof(SRDRTarot), typeof(SRDREggCase),
+        typeof(SRDRGruesomeStandard), typeof(SRDRHangingLeatherTunic), typeof(SRDRHangingStuddedLeggings),
+        typeof(SRDRHangingStuddedTunic), typeof(SRDRRock), typeof(SRDRSkinnedDeer), typeof(SRDRSkinnedGoat),
+        typeof(SRDRSkullCandle), typeof(SRDRStackedBooks2), typeof(SRDRStackedBooks), typeof(SRDRStretchedHide),
+        typeof(SRDRReversedBackPack)
+    ];
+
+    public void Dispose()
+    {
+        foreach (var e in _created)
+        {
+            e?.Delete();
+        }
+
+        _created.Clear();
+    }
+
+    private T Track<T>(T e) where T : IEntity
+    {
+        _created.Add(e);
+        return e;
+    }
+
+    private PlayerMobile Thief(double stealing)
+    {
+        var m = Track(new PlayerMobile(World.NewMobile));
+        m.DefaultMobileInit();
+        m.MoveToWorld(new Point3D(1500, 1600, 0), Map.Felucca);
+        m.AddItem(new Backpack());
+        m.Skills.Stealing.Base = stealing;
+        return m;
+    }
+
+    [Theory]
+    [MemberData(nameof(Rares))]
+    public void Rare_SpawnsFixedAndStealable(Type type)
+    {
+        var item = Track(type.CreateInstance<Item>());
+
+        Assert.False(item.Movable);
+        Assert.IsAssignableFrom<IStealable>(item);
+        Assert.True(((IStealable)item).GetMin() >= 80.0);
+    }
+
+    [Fact]
+    public void Steal_BelowTheRaresMinimum_IsRefusedAndLeavesItFixed()
+    {
+        var thief = Thief(90.0);
+        var rare = Track(new SRDRTarot());
+        rare.MoveToWorld(new Point3D(1501, 1600, 0), Map.Felucca);
+
+        Assert.Null(DfiRares.Steal(thief, rare, rare));
+        Assert.False(rare.Movable);
+    }
+
+    [Fact]
+    public void Steal_AtTheTopOfTheWindow_AlwaysSucceedsAndFreesTheRare()
+    {
+        var thief = Thief(100.0);
+        var rare = Track(new SRDriedOnions());
+        rare.MoveToWorld(new Point3D(1501, 1600, 0), Map.Felucca);
+
+        Assert.Same(rare, DfiRares.Steal(thief, rare, rare));
+        Assert.True(rare.Movable);
+    }
+
+    [Fact]
+    public void Steal_OutOfReach_IsRefused()
+    {
+        var thief = Thief(100.0);
+        var rare = Track(new SRDriedOnions());
+        rare.MoveToWorld(new Point3D(1510, 1600, 0), Map.Felucca);
+
+        Assert.Null(DfiRares.Steal(thief, rare, rare));
+    }
+
+    [Fact]
+    public void LockedFruitBasket_EatenLeavesAnEmptyBasket()
+    {
+        var m = Thief(0);
+        m.Hunger = 0;
+        var basket = Track(new LockedFruitBasket());
+        basket.MoveToWorld(new Point3D(1501, 1600, 0), Map.Felucca);
+
+        basket.OnDoubleClick(m);
+
+        Assert.True(basket.Deleted);
+        Assert.True(m.Hunger > 0);
+    }
+}
diff --git a/Projects/UOContent/Custom/DFI/Items/DfiRares.cs b/Projects/UOContent/Custom/DFI/Items/DfiRares.cs
new file mode 100644
index 000000000..d1c6eb1cc
--- /dev/null
+++ b/Projects/UOContent/Custom/DFI/Items/DfiRares.cs
@@ -0,0 +1,42 @@
+using Server.Items;
+
+namespace Server.Custom.Dfi;
+
+public static class DfiRares
+{
+    // A fixed rare on the ground: the thief needs the rare's minimum skill to try at all, succeeds by
+    // a skill check across its min..max window, and on success the rare becomes an ordinary item.
+    // The spawner that placed it counts it gone once it is in a backpack and puts a new one back.
+    public static Item Steal(Mobile thief, Item item, IStealable rare)
+    {
+        if (!thief.InRange(item.GetWorldLocation(), 1))
+        {
+            thief.SendLocalizedMessage(502703); // You must be standing next to an item to steal it.
+            return null;
+        }
+
+        if (thief.Backpack?.CheckHold(thief, item, false, true) != true)
+        {
+            thief.SendLocalizedMessage(1048147); // Your backpack can't hold anything else.
+            return null;
+        }
+
+        if (thief.Skills.Stealing.Value < rare.GetMin())
+        {
+            // You're not skilled enough to attempt the theft of this item.
+            thief.SendLocalizedMessage(1060025, "", 0x66D);
+            return null;
+        }
+
+        if (!thief.CheckTargetSkill(SkillName.Stealing, item, rare.GetMin(), rare.GetMax()))
+        {
+            thief.SendLocalizedMessage(502723); // You fail to steal the item.
+            return null;
+        }
+
+        thief.SendLocalizedMessage(502724); // You successfully steal the item.
+        item.Movable = true;
+        rare.OnSteal();
+        return item;
+    }
+}
