diff --git a/Projects/UOContent/Custom/DFI/CursedCave/CursedCave.cs b/Projects/UOContent/Custom/DFI/CursedCave/CursedCave.cs
new file mode 100644
index 000000000..da6e13d4d
--- /dev/null
+++ b/Projects/UOContent/Custom/DFI/CursedCave/CursedCave.cs
@@ -0,0 +1,208 @@
+// DFI Network's Cursed Cave, ported from DFI RUNUO Scripts/Custom/Engines/Quest System/CursedCave
+// (CursedCaveUtility.cs, CursedCaveSpeech.cs) and the helpers it borrowed from
+// DFI's core: Notoriety.GetNotorietyByLevel, Teleporter.Teleport, BoneRemains.PackSkullsAndSmallBones.
+
+using System;
+using Server.Items;
+using Server.Misc;
+using Server.Mobiles;
+using Server.Network;
+
+namespace Server.Custom.Dfi;
+
+public static class CursedCave
+{
+    // DFI's Notoriety.GetNotorietyByLevel: fame or karma for a level from -6 to 6, randomised within it.
+    public static int FameByLevel(int level)
+    {
+        level = Math.Clamp(level, -6, 6);
+        var random = Utility.Random(5000) * (level < 0 ? -1 : 1);
+        return 5000 * level + random;
+    }
+
+    // The cave's gear rolls 1 to 5 properties at 20-100% intensity, with the given luck in percent.
+    public static Item MutateItem(Item item, int percentValue) =>
+        DfiLoot.Mutate(item, Utility.RandomMinMax(1, 5), 20, 100, percentValue * 100);
+
+    public static void PackSkullsAndSmallBones(Container c, int amount)
+    {
+        if (c == null)
+        {
+            return;
+        }
+
+        for (var i = 0; i < amount; i++)
+        {
+            var bone = Utility.RandomBool()
+                ? new Item(Utility.Random(0x1AE0, 5)) { Name = "a skull" }
+                : new Item(Utility.Random(0x1B13, 10)) { Name = "bones" };
+
+            bone.Weight = 0.1;
+            c.DropItem(bone);
+        }
+    }
+
+    // DFI's Teleporter.Teleport: players only, pets follow when allowed, and the sound plays at both ends.
+    public static bool Teleport(
+        Mobile m, bool active, Point3D loc, Map destMap, bool allowPets, string teleName, int soundID = 0x228
+    )
+    {
+        if (!m.Player)
+        {
+            return false;
+        }
+
+        if (!active)
+        {
+            if (!string.IsNullOrEmpty(teleName))
+            {
+                m.SendLocalizedMessage(1042753, $"The {teleName}"); // ~1_SOMETHING~ has been temporarily disabled.
+            }
+
+            return false;
+        }
+
+        var map = destMap == null || destMap == Map.Internal ? m.Map : destMap;
+        var p = loc == Point3D.Zero ? m.Location : loc;
+        var sendEffect = !m.Hidden || m.AccessLevel == AccessLevel.Player;
+
+        if (sendEffect)
+        {
+            TeleEffect(m, soundID);
+        }
+
+        if (allowPets)
+        {
+            BaseCreature.TeleportPets(m, p, map);
+        }
+        else if (m.Followers > 0)
+        {
+            m.SendMessage("Your pets cannot follow you...");
+        }
+
+        m.MoveToWorld(p, map);
+
+        if (sendEffect)
+        {
+            TeleEffect(m, soundID);
+        }
+
+        return true;
+    }
+
+    private static void TeleEffect(Mobile m, int soundID)
+    {
+        Effects.SendLocationParticles(
+            EffectItem.Create(m.Location, m.Map, EffectItem.DefaultDuration),
+            0x3728,
+            10,
+            10,
+            2023
+        );
+        m.PlaySound(soundID);
+    }
+
+    public static void PrivateMessage(Mobile from, string message)
+    {
+        from.PrivateOverheadMessage(MessageType.Regular, 0x3B2, false, message, from.NetState);
+    }
+
+    public enum TriggerCheck
+    {
+        All,
+        None,
+        LongswordOfJustice,
+        HarvesterOfTheGhost,
+        BowOfHephaestus
+    }
+
+    public static bool HasTalkingWeapon(Mobile from, out string weaponName, TriggerCheck type)
+    {
+        weaponName = from.Weapon switch
+        {
+            HarvesterOfTheGhost when type is TriggerCheck.HarvesterOfTheGhost or TriggerCheck.All => "Harvester Of The Ghost",
+            LongswordOfJustice when type is TriggerCheck.LongswordOfJustice or TriggerCheck.All   => "Longsword Of Justice",
+            BowOfHephaestus when type is TriggerCheck.BowOfHephaestus or TriggerCheck.All         => "Bow Of Hephaestus",
+            _                                                                                    => null
+        };
+
+        return weaponName != null;
+    }
+
+    public static void WeaponSpeak(Mobile attacker, Mobile defender, string weaponName)
+    {
+        var line = defender switch
+        {
+            BaseCreature => Utility.Random(8) switch
+            {
+                0 => "I never liked these creatures!",
+                1 => "Slay all of them!",
+                2 => "Take that foul creature!",
+                3 => "I will slay you all!",
+                4 => "Die foul creature!",
+                5 => $"Lets kill them all master {attacker.Name}!",
+                6 => "Die die die!",
+                _ => $"Nice hit master {attacker.Name}!"
+            },
+            PlayerMobile => Utility.Random(4) switch
+            {
+                0 => $"My master {attacker.Name} will kill you foul human!",
+                1 => "Die human scum!",
+                2 => "Die die die!",
+                _ => $"Nice hit master {attacker.Name}!"
+            },
+            _ => "Take that!"
+        };
+
+        PrivateMessage(attacker, $"{weaponName}: {line}");
+    }
+
+    public static string WeaponChatter(Mobile from) =>
+        Utility.Random(6) switch
+        {
+            0 => $"I will serve thee well master {from.Name}.",
+            1 => $"Lets go kill something master {from.Name}!",
+            2 => $"Lets slay some cursed creatures master {from.Name}!",
+            3 => $"Nice day today master {from.Name}.",
+            4 => "Im bored.",
+            _ => "Lets go to the cursed cave."
+        };
+
+    private static InhumanSpeech _cursedSpeech;
+
+    public static InhumanSpeech Speech =>
+        _cursedSpeech ??= new InhumanSpeech
+        {
+            Hue = 472,
+            Sound = 432,
+            Flags = IHSFlags.All,
+            Keywords =
+            [
+                "meat", "gold", "kill", "killing", "slay", "sword", "axe", "spell", "magic", "spells", "swords",
+                "axes", "mace", "maces", "monster", "monsters", "food", "run", "escape", "away", "help", "dead",
+                "die", "dying", "lose", "losing", "life", "lives", "death", "ghost", "ghosts", "british",
+                "blackthorn", "guild", "guilds", "dragon", "dragons", "game", "games", "ultima", "silly", "stupid",
+                "dumb", "idiot", "idiots", "cheesy", "cheezy", "crazy", "dork", "jerk", "fool", "foolish", "ugly",
+                "insult", "scum"
+            ],
+            Responses =
+            [
+                "meat", "kill", "pound", "crush", "yum yum", "crunch", "destroy", "murder", "eat", "munch",
+                "massacre", "food", "monster", "evil", "run", "die", "lose", "dumb", "idiot", "fool", "crazy",
+                "dinner", "lunch", "breakfast", "fight", "battle", "doomed", "rip apart", "tear apart", "smash",
+                "edible?", "shred", "disembowel", "ugly", "smelly", "stupid", "hideous", "smell", "tasty", "invader",
+                "attack", "raid", "plunder", "pillage", "treasure", "loser", "lose", "scum"
+            ],
+            Syllables =
+            [
+                "skrit", "ch", "ch", "it", "ti", "it", "ti", "ak", "ek", "ik", "ok", "uk", "yk", "ka", "ke", "ki",
+                "ko", "ku", "ky", "at", "et", "it", "ot", "ut", "yt", "cha", "che", "chi", "cho", "chu", "chy",
+                "ach", "ech", "ich", "och", "uch", "ych", "att", "ett", "itt", "ott", "utt", "ytt", "tat", "tet",
+                "tit", "tot", "tut", "tyt", "tta", "tte", "tti", "tto", "ttu", "tty", "tak", "tek", "tik", "tok",
+                "tuk", "tyk", "ack", "eck", "ick", "ock", "uck", "yck", "cka", "cke", "cki", "cko", "cku", "cky",
+                "rak", "rek", "rik", "rok", "ruk", "ryk", "tcha", "tche", "tchi", "tcho", "tchu", "tchy", "rach",
+                "rech", "rich", "roch", "ruch", "rych", "rrap", "rrep", "rrip", "rrop", "rrup", "rryp", "ccka",
+                "ccke", "ccki", "ccko", "ccku", "ccky"
+            ]
+        };
+}
diff --git a/Projects/UOContent/Custom/DFI/CursedCave/CursedCaveGen.cs b/Projects/UOContent/Custom/DFI/CursedCave/CursedCaveGen.cs
new file mode 100644
index 000000000..839ce8f89
--- /dev/null
+++ b/Projects/UOContent/Custom/DFI/CursedCave/CursedCaveGen.cs
@@ -0,0 +1,172 @@
+// Places the Cursed Cave's fixtures. DFI's live placements did not survive in any of its saves, so this
+// layout is GUO's: the entrance and Warren's post north of Minoc Mines, where DFI's hint gump put the cave;
+// walk-on passages and keyword doors between the levels; and Hephaestus' chamber sealed in level 3's
+// south-west dead end. The cave's creatures and rares come from Data/Spawns/dfi/dfi-cursed-cave.json.
+
+using System.Collections.Generic;
+using Server.Commands;
+using Server.Engines.Quests.CursedCave;
+using Server.Items;
+using Server.Logging;
+
+namespace Server.Custom.Dfi;
+
+public static class CursedCaveGen
+{
+    private static readonly ILogger logger = LogFactory.GetLogger(typeof(CursedCaveGen));
+
+    public static readonly Point3D Entrance = new(2548, 288, 15);
+    public static readonly Point3D OutsideArrival = new(2546, 288, 15);
+    public static readonly Point3D WarrenSpot = new(2543, 286, 15);
+
+    public static readonly Point3D Level1Arrival = new(6038, 280, 0);
+    public static readonly Point3D Level1Exit = new(6036, 276, 0);
+
+    public static readonly Point3D Level1Door = new(6068, 362, 22);
+    public static readonly Point3D Level1DoorArrival = new(6064, 358, 22);
+    public static readonly Point3D Level2Door = new(6090, 362, 0);
+    public static readonly Point3D Level2DoorArrival = new(6092, 358, 0);
+
+    public static readonly Point3D Level2Down = new(6118, 284, 22);
+    public static readonly Point3D Level2UpArrival = new(6114, 286, 22);
+    public static readonly Point3D Level3Arrival = new(5140, 1436, 0);
+    public static readonly Point3D Level3Up = new(5135, 1440, 0);
+
+    public static readonly Point3D ChamberDoor = new(5155, 1495, 0);
+    public static readonly Point3D ChamberArrival = new(5155, 1499, 0);
+    public static readonly Point3D ChamberAltar = new(5155, 1506, 20);
+    public static readonly Point3D ChamberExit = new(5158, 1510, 0);
+    public static readonly Point3D ChamberExitArrival = new(5155, 1491, 0);
+    public static readonly Rectangle2D Chamber = new(5150, 1496, 12, 17);
+
+    private const string DoorKeyword = "hephaestus";
+    private const string DoorQuestion = "Speak the name of the god of fire, and the door shall open.";
+
+    public static void Configure()
+    {
+        CommandSystem.Register("CursedCave", AccessLevel.Administrator, OnCommand);
+    }
+
+    [Usage("CursedCave")]
+    [Description("Places the Cursed Cave's entrance, guard, passages, doors and Hephaestus' altar, replacing any placed before.")]
+    private static void OnCommand(CommandEventArgs e)
+    {
+        var removed = Remove();
+        var placed = Place();
+        e.Mobile.SendMessage($"CursedCave: removed {removed} fixtures, placed {placed}.");
+        logger.Information("{User} placed {Placed} Cursed Cave fixtures ({Removed} removed)", e.Mobile, placed, removed);
+    }
+
+    private static bool IsFixture(Item item) =>
+        item is CursedCavePassage or CCKeywordDoor or CCMagicDoor or CCTrigger or CCSummoningAltar or CursedCaveTeleporter ||
+        item is Blocker && item.Map == Map.Felucca && Chamber.Contains(new Point2D(item.X, item.Y + 1));
+
+    public static int Remove()
+    {
+        var doomed = new List<IEntity>();
+
+        foreach (var item in World.Items.Values)
+        {
+            if (IsFixture(item))
+            {
+                doomed.Add(item);
+            }
+        }
+
+        foreach (var m in World.Mobiles.Values)
+        {
+            if (m is WarrenTheGuard)
+            {
+                doomed.Add(m);
+            }
+        }
+
+        foreach (var entity in doomed)
+        {
+            entity.Delete();
+        }
+
+        return doomed.Count;
+    }
+
+    public static int Place()
+    {
+        var map = Map.Felucca;
+        var placed = 0;
+
+        void Put(Item item, Point3D at)
+        {
+            item.MoveToWorld(at, map);
+            placed++;
+
+            if (!map.CanFit(at.X, at.Y, at.Z, 16, true, false) && item is not (Blocker or CCMagicDoor or CCKeywordDoor or CCSummoningAltar))
+            {
+                logger.Warning("Cursed Cave fixture {Item} at {Location} does not fit there", item.GetType().Name, at);
+            }
+        }
+
+        var warren = new WarrenTheGuard();
+        warren.MoveToWorld(WarrenSpot, map);
+        warren.Home = WarrenSpot;
+        placed++;
+
+        Put(new CursedCavePassage(Level1Arrival) { Visible = true, ItemID = 0xDDA, Hue = 0x455, Name = "the Cursed Cave" }, Entrance);
+        Put(new CursedCavePassage(OutsideArrival), Level1Exit);
+
+        Put(Door(new Rectangle2D(6026, 266, 54, 108), Level2DoorArrival, Level1DoorArrival), Level1Door);
+        Put(Door(new Rectangle2D(6026, 266, 54, 108), Level2DoorArrival, Level1DoorArrival), Level2Door);
+
+        Put(new CursedCavePassage(Level3Arrival), Level2Down);
+        Put(new CursedCavePassage(Level2UpArrival), Level3Up);
+
+        var altar = new CCSummoningAltar();
+        Put(altar, ChamberAltar);
+        altar.IsActive = true;
+
+        Put(
+            new CCMagicDoor { PointDest = ChamberArrival, OneSideArea = Chamber, Altar = altar },
+            ChamberDoor
+        );
+
+        for (var x = Chamber.X + 1; x <= Chamber.X + 9; x++)
+        {
+            if (x != ChamberDoor.X)
+            {
+                Put(new Blocker(), new Point3D(x, ChamberDoor.Y, ChamberDoor.Z));
+            }
+        }
+
+        Put(new CursedCavePassage(ChamberExitArrival), ChamberExit);
+
+        Put(
+            new CCTrigger
+            {
+                Message = "You hear screams and strange noises from deep within the cave.",
+                TriggerCheck = CursedCave.TriggerCheck.None
+            },
+            Level1Arrival
+        );
+
+        Put(
+            new CCTrigger { Message = "The god of fire waits behind this door!", TriggerCheck = CursedCave.TriggerCheck.All },
+            new Point3D(ChamberDoor.X, ChamberDoor.Y - 3, ChamberDoor.Z)
+        );
+
+        return placed;
+    }
+
+    private static CCKeywordDoor Door(Rectangle2D level1, Point3D toLevel2, Point3D toLevel1) =>
+        new()
+        {
+            Substring = DoorKeyword,
+            Range = 3,
+            Question = DoorQuestion,
+            OneSideArea = level1,
+            PointDest1 = toLevel2,
+            PointDest2 = toLevel1,
+            MapDest = Map.Felucca,
+            SourceEffect = true,
+            DestEffect = true,
+            SoundID = 0x228
+        };
+}
diff --git a/Projects/UOContent/Custom/DFI/CursedCave/CursedCaveItems.cs b/Projects/UOContent/Custom/DFI/CursedCave/CursedCaveItems.cs
new file mode 100644
index 000000000..2cebedf34
--- /dev/null
+++ b/Projects/UOContent/Custom/DFI/CursedCave/CursedCaveItems.cs
@@ -0,0 +1,678 @@
+// The Cursed Cave's fixtures, ported from DFI RUNUO Scripts/Custom/Engines/Quest System/CursedCave
+// (CCKey.cs, CCMagicDoor.cs, CCKeywordDoor.cs, CCTrigger.cs, CursedCaveTeleporter.cs, ESpecialAbilities.cs,
+// Items/CCSkeletalCorpse.cs, Items/TentCamp*.cs) and DFI's Custom/Ants/BasePool.cs.
+
+using System;
+using System.Collections.Generic;
+using ModernUO.CodeGeneratedEvents;
+using ModernUO.Serialization;
+using Server.Collections;
+using Server.Custom.Dfi;
+using Server.Engines.PartySystem;
+using Server.Gumps;
+using Server.Mobiles;
+using Server.Multis;
+using Server.Network;
+using Server.Regions;
+using Server.Targeting;
+
+namespace Server.Items;
+
+// Opens Hephaestus' chamber: target the magic door from outside it and the key is spent, the holder is
+// taken in, and the party members on level 3 are asked to follow.
+[SerializationGenerator(0)]
+public partial class CCKey : Item
+{
+    [Constructible]
+    public CCKey() : base(0x1012)
+    {
+    }
+
+    public override string DefaultName => "a cursed cave key";
+
+    public override void OnDoubleClick(Mobile from)
+    {
+        if (!IsChildOf(from.Backpack))
+        {
+            from.SendLocalizedMessage(1060640); // The item must be in your backpack to use it.
+            return;
+        }
+
+        from.SendLocalizedMessage(501680); // What do you want to unlock?
+        from.Target = new KeyTarget(this);
+    }
+
+    private class KeyTarget : Target
+    {
+        private readonly CCKey _key;
+
+        public KeyTarget(CCKey key) : base(3, false, TargetFlags.None) => _key = key;
+
+        protected override void OnTarget(Mobile from, object targeted)
+        {
+            if (_key.Deleted || !_key.IsChildOf(from.Backpack))
+            {
+                from.SendLocalizedMessage(1060640); // The item must be in your backpack to use it.
+                return;
+            }
+
+            if (targeted is not CCMagicDoor door)
+            {
+                from.SendLocalizedMessage(501666); // You can't unlock that!
+                return;
+            }
+
+            if (door.OneSideArea.Contains(from.Location))
+            {
+                from.LocalOverheadMessage(MessageType.Regular, 0x5A, true, "There does not seem to be a keyhole on this side");
+                return;
+            }
+
+            var party = Party.Get(from);
+
+            if (party != null)
+            {
+                foreach (var info in party.Members)
+                {
+                    var member = info.Mobile;
+
+                    if (member != from && member.Map == Map.Felucca && member.Region.IsPartOf(CursedCaveRegion.Level3Name))
+                    {
+                        member.SendGump(new MagicDoorPartyGump(door, from, member), true);
+                    }
+                }
+            }
+
+            if (door.Teleport(from))
+            {
+                from.LocalOverheadMessage(MessageType.Regular, 0x5A, true, "The key disappears and you are teleported to the room");
+                _key.Delete();
+
+                if (door.Altar != null)
+                {
+                    door.Altar.MainQueue++;
+                }
+            }
+        }
+    }
+}
+
+public class MagicDoorPartyGump : StaticGump<MagicDoorPartyGump>
+{
+    private readonly CCMagicDoor _door;
+    private readonly Mobile _leader;
+    private readonly Mobile _member;
+
+    public MagicDoorPartyGump(CCMagicDoor door, Mobile leader, Mobile member) : base(150, 50)
+    {
+        _door = door;
+        _leader = leader;
+        _member = member;
+    }
+
+    public override bool Singleton => true;
+
+    protected override void BuildLayout(ref StaticGumpBuilder builder)
+    {
+        builder.SetNoClose();
+
+        builder.AddPage();
+
+        builder.AddImage(0, 0, 3600);
+        builder.AddImageTiled(0, 14, 15, 200, 3603);
+        builder.AddImageTiled(380, 14, 14, 200, 3605);
+        builder.AddImage(0, 201, 3606);
+        builder.AddImageTiled(15, 201, 370, 16, 3607);
+        builder.AddImageTiled(15, 0, 370, 16, 3601);
+        builder.AddImage(380, 0, 3602);
+        builder.AddImage(380, 201, 3608);
+        builder.AddImageTiled(15, 15, 365, 190, 2624);
+
+        builder.AddRadio(30, 140, 9727, 9730, true, 1);
+        builder.AddHtmlLocalized(65, 145, 300, 25, 1050050, 0x7FFF); // Yes, let's go!
+
+        builder.AddRadio(30, 175, 9727, 9730, false, 0);
+        builder.AddHtmlLocalized(65, 178, 300, 25, 1050049, 0x7FFF); // No thanks, I'd rather stay here.
+
+        builder.AddHtml(
+            30,
+            20,
+            360,
+            35,
+            "Another player has used a key to enter Hephaestus the god of fire's chamber:".Color(0xFFFFFF)
+        );
+
+        builder.AddHtmlLocalized(30, 105, 345, 40, 1050048, 0x5B2D); // Do you wish to accept their invitation at this time?
+
+        builder.AddImage(65, 72, 5605);
+        builder.AddImageTiled(80, 90, 200, 1, 9107);
+        builder.AddImageTiled(95, 92, 200, 1, 9157);
+        builder.AddLabelPlaceholder(90, 70, 1645, "leader");
+
+        builder.AddButton(290, 175, 247, 248, 2);
+
+        builder.AddImageTiled(15, 14, 365, 1, 9107);
+        builder.AddImageTiled(380, 14, 1, 190, 9105);
+        builder.AddImageTiled(15, 205, 365, 1, 9107);
+        builder.AddImageTiled(15, 14, 1, 190, 9105);
+        builder.AddImageTiled(0, 0, 395, 1, 9157);
+        builder.AddImageTiled(394, 0, 1, 217, 9155);
+        builder.AddImageTiled(0, 216, 395, 1, 9157);
+        builder.AddImageTiled(0, 0, 1, 217, 9155);
+    }
+
+    protected override void BuildStrings(ref GumpStringsBuilder builder)
+    {
+        builder.SetStringSlot("leader", _leader.Name);
+    }
+
+    public override void OnResponse(NetState sender, in RelayInfo info)
+    {
+        if (info.ButtonID == 2 && info.IsSwitched(1))
+        {
+            if (_member.Region.IsPartOf(CursedCaveRegion.Level3Name))
+            {
+                _leader.SendMessage($"{_member.Name} has accepted your invitation.");
+                _door?.Teleport(_member);
+            }
+            else
+            {
+                _member.SendLocalizedMessage(1050051); // The invitation has been revoked.
+            }
+        }
+        else
+        {
+            _member.SendLocalizedMessage(1050052); // You have declined their invitation.
+            _leader.SendMessage($"{_member.Name} has declined your invitation.");
+        }
+    }
+}
