+// A door that answers a spoken keyword: from inside OneSideArea it leads to PointDest1, from anywhere
+// else to PointDest2. Double-clicking it asks its question.
+[SerializationGenerator(0)]
+public partial class CCKeywordDoor : KeywordTeleporter
+{
+    [SerializableField(0)]
+    [SerializedCommandProperty(AccessLevel.GameMaster)]
+    private string _question;
+
+    [SerializableField(1)]
+    [SerializedCommandProperty(AccessLevel.GameMaster)]
+    private Point3D _pointDest1;
+
+    [SerializableField(2)]
+    [SerializedCommandProperty(AccessLevel.GameMaster)]
+    private Point3D _pointDest2;
+
+    [SerializableField(3)]
+    [SerializedCommandProperty(AccessLevel.GameMaster)]
+    private Rectangle2D _oneSideArea;
+
+    [SerializableField(4)]
+    [SerializedCommandProperty(AccessLevel.GameMaster)]
+    private TimeSpan _usageDelay;
+
+    private HashSet<Mobile> _users;
+    private bool _playedAnimation;
+
+    [Constructible]
+    public CCKeywordDoor()
+    {
+        ItemID = 0x677;
+        Visible = true;
+        _usageDelay = TimeSpan.FromSeconds(10.0);
+    }
+
+    public override int LabelNumber => 1020000 + (ItemID & 0x3FFF);
+
+    public override void OnDoubleClick(Mobile from)
+    {
+        if (from.InRange(Location, Range) && _question != null)
+        {
+            from.LocalOverheadMessage(MessageType.Regular, 0x5A, true, _question);
+        }
+    }
+
+    public override void StartTeleport(Mobile m)
+    {
+        _users ??= [];
+
+        if (!_users.Add(m))
+        {
+            if (!_playedAnimation)
+            {
+                Effects.PlaySound(Location, Map, 0x348);
+                Effects.SendLocationParticles(
+                    EffectItem.Create(new Point3D(X, Y + 1, Z), Map, EffectItem.DefaultDuration),
+                    0x398C,
+                    8,
+                    72,
+                    5042
+                );
+                _playedAnimation = true;
+                Timer.StartTimer(TimeSpan.FromSeconds(3.5), () => _playedAnimation = false);
+            }
+
+            return;
+        }
+
+        Timer.StartTimer(_usageDelay, () => _users.Remove(m));
+
+        PointDest = _oneSideArea.Contains(m.Location) ? _pointDest1 : _pointDest2;
+        base.StartTeleport(m);
+    }
+}
