+// Whispers its message to a player who comes within range, at most once every three hours each; with a
+// check other than None, only to one carrying that talking weapon, in the weapon's voice.
+[SerializationGenerator(0)]
+public partial class CCTrigger : Item
+{
+    private static readonly TimeSpan _repeatDelay = TimeSpan.FromHours(3.0);
+
+    [InvalidateProperties]
+    [SerializableField(0)]
+    [SerializedCommandProperty(AccessLevel.GameMaster)]
+    private CursedCave.TriggerCheck _triggerCheck;
+
+    [SerializableField(1)]
+    [SerializedCommandProperty(AccessLevel.GameMaster)]
+    private string _message;
+
+    [InvalidateProperties]
+    [SerializableField(2)]
+    [SerializedCommandProperty(AccessLevel.GameMaster)]
+    private int _range;
+
+    private Dictionary<Mobile, DateTime> _heard;
+
+    [Constructible]
+    public CCTrigger() : base(0x1F1C)
+    {
+        Visible = false;
+        Movable = false;
+        _range = 4;
+    }
+
+    public override string DefaultName => "CC Trigger";
+    public override bool HandlesOnMovement => true;
+
+    public override void GetProperties(IPropertyList list)
+    {
+        base.GetProperties(list);
+        list.Add(1060658, $"{"Range"}\t{_range}");
+        list.Add(1060659, $"{"Check Type"}\t{_triggerCheck}");
+    }
+
+    public override void OnMovement(Mobile m, Point3D oldLocation)
+    {
+        if (!m.Player || _message == null || Utility.InRange(oldLocation, Location, _range) ||
+            !Utility.InRange(m.Location, Location, _range))
+        {
+            return;
+        }
+
+        _heard ??= [];
+
+        if (_heard.TryGetValue(m, out var until) && Core.Now <= until)
+        {
+            return;
+        }
+
+        if (_triggerCheck == CursedCave.TriggerCheck.None)
+        {
+            _heard[m] = Core.Now + _repeatDelay;
+            CursedCave.PrivateMessage(m, _message);
+        }
+        else if (CursedCave.HasTalkingWeapon(m, out var weaponName, _triggerCheck))
+        {
+            _heard[m] = Core.Now + _repeatDelay;
+            CursedCave.PrivateMessage(m, $"{weaponName}: {_message}");
+        }
+    }
+}
