+// Takes a player standing within three tiles who says its trigger word.
+[SerializationGenerator(0)]
+public partial class CursedCaveTeleporter : Item
+{
+    [SerializableField(0)]
+    [SerializedCommandProperty(AccessLevel.GameMaster)]
+    private string _teleName;
+
+    [SerializableField(1)]
+    [SerializedCommandProperty(AccessLevel.GameMaster)]
+    private bool _allowPets;
+
+    [SerializableField(2)]
+    [SerializedCommandProperty(AccessLevel.GameMaster)]
+    private int _range;
+
+    [SerializableField(3)]
+    [SerializedCommandProperty(AccessLevel.GameMaster)]
+    private bool _active;
+
+    [SerializableField(4)]
+    [SerializedCommandProperty(AccessLevel.GameMaster)]
+    private Point3D _pointDest;
+
+    [SerializableField(5)]
+    [SerializedCommandProperty(AccessLevel.GameMaster)]
+    private Map _mapDest;
+
+    [SerializableField(6)]
+    [SerializedCommandProperty(AccessLevel.GameMaster)]
+    private string _triggerWord;
+
+    [Constructible]
+    public CursedCaveTeleporter() : this(Point3D.Zero, null)
+    {
+    }
+
+    [Constructible]
+    public CursedCaveTeleporter(Point3D pointDest, Map mapDest) : base(0x1BC3)
+    {
+        Movable = false;
+        Visible = false;
+        _active = true;
+        _pointDest = pointDest;
+        _mapDest = mapDest;
+        _teleName = "teleporter";
+    }
+
+    public override string DefaultName => "Cursed Cave Teleporter";
+    public override bool HandlesOnSpeech => true;
+
+    public override void OnSingleClick(Mobile from)
+    {
+        LabelTo(from, 1026095); // teleporter
+
+        if (!_active)
+        {
+            LabelTo(from, "(inactive)");
+        }
+        else if (_mapDest != null && _pointDest != Point3D.Zero)
+        {
+            LabelTo(from, $"{_pointDest} [{_mapDest}]");
+        }
+        else if (_mapDest != null)
+        {
+            LabelTo(from, $"[{_mapDest}]");
+        }
+        else if (_pointDest != Point3D.Zero)
+        {
+            LabelTo(from, $"{_pointDest}");
+        }
+    }
+
+    public override void OnSpeech(SpeechEventArgs e)
+    {
+        var m = e.Mobile;
+
+        if (e.Handled || _triggerWord == null || !m.InRange(this, _range))
+        {
+            return;
+        }
+
+        foreach (var word in e.Speech.Split(' '))
+        {
+            if (word != _triggerWord)
+            {
+                continue;
+            }
+
+            if (!m.InRange(Location, 3))
+            {
+                m.SendLocalizedMessage(1019045); // I can't reach that.
+                return;
+            }
+
+            if (!_allowPets && m.Mounted)
+            {
+                m.Mount.Rider = null;
+            }
+
+            CursedCave.Teleport(m, _active, _pointDest, _mapDest, _allowPets, _teleName);
+            return;
+        }
+    }
+}
