+// A burning puddle that hurts the players and pets standing in it, once a second for ten seconds.
+// Not saved: a pool that outlives a restart is deleted on load.
+[SerializationGenerator(0)]
+public partial class LavaPool : Item
+{
+    private static readonly TimeSpan _duration = TimeSpan.FromSeconds(10.0);
+
+    private readonly int _minDamage;
+    private readonly int _maxDamage;
+    private DateTime _created;
+    private TimerExecutionToken _timerToken;
+
+    public LavaPool(int minDamage, int maxDamage) : base(0x122A)
+    {
+        Movable = false;
+        Hue = 0x1B5;
+        _minDamage = minDamage;
+        _maxDamage = maxDamage;
+        _created = Core.Now;
+        Timer.StartTimer(TimeSpan.Zero, TimeSpan.FromSeconds(1), OnTick, out _timerToken);
+    }
+
+    public override string DefaultName => "lava";
+
+    [AfterDeserialization(false)]
+    private void AfterDeserialization() => Delete();
+
+    public override void OnAfterDelete()
+    {
+        _timerToken.Cancel();
+        base.OnAfterDelete();
+    }
+
+    private void OnTick()
+    {
+        if (Core.Now - _created > _duration)
+        {
+            Delete();
+            return;
+        }
+
+        using var queue = PooledRefQueue<Mobile>.Create();
+
+        foreach (var m in GetMobilesInRange(0))
+        {
+            if (m.Alive && (m is PlayerMobile || m is BaseCreature { IsDeadBondedPet: false } bc && (bc.Controlled || bc.Summoned)))
+            {
+                queue.Enqueue(m);
+            }
+        }
+
+        while (queue.Count > 0)
+        {
+            var m = queue.Dequeue();
+            AOS.Damage(m, Utility.RandomMinMax(_minDamage, _maxDamage), 0, 100, 0, 0, 0);
+            m.PlaySound(0x1DE);
+        }
+    }
+}
