+                BaseEquipableLight light = Utility.Random(3) switch
+                {
+                    1 => new Lantern(),
+                    2 => new Candle(),
+                    _ => new Torch()
+                };
+
+                light.Ignite();
+                AddItem(light);
+            }
+            else
+            {
+                AddItem(CursedCave.MutateItem(Loot.RandomShield(), 10));
+            }
+        }
+    }
+
+    public override string CorpseName => "an inhuman corpse";
+    public override bool UseRearm => true;
+    public override InhumanSpeech SpeechType => CursedCave.Speech;
+    public override bool AlwaysMurderer => true;
+
+    public override void GenerateLoot()
+    {
+        base.GenerateLoot();
+        AddLoot(LootPack.AosRich);
+
+        if (!m_Spawning)
+        {
+            CursedCave.PackSkullsAndSmallBones(Backpack, Utility.Random(1, 2));
+        }
