+
+    public override void BreathDealDamage(BaseCreature source, Mobile target)
+    {
+        base.BreathDealDamage(source, target);
+        Effects.PlaySound(target.Location, target.Map, 0x1CA);
+        new LavaPool(30, 35).MoveToWorld(target.Location, target.Map);
+    }
+}
