+// The Cursed Cave quest and Warren the Guard, ported from DFI RUNUO Scripts/Custom/Engines/Quest System/
+// CursedCave/CursedCaveQuest and the rares reward in CursedCaveUtility.cs.
+
+using System;
+using System.Collections.Generic;
+using ModernUO.Serialization;
+using Server.Custom.Dfi;
+using Server.Gumps;
+using Server.Items;
+using Server.Mobiles;
+using Server.Network;
+using Server.Regions;
+using Server.Text;
+
+namespace Server.Engines.Quests.CursedCave;
+
+// DFI wrote its quest text in English rather than clilocs; these show it in the quest gumps.
+public abstract class DfiQuestConversation : QuestConversation
+{
+    public override int Message => 0;
+    public abstract string Text { get; }
+}
+
+public abstract class DfiQuestObjective : QuestObjective
+{
+    public override int Message => 0;
+    public abstract string Text { get; }
+
+    public override void RenderMessage(ref DynamicGumpBuilder builder)
+    {
+        BaseQuestGump.AddHtmlObject(ref builder, 70, 130, 300, 100, Text, BaseQuestGump.Blue, false, false);
+    }
+}
+
+public abstract class DfiQuestSystem : QuestSystem
+{
+    public DfiQuestSystem(PlayerMobile from) : base(from)
+    {
+    }
+
+    public DfiQuestSystem()
+    {
+    }
+
+    public override void AddConversation(QuestConversation conv)
+    {
+        conv.System = this;
+
+        if (conv.Logged)
+        {
+            Conversations.Add(conv);
+        }
+
+        var gumps = From.GetGumps();
+        gumps.Close<QuestItemInfoGump>();
+        gumps.Close<QuestObjectivesGump>();
+
+        DfiConversationGump.DisplayTo(From, conv.Logged ? Conversations : [conv]);
+    }
+
+    public override void ShowQuestConversation()
+    {
+        if (Conversations.Count > 0)
+        {
+            var gumps = From.GetGumps();
+            gumps.Close<QuestItemInfoGump>();
+            gumps.Close<QuestObjectivesGump>();
+
+            DfiConversationGump.DisplayTo(From, Conversations);
+        }
+    }
+}
+
+// QuestConversationsGump's layout, with the conversations' English text.
+public class DfiConversationGump : BaseQuestGump
+{
+    private readonly List<QuestConversation> _conversations;
+
+    private DfiConversationGump(List<QuestConversation> conversations) : base(30, 50) => _conversations = conversations;
+
+    public override bool Singleton => true;
+
+    public static void DisplayTo(Mobile from, List<QuestConversation> conversations)
+    {
+        if (from?.NetState != null && conversations?.Count > 0)
+        {
+            from.SendGump(new DfiConversationGump(conversations));
+        }
+    }
+
+    protected override void BuildLayout(ref DynamicGumpBuilder builder)
+    {
+        builder.SetNoClose();
+
+        builder.AddPage();
+
+        builder.AddImage(349, 10, 9392);
+        builder.AddImageTiled(349, 130, 100, 120, 9395);
+        builder.AddImageTiled(149, 10, 200, 140, 9391);
+        builder.AddImageTiled(149, 250, 200, 140, 9397);
+        builder.AddImage(349, 250, 9398);
+        builder.AddImage(35, 10, 9390);
+        builder.AddImageTiled(35, 150, 120, 100, 9393);
+        builder.AddImage(35, 250, 9396);
+
+        builder.AddHtmlLocalized(110, 60, 200, 20, 1049069, White); // <STRONG>Conversation Event</STRONG>
+
+        builder.AddImage(65, 14, 10102);
+        builder.AddImageTiled(81, 14, 349, 17, 10101);
+        builder.AddImage(426, 14, 10104);
+
+        builder.AddImageTiled(55, 40, 388, 323, 2624);
+        builder.AddAlphaRegion(55, 40, 388, 323);
+
+        builder.AddImageTiled(75, 90, 200, 1, 9101);
+        builder.AddImage(75, 58, 9781);
+        builder.AddImage(380, 45, 223);
+
+        builder.AddButton(220, 335, 2313, 2312, 1);
+        builder.AddImage(0, 0, 10440);
+
+        builder.AddPage(1);
+
+        for (var i = 0; i < _conversations.Count; ++i)
+        {
+            var conv = _conversations[_conversations.Count - 1 - i];
+
+            if (i > 0)
+            {
+                builder.AddButton(65, 366, 9909, 9911, 0, GumpButtonType.Page, 1 + i);
+                builder.AddHtmlLocalized(90, 367, 50, 20, 1043354, Black); // Previous
+
+                builder.AddPage(1 + i);
+            }
+
+            object message = conv is DfiQuestConversation dfi ? dfi.Text : conv.Message;
+            AddHtmlObject(ref builder, 70, 110, 365, 220, message, LightGreen, false, true);
+
+            if (i > 0)
+            {
+                builder.AddButton(420, 366, 9903, 9905, 0, GumpButtonType.Page, i);
+                builder.AddHtmlLocalized(370, 367, 50, 20, 1043353, Black); // Next
+            }
+        }
+    }
+
+    public override void OnResponse(NetState sender, in RelayInfo info)
+    {
+        for (var i = _conversations.Count - 1; i >= 0; --i)
+        {
+            var qc = _conversations[i];
+
+            if (!qc.HasBeenRead)
+            {
+                qc.HasBeenRead = true;
+                qc.OnRead();
+            }
+        }
+    }
+}
