+public class CursedCaveQuest : DfiQuestSystem
+{
+    private static readonly Type[] _typeReferenceTable =
+    [
+        typeof(AcceptConversation),
+        typeof(DuringKillTaskConversation),
+        typeof(DontOfferConversation),
+        typeof(EndConversation),
+        typeof(CursedCaveBeginObjective),
+        typeof(ReportBackObjective)
+    ];
+
+    public CursedCaveQuest(PlayerMobile from) : base(from)
+    {
+    }
+
+    public CursedCaveQuest()
+    {
+    }
+
+    public override Type[] TypeReferenceTable => _typeReferenceTable;
+
+    public override object Name => "Cursed Cave";
+
+    public override object OfferMessage =>
+        "<I>The guard speaks to you as you approach.. </I><BR><BR>Hail to thee adventurer!<BR>Would you like to help us " +
+        "killing a few monsters in the cursed cave? I will reward you if you complete your task... all I have to give " +
+        "as a reward are some magical items, gold and reagents.";
+
+    public override TimeSpan RestartDelay => TimeSpan.Zero;
+    public override bool IsTutorial => false;
