+// DFI Network's "Slayer of evil!" quest (Opticon's Midas quest), ported from DFI RUNUO Scripts/Custom/Opticon/
+// MidasQuest. DFI wrote six kill objectives and six report-back objectives, one pair per creature; here one of
+// each carries the round.
+
+using System;
+using ModernUO.Serialization;
+using Server.Custom.Dfi;
+using Server.Engines.Quests.CursedCave;
+using Server.Gumps;
+using Server.Items;
+using Server.Mobiles;
+
+namespace Server.Engines.Quests.Midas
+{
+    public class MidasQuest : DfiQuestSystem
+    {
+        private static readonly Type[] _typeReferenceTable =
+        [
+            typeof(SlayConversation),
+            typeof(SlayObjective),
+            typeof(ReturnToNimreObjective),
+            typeof(DuringSlayConversation),
+            typeof(EndConversation),
+            typeof(DeclineConversation)
+        ];
+
+        public MidasQuest(PlayerMobile from) : base(from)
+        {
+        }
+
+        public MidasQuest()
+        {
+        }
+
+        public override Type[] TypeReferenceTable => _typeReferenceTable;
+        public override object Name => "Slayer of evil!";
+
+        public override object OfferMessage =>
+            "<i>Nimre starts to speak.</i><BR><BR>Help me slay demons that roam in this cursed dungeon.<BR><BR>Will you aid me?";
+
+        public override TimeSpan RestartDelay => TimeSpan.Zero;
+        public override bool IsTutorial => false;
+        public override int Picture => 0x15A9;
+
+        public override void Accept()
+        {
+            base.Accept();
+            AddConversation(new SlayConversation(0));
+        }
+
+        public override void Decline()
+        {
+            base.Decline();
+            AddConversation(new DeclineConversation());
+        }
+
+        // A bag of magic items, a 5,000 gold check and a treasure map; one time in ten a Kale artifact, and
+        // often the Midas Touch.
+        public static void GiveRewardTo(PlayerMobile player)
+        {
+            var bag = new Bag { Hue = Utility.RandomDyedHue() };
+            DfiLoot.AddRandomLoot(bag, 5, 600, 5, 5, 50, 100);
+            bag.DropItem(new BankCheck(5000));
+            bag.DropItem(new TreasureMap(Utility.RandomDouble() < 0.08 ? 6 : Utility.RandomMinMax(3, 5), Map.Felucca));
+
+            if (Utility.RandomDouble() < 0.1)
+            {
+                bag.DropItem(
+                    Utility.Random(4) switch
+                    {
+                        0 => new YetisPads(),
+                        1 => new Necronomicon(),
+                        2 => new Behemoth(),
+                        _ => new DragonClenchingClaws()
+                    }
+                );
+            }
+
+            if (Utility.RandomDouble() < 0.80)
+            {
+                bag.DropItem(new MidasTouch());
+            }
+
+            if (!player.KarmaLocked)
+            {
+                player.Karma = Math.Min(15000, player.Karma + 1500);
+            }
+
+            if (player.PlaceInBackpack(bag))
+            {
+                player.SendMessage("Reward bag has been placed in your backpack.");
+            }
+            else
+            {
+                player.SendMessage("Your backpack if full, reward is on the ground.");
+                bag.MoveToWorld(player.Location, player.Map);
+            }
+        }
+    }
+
+    public static class MidasRounds
+    {
+        public static readonly (Type Creature, string Name, string Text)[] All =
+        [
+            (typeof(DarknightCreeper), "Darknight Creeper",
+                "<U>Darknight creepers</U> Search britania's doom dungeon. There you can find plenty of Darknight creepers. Kill 1 of them."),
+            (typeof(FleshRenderer), "Flesh Renderer",
+                "<U>Flesh renderer</U> Search britania's Doom dungeon. There you can find plenty of Flesh Renderers. Kill 1 of them."),
+            (typeof(Impaler), "Impaler",
+                "<U>Impaler</U> Search britania's Doom dungeon. There you can find plenty of impalers. Kill 1 of them."),
+            (typeof(ShadowKnight), "ShadowKnight",
+                "<U>Shadow knight</U> Search britania's Doom dungeon. There you can find plenty of Shadow knights. Kill 1 of them."),
+            (typeof(AbysmalHorror), "Abysmal Horror",
+                "<U>Abysmal Horror</U> Search britania's Doom dungeon. There you can find plenty of Abysmal horrors. Kill 1 of them."),
+            (typeof(DemonKnight), "Dark Father",
+                "<U>Dark Father</U> Search britania's Doom dungeon. There you can find plenty of Dark Fathers. Kill 1 of them.")
+        ];
+
+        public static readonly string[] Orders =
+        [
+            "Kill 1 Darknight creeper and then return",
+            "Kill 1 Flesh renderer and then return",
+            "Kill 1 Impaler and then return",
+            "Kill 1 Shadowknight and then return",
+            "Kill 1 Abysmal horror and then return",
