+
+    public class SlayObjective : DfiQuestObjective
+    {
+        private int _round;
+
+        public SlayObjective(int round) => _round = round;
+
+        public SlayObjective()
+        {
+        }
+
+        public int Round => _round;
+
+        private (Type Creature, string Name, string Text) Current => MidasRounds.All[Math.Clamp(_round, 0, MidasRounds.All.Length - 1)];
+
+        public override string Text => Current.Text;
+
+        public override void RenderProgress(ref DynamicGumpBuilder builder)
+        {
+            if (Completed)
+            {
+                base.RenderProgress(ref builder);
+                return;
+            }
+
+            builder.AddLabel(70, 260, 270, Current.Name);
+            builder.AddLabel(70, 280, 0x64, $"{CurProgress}");
+            builder.AddLabel(100, 280, 0x64, "/");
+            builder.AddLabel(130, 280, 0x64, $"{MaxProgress}");
+        }
+
+        public override void OnKill(BaseCreature creature, Container corpse)
+        {
+            if (Current.Creature.IsInstanceOfType(creature))
+            {
+                CurProgress++;
+            }
+        }
+
+        public override void OnComplete()
+        {
+            System.AddObjective(new ReturnToNimreObjective(_round));
+        }
+
+        public override void ChildDeserialize(IGenericReader reader)
+        {
+            reader.ReadEncodedInt(); // version
+            _round = reader.ReadEncodedInt();
+        }
+
+        public override void ChildSerialize(IGenericWriter writer)
+        {
+            writer.WriteEncodedInt(0); // version
+            writer.WriteEncodedInt(_round);
+        }
+    }
+
+    public class ReturnToNimreObjective : DfiQuestObjective
+    {
+        private int _round;
+
+        public ReturnToNimreObjective(int round) => _round = round;
+
+        public ReturnToNimreObjective()
+        {
+        }
+
+        public int Round => _round;
+
+        public override string Text =>
+            _round >= MidasRounds.All.Length - 1
+                ? "Return to Nimre to talk and get your reward."
+                : "Return to Nimre for further instructions.";
+
+        public override void ChildDeserialize(IGenericReader reader)
+        {
+            reader.ReadEncodedInt(); // version
+            _round = reader.ReadEncodedInt();
+        }
+
+        public override void ChildSerialize(IGenericWriter writer)
+        {
+            writer.WriteEncodedInt(0); // version
+            writer.WriteEncodedInt(_round);
+        }
+    }
+
+    public class SlayConversation : DfiQuestConversation
+    {
+        private int _round;
+
+        public SlayConversation(int round) => _round = round;
+
+        public SlayConversation()
+        {
+        }
+
+        public override string Text => MidasRounds.Orders[Math.Clamp(_round, 0, MidasRounds.Orders.Length - 1)];
+
+        public override void OnRead()
+        {
+            System.AddObjective(new SlayObjective(_round));
+        }
+
+        public override void ChildDeserialize(IGenericReader reader)
+        {
+            reader.ReadEncodedInt(); // version
+            _round = reader.ReadEncodedInt();
+        }
+
+        public override void ChildSerialize(IGenericWriter writer)
+        {
+            writer.WriteEncodedInt(0); // version
+            writer.WriteEncodedInt(_round);
+        }
