+
+    public class DeclineConversation : DfiQuestConversation
+    {
+        public override string Text => "Return if you change your mind.";
+        public override bool Logged => false;
+    }
+
+    public class DuringSlayConversation : DfiQuestConversation
+    {
+        public override string Text => "You didn't finish your task yet! Continue when you want.";
+        public override bool Logged => false;
+    }
+
+    public class EndConversation : DfiQuestConversation
+    {
+        public override string Text => "You truly are the brave one. <BR>Your reward is in your backpack!";
+
+        public override void OnRead()
+        {
+            MidasQuest.GiveRewardTo(System.From);
+            System.Complete();
+        }
+    }
+
+    [SerializationGenerator(0)]
+    public partial class MidasQuestGiver : BaseQuester
+    {
+        [Constructible]
+        public MidasQuestGiver()
+        {
+        }
+
+        public override string DefaultName => "Nimre slayer of evil";
+
+        public override void InitBody()
+        {
+            InitStats(100, 100, 25);
+            Hue = 0x83ED;
+            Female = false;
+            HairHue = 0x1F4;
+            HairItemID = 0x203C;
+            FacialHairItemID = 0x2040;
+            FacialHairHue = 1000;
+            Body = 0x190;
+        }
+
+        public override void InitOutfit()
+        {
+            foreach (var piece in (BaseArmor[])[new PlateArms(), new PlateGloves(), new PlateLegs(), new PlateGorget(), new PlateChest()])
+            {
+                piece.LootType = LootType.Newbied;
+                piece.Hue = 1153;
+                AddItem(piece);
+            }
+
+            AddItem(new OrderShield { LootType = LootType.Newbied, Hue = 1153 });
+        }
+
+        public override void OnTalk(PlayerMobile player, bool contextMenu)
+        {
+            Direction = GetDirectionTo(player);
+
+            var qs = player.Quest;
+
+            if (qs is not MidasQuest)
+            {
+                if (qs == null && QuestSystem.CanOfferQuest(player, typeof(MidasQuest)))
+                {
+                    new MidasQuest(player).SendOffer();
+                }
+
+                return;
+            }
+
+            if (qs.IsObjectiveInProgress(typeof(SlayObjective)))
+            {
+                qs.AddConversation(new DuringSlayConversation());
+                return;
+            }
+
+            // Every round leaves a report-back objective; the newest one not yet done is this round's.
+            ReturnToNimreObjective current = null;
+
+            foreach (var obj in qs.Objectives)
+            {
+                if (obj is ReturnToNimreObjective r && !r.Completed)
+                {
+                    current = r;
+                }
+            }
+
+            if (current == null)
+            {
+                return;
+            }
+
+            current.Complete();
+
+            if (current.Round >= MidasRounds.All.Length - 1)
+            {
+                qs.AddConversation(new EndConversation());
+            }
+            else
+            {
+                qs.AddConversation(new SlayConversation(current.Round + 1));
+            }
+        }
+    }
+}
