+// DFI Network's Plague quest, ported from DFI RUNUO Scripts/Custom/Engines/Quest System/Plague.
+
+using System;
+using ModernUO.Serialization;
+using Server.Custom.Dfi;
+using Server.Engines.PartySystem;
+using Server.Engines.Quests.CursedCave;
+using Server.Gumps;
+using Server.Items;
+using Server.Mobiles;
+using Server.Network;
+
+namespace Server.Engines.Quests.Plague
+{
+    // Zuleika keeps the poison fungus a player brings her; at 200 she opens the way to the Alternate
+    // Dimension, where her altar summons the Plague.
+    public class ThePlagueQuest : DfiQuestSystem
+    {
+        private static readonly Type[] _typeReferenceTable =
+        [
+            typeof(AcceptConversation),
+            typeof(CollectFungusObjective),
+            typeof(VanquishDaemonConversation),
+            typeof(DontOfferConversation),
+            typeof(DuringCollectFungusConversation)
+        ];
+
+        private Zuleika _zuleika;
+
+        public ThePlagueQuest(Zuleika zuleika, PlayerMobile from) : base(from) => _zuleika = zuleika;
+
+        public ThePlagueQuest()
+        {
+        }
+
+        public Zuleika Zuleika => _zuleika;
+
+        public override Type[] TypeReferenceTable => _typeReferenceTable;
+        public override object Name => "The Plague";
+
+        public override object OfferMessage =>
+            "<I>Zuleika turns to you and says...</I><BR><BR>I can help you find these evil plague beasts, i need 200 Poison " +
+            "fungus to create a spell that can teleport you and your party to the Alternate Dimension. If you accept my help, " +
+            "I will store the Poison fungus for you until you have collected all 200 of them. Once the fungus are collected " +
+            "in full, I will teleport you and your party to the Alternate Dimension.<BR><BR>";
+
+        public override bool IsTutorial => false;
+        public override TimeSpan RestartDelay => TimeSpan.Zero;
+        public override int Picture => 0x15B5;
+
+        public override void Cancel()
+        {
+            base.Cancel();
+
+            var obj = FindObjective(typeof(CollectFungusObjective));
+
+            if (obj?.CurProgress > 0)
+            {
+                From.BankBox?.DropItem(new PoisonFungus(obj.CurProgress));
+                From.SendMessage("The Poison fungus that you have thus far given to Zuleika have been returned to you.");
+            }
+        }
+
+        public override void Accept()
+        {
+            base.Accept();
+            AddConversation(new AcceptConversation());
+        }
+
+        public override void ChildDeserialize(IGenericReader reader)
+        {
+            reader.ReadEncodedInt(); // version
+            _zuleika = reader.ReadEntity<Zuleika>();
+        }
+
+        public override void ChildSerialize(IGenericWriter writer)
+        {
+            writer.WriteEncodedInt(0); // version
+            writer.Write(_zuleika);
+        }
+    }
+
+    public class CollectFungusObjective : DfiQuestObjective
+    {
+        public override string Text => "Find 200 Poison fungus and hand them to Zuleika as you find them.";
+        public override int MaxProgress => 200;
+
+        public override void OnComplete()
+        {
+            if (((ThePlagueQuest)System).Zuleika?.Altar == null)
+            {
+                System.From.SendMessage("Zuleika cannot be found to weave the spell; the quest cannot continue.");
+                System.Cancel();
+                return;
+            }
+
+            System.AddConversation(new VanquishDaemonConversation());
+        }
+
+        public override void RenderMessage(ref DynamicGumpBuilder builder)
+        {
+            if (CurProgress > 0 && CurProgress < MaxProgress)
+            {
+                BaseQuestGump.AddHtmlObject(
+                    ref builder,
+                    70,
+                    130,
+                    300,
+                    100,
+                    "Zuleika has accepted the Poison fungus, but the requirement is not yet met.",
+                    BaseQuestGump.Blue,
+                    false,
+                    false
+                );
+            }
+            else
+            {
+                base.RenderMessage(ref builder);
+            }
+        }
+
+        public override void RenderProgress(ref DynamicGumpBuilder builder)
+        {
+            if (CurProgress > 0 && CurProgress < MaxProgress)
+            {
+                BaseQuestGump.AddHtmlObject(ref builder, 70, 260, 270, 100, "Number of fungus collected:", BaseQuestGump.Blue, false, false);
+                builder.AddLabel(70, 280, 100, $"{CurProgress}");
+                builder.AddLabel(100, 280, 100, "/");
+                builder.AddLabel(130, 280, 100, $"{MaxProgress}");
+            }
+            else
+            {
+                base.RenderProgress(ref builder);
+            }
+        }
+    }
+
+    public class AcceptConversation : DfiQuestConversation
+    {
+        public override string Text =>
+            "You have accepted Zuleika's help. She requires 200 Poison fungus to create a spell that can teleport you and " +
+            "your party to the Alternate Dimension.<BR><BR>You may hand Zuleika the fungus as you collect them and she will " +
+            "keep count of how many you have brought her.<BR><BR>Poison fungus can be collected from (Plagued) creatures, " +
+            "these creatures can be found in all the dungeons in britannia.<BR><BR>Good luck.";
+
+        public override void OnRead()
+        {
+            System.AddObjective(new CollectFungusObjective());
+        }
+    }
+
+    public class DontOfferConversation : DfiQuestConversation
+    {
+        public override string Text =>
+            "<I>The gray skinned necromancer looks at you and says...</I><BR><BR>You seem to be busy with another quest. " +
+            "Come and speak with me again when you have completed your present quest.";
+
+        public override bool Logged => false;
+    }
+
+    public class DuringCollectFungusConversation : DfiQuestConversation
+    {
+        public override string Text =>
+            "<I>The old necromancer looks at you and says...</I><BR><BR>Have you collected the poison fungus already? If so " +
+            "give them to me so i can create the spell.";
+
+        public override bool Logged => false;
+    }
+
+    public class VanquishDaemonConversation : DfiQuestConversation
+    {
+        public override string Text =>
+            "Well done! I shall now use the spell to teleport you and your party to the Alternate Dimension.";
+
+        public override void OnRead()
+        {
+            var zuleika = ((ThePlagueQuest)System).Zuleika;
+
+            if (zuleika?.Altar == null)
+            {
+                System.From.SendMessage("Zuleika cannot be found to weave the spell; the quest cannot continue.");
+                System.Cancel();
+                return;
+            }
+
+            zuleika.Altar.MainQueue++;
+            zuleika.MovePlayers(System.From);
+            System.Complete();
+        }
+    }
+
+    [SerializationGenerator(0)]
+    public partial class Zuleika : BaseQuester
+    {
+        // The Alternate Dimension: the spiral halls on Trammel east of the dungeon block.
+        public static readonly Point3D Destination = new(6093, 441, -22);
+
+        [SerializableField(0)]
+        [SerializedCommandProperty(AccessLevel.GameMaster)]
+        private PlagueSummoningAltar _altar;
+
+        [Constructible]
+        public Zuleika() : base("the Necromancer")
+        {
+        }
+
+        public override string DefaultName => "Zuleika";
+        public override bool ClickTitle => true;
+        public override bool IsActiveVendor => true;
+        public override bool DisallowAllMoves => false;
+
+        public override void InitSBInfo()
+        {
+            SBInfos.Add(new SBZuleika());
+        }
+
+        public override void InitBody()
+        {
+            InitStats(100, 100, 25);
+            Body = 0x191;
+            Female = true;
+        }
+
+        public override void InitOutfit()
+        {
+            HairItemID = 0x203C;
+            HairHue = 0x457;
+
+            EquipItem(new Robe(0x455));
+            EquipItem(new Sandals(0x455));
+            EquipItem(new GnarledStaff { Hue = 0x455 });
+            EquipItem(new GoldBeadNecklace { Hue = 0x455 });
+            EquipItem(new GoldBracelet());
+            EquipItem(new GoldRing());
+            EquipItem(new HoodedShroudOfShadows(0x593));
+        }
+
+        public override bool OnDragDrop(Mobile from, Item dropped)
+        {
+            if (from is not PlayerMobile { Quest: ThePlagueQuest qs } || dropped is not PoisonFungus fungus)
+            {
+                return base.OnDragDrop(from, dropped);
+            }
+
+            var obj = qs.FindObjective(typeof(CollectFungusObjective));
+
+            if (obj == null || obj.Completed)
+            {
+                SayTo(from, "You have already given me all the Poison fungus necessary to weave the spell.  Keep these for a later time.");
+                return false;
+            }
+
+            var need = obj.MaxProgress - obj.CurProgress;
+
+            if (fungus.Amount < need)
+            {
+                obj.CurProgress += fungus.Amount;
+                fungus.Delete();
+                qs.ShowQuestLogUpdated();
+            }
+            else
+            {
+                fungus.Consume(need);
+                obj.Complete();
+
+                if (!fungus.Deleted)
+                {
+                    SayTo(from, "You have already given me all the Poison fungus necessary to weave the spell.  Keep these for a later time.");
+                }
+            }
+
+            return false;
+        }
+
+        public void MovePlayers(Mobile from)
+        {
+            var party = Server.Engines.PartySystem.Party.Get(from);
+
+            if (party != null)
+            {
+                foreach (var info in party.Members)
+                {
+                    var member = info.Mobile;
+
+                    if (member != from && member.Map == Map.Felucca && member.Region == from.Region)
+                    {
+                        member.SendGump(new ZuleikaPartyGump(from, member), true);
+                    }
+                }
+            }
+
+            Teleport(from);
+        }
+
+        public static void Teleport(Mobile from)
+        {
+            var map = Map.Trammel;
+            Effects.SendLocationParticles(EffectItem.Create(Destination, map, EffectItem.DefaultDuration), 0x3728, 10, 10, 2023);
+            Effects.PlaySound(Destination, map, 0x1FE);
+            BaseCreature.TeleportPets(from, Destination, map);
+            from.MoveToWorld(Destination, map);
+        }
+
+        public override void OnTalk(PlayerMobile player, bool contextMenu)
+        {
+            var qs = player.Quest;
+
+            if (qs is ThePlagueQuest)
+            {
+                if (qs.IsObjectiveInProgress(typeof(CollectFungusObjective)))
+                {
+                    qs.AddConversation(new DuringCollectFungusConversation());
+                }
+            }
+            else if (qs != null)
+            {
+                qs.AddConversation(new DontOfferConversation());
+            }
+            else if (QuestSystem.CanOfferQuest(player, typeof(ThePlagueQuest)))
+            {
+                Direction = GetDirectionTo(player);
+                new ThePlagueQuest(this, player).SendOffer();
+            }
+        }
+    }
+
