+            SetSkill(SkillName.Wrestling, 100.0);
+            SetSkill(SkillName.Macing, 100.0);
+            SetSkill(SkillName.Anatomy, 100.0);
+
+            Fame = 22500;
+            Karma = -22500;
+
+            VirtualArmor = 30;
+        }
+
+        public override string DefaultName => "The Plague";
+        public override string CorpseName => "a plagued corpse";
+        public override bool AlwaysMurderer => true;
+        public override bool BardImmune => true;
+        public override Poison PoisonImmune => Poison.Lethal;
+        public override int TreasureMapLevel => 5;
+        public override bool ShowFameTitle => false;
+        public override bool ClickTitle => false;
+
+        public override MonsterAbility[] GetMonsterAbilities() => _abilities;
+
+        public static Item CreateRandomArtifact() => Loot.Construct(_rewards.RandomElement());
+
+        public override void GenerateLoot()
+        {
+            AddLoot(LootPack.SuperBoss, 2);
+        }
+
+        public override void OnGaveMeleeAttack(Mobile defender, int damage)
+        {
+            base.OnGaveMeleeAttack(defender, damage);
+
+            if (Utility.RandomDouble() <= 0.1)
+            {
+                AddPlaguedSkull(defender, 0.25);
+            }
+        }
+
+        public override void OnDamage(int amount, Mobile from, bool willKill)
+        {
+            base.OnDamage(amount, from, willKill);
+
+            if (from != null && Utility.RandomDouble() <= 0.1)
+            {
+                AddPlaguedSkull(from, 0.25);
+            }
+        }
+
+        public override void AlterDamageScalarFrom(Mobile caster, ref double scalar)
+        {
+            base.AlterDamageScalarFrom(caster, ref scalar);
+
+            if (Utility.RandomDouble() <= 0.1)
+            {
+                AddPlaguedSkull(caster, 1.0);
+            }
+        }
+
+        public override void AlterMeleeDamageTo(Mobile to, ref int damage)
+        {
+            if (to is BaseCreature { Controlled: true, Summoned: false })
+            {
+                damage *= 2;
+            }
+        }
+
+        public override void OnDeath(Container c)
+        {
+            base.OnDeath(c);
+
+            if (0.03 + LootPack.GetLuckChanceForKiller(this) / 180000.0 > Utility.RandomDouble())
+            {
+                DemonKnight.DistributeArtifact(this, CreateRandomArtifact());
+            }
+        }
+
+        // Throws a plagued skull at the target, or drops one at its own feet; the skull hatches a plagued
+        // slime or plague beast ten seconds later unless it is carved apart first.
+        public void AddPlaguedSkull(Mobile target, double chanceToThrow)
+        {
+            if (Utility.RandomDouble() > chanceToThrow)
+            {
+                new PlaguedSkull().MoveToWorld(Location, Map);
+                return;
+            }
+
+            Direction = GetDirectionTo(target);
+            MovingEffect(target, 0xF7E, 10, 1, true, false, 0x496, 0);
+
+            Timer.StartTimer(
+                TimeSpan.FromSeconds(1.0),
+                () =>
+                {
+                    if (!Deleted && CanBeHarmful(target))
+                    {
+                        DoHarmful(target);
+                        AOS.Damage(target, this, Utility.RandomMinMax(10, 20), 100, 0, 0, 0, 0);
+                        new PlaguedSkull().MoveToWorld(target.Location, target.Map);
+                    }
+                }
+            );
+        }
+    }
+
+    public class PlagueBreath : FireBreath
+    {
+        public override int FireDamage => 0;
+        public override int PoisonDamage => 100;
+        public override int BreathEffectHue => 0x3F;
+        public override int BreathEffectSound => 0x118;
+
+        public override int BreathComputeDamage(BaseCreature source) => 50;
+
+        public override void BreathDealDamage(BaseCreature source, Mobile target)
+        {
+            base.BreathDealDamage(source, target);
+            Effects.PlaySound(target.Location, target.Map, 0x1CA);
+        }
+    }
+}
