+            DropItem(new TreasureMap(level, Map.Felucca));
+    }
+
+    // Hatches a plagued slime or plague beast ten seconds after it lands, unless carved first.
+    [SerializationGenerator(0)]
+    public partial class PlaguedSkull : Item, ICarvable
+    {
+        private TimerExecutionToken _timerToken;
+
+        [Constructible]
+        public PlaguedSkull() : base(Utility.Random(0x1AE0, 5))
+        {
+            Movable = false;
+            Hue = 0x55C;
+            StartTimer();
+        }
+
+        private void StartTimer() => Timer.StartTimer(TimeSpan.FromSeconds(10), Hatch, out _timerToken);
+
+        private void Hatch()
+        {
+            if (Deleted)
+            {
+                return;
+            }
+
+            BaseCreature spawn = Utility.RandomBool() ? new Slime() : new PlagueBeast();
+            DfiVariants.MakePlagued(spawn, false);
+            spawn.MoveToWorld(Location, Map);
+            Delete();
+        }
+
+        public void Carve(Mobile from, Item item)
+        {
+            Effects.PlaySound(GetWorldLocation(), Map, 0x48F);
+            Effects.SendLocationEffect(GetWorldLocation(), Map, 0x3728, 10, 10);
+
+            if (Utility.RandomDouble() < 0.3)
+            {
+                from.SendMessage("You destroy the skull.");
+                new Gold(25, 100).MoveToWorld(GetWorldLocation(), Map);
+                Delete();
+            }
+            else
+            {
+                from.SendMessage("You damage the skull.");
+            }
+        }
+
+        public override void OnAfterDelete()
+        {
+            _timerToken.Cancel();
+            base.OnAfterDelete();
+        }
+
+        [AfterDeserialization]
+        private void AfterDeserialization() => StartTimer();
+    }
