+    // Levels on one of six kinds of creature, picked when it is made.
+    [SerializationGenerator(0)]
+    public partial class BowOfWeakening : Bow, ILevelable
+    {
+        private static readonly string[] _kindNames = ["Abyss", "Arachnid", "Cold Blood", "Forest Lord", "Vermin Horde", "Unholy Terror"];
+
+        private static readonly Type[][] _kinds =
+        [
+            [
+                typeof(Mongbat), typeof(Imp), typeof(Gargoyle), typeof(Harpy), typeof(FireGargoyle), typeof(StoneGargoyle),
+                typeof(Daemon), typeof(Succubus)
+            ],
+            [
+                typeof(Scorpion), typeof(GiantSpider), typeof(TerathanDrone), typeof(TerathanWarrior), typeof(DreadSpider),
+                typeof(TerathanMatriarch), typeof(PoisonElemental), typeof(TerathanAvenger)
+            ],
+            [
+                typeof(Lizardman), typeof(Snake), typeof(LavaLizard), typeof(OphidianWarrior), typeof(Drake),
+                typeof(OphidianArchmage), typeof(Dragon), typeof(OphidianKnight)
+            ],
+            [
+                typeof(Pixie), typeof(ShadowWisp), typeof(Kirin), typeof(Wisp), typeof(Centaur), typeof(Unicorn),
+                typeof(EtherealWarrior), typeof(SerpentineDragon)
+            ],
+            [
+                typeof(GiantRat), typeof(Slime), typeof(DireWolf), typeof(Ratman), typeof(HellHound), typeof(RatmanMage),
+                typeof(RatmanArcher), typeof(SilverSerpent)
+            ],
+            [
+                typeof(Bogle), typeof(Ghoul), typeof(Shade), typeof(Spectre), typeof(Wraith), typeof(BoneMagi),
+                typeof(Mummy), typeof(SkeletalMage), typeof(BoneKnight), typeof(Lich), typeof(SkeletalKnight),
+                typeof(LichLord), typeof(RottingCorpse)
+            ]
+        ];
+
+        [SerializableField(0, getter: "private", setter: "private")]
+        private int _kind;
+
+        [SerializableField(1, getter: "private", setter: "private")]
+        private int _exp;
+
+        [SerializableField(2, getter: "private", setter: "private")]
+        private int _lvl;
+
+        [Constructible]
+        public BowOfWeakening()
+        {
+            Hue = 0x59E;
+            _kind = Utility.Random(_kinds.Length);
+            Attributes.WeaponDamage = 40;
+            Attributes.WeaponSpeed = 30;
+            SkillBonuses.SetValues(0, SkillName.Archery, 10.0);
+            Slayer = SlayerName.ReptilianDeath;
+            WeaponAttributes.HitLowerAttack = 50;
+            LevelItemManager.InvalidateLevel(this);
+        }
+
+        public override string DefaultName => "bow of weakening";
+        public override int ArtifactRarity => 11;
+        public override int InitMinHits => 255;
+        public override int InitMaxHits => 255;
+
+        public Type[] Types => _kinds[Math.Clamp(_kind, 0, _kinds.Length - 1)];
+
+        [CommandProperty(AccessLevel.GameMaster)]
+        public int Experience
+        {
+            get => _exp;
+            set
+            {
+                _exp = LevelableWeapon.ClampExperience(value);
+                LevelItemManager.InvalidateLevel(this);
+                this.MarkDirty();
+            }
+        }
+
+        [CommandProperty(AccessLevel.GameMaster)]
+        public int Level
+        {
+            get => _lvl;
+            set
+            {
+                value = LevelableWeapon.ClampLevel(value);
+
+                if (_lvl != value)
+                {
+                    var oldLevel = _lvl;
+                    _lvl = value;
+                    OnLevel(oldLevel, _lvl);
+                    this.MarkDirty();
+                }
+            }
+        }
+
+        public override void GetDamageTypes(
+            Mobile wielder, out int phys, out int fire, out int cold, out int pois, out int nrgy, out int chaos, out int direct
+        )
+        {
+            phys = pois = cold = nrgy = chaos = direct = 0;
+            fire = 100;
+        }
+
+        public override void GetProperties(IPropertyList list)
+        {
+            base.GetProperties(list);
+            LevelableWeapon.AddProperties(list, _lvl, _exp);
+            list.Add(1060660, $"{"Type"}\t{_kindNames[Math.Clamp(_kind, 0, _kindNames.Length - 1)]}");
+        }
+
+        public override void GetContextMenuEntries(Mobile from, ref Server.Collections.PooledRefList<ContextMenus.ContextMenuEntry> list)
+        {
+            base.GetContextMenuEntries(from, ref list);
+
+            if (from.Alive && (from.Items.Contains(this) || IsChildOf(from.Backpack)))
+            {
+                list.Add(new LevelInfoEntry(this));
+            }
+        }
+
+        public void OnLevel(int oldLevel, int newLevel)
+        {
+            Attributes.WeaponDamage = LevelItemManager.CalculateProperty(40, _lvl);
+            Attributes.WeaponSpeed = LevelItemManager.CalculateProperty(30, _lvl);
+            WeaponAttributes.HitLowerAttack = LevelItemManager.CalculateProperty(50, _lvl);
+            SkillBonuses.SetValues(0, SkillName.Archery, LevelItemManager.CalculateProperty(10, _lvl));
+        }
+
+        public string GetHtml() =>
+            "<div align=center><i>ENHANCEMENTS</i></div>WeaponDamage: 40%<br>WeaponSpeed: 30%<br>HitLowerAttack: 50%<br>" +
+            "Archery: 10<br>" + LevelItemManager.LevelGainList();
+    }
+}
