diff --git a/Projects/UOContent/Custom/DFI/HuntingBods/HuntRewardDecor.cs b/Projects/UOContent/Custom/DFI/HuntingBods/HuntRewardDecor.cs
new file mode 100644
index 000000000..604e0dbc0
--- /dev/null
+++ b/Projects/UOContent/Custom/DFI/HuntingBods/HuntRewardDecor.cs
@@ -0,0 +1,833 @@
+// The hunting contract reward decor, generated from DFI RUNUO Scripts/Custom/Engines/HuntingBods/Rewards
+// (Carpets.cs, LargeCarpets.cs, LargeStretchedHide.cs, OrcishBanner.cs, LargeBanners).
+
+using ModernUO.Serialization;
+
+namespace Server.Items;
+
+[SerializationGenerator(0)]
+public partial class SmallBrownCarpetAddon : BaseAddon
+{
+    [Constructible]
+    public SmallBrownCarpetAddon()
+    {
+        AddComponent(new AddonComponent(0xAE4), -1, -1, 0);
+        AddComponent(new AddonComponent(0xAE7), -1, 0, 0);
+        AddComponent(new AddonComponent(0xAE5), -1, 1, 0);
+        AddComponent(new AddonComponent(0xAE8), 0, -1, 0);
+        AddComponent(new AddonComponent(0xAEC), 0, 0, 0);
+        AddComponent(new AddonComponent(0xAEA), 0, 1, 0);
+        AddComponent(new AddonComponent(0xAE6), 1, -1, 0);
+        AddComponent(new AddonComponent(0xAE9), 1, 0, 0);
+        AddComponent(new AddonComponent(0xAE3), 1, 1, 0);
+    }
+
+    public override BaseAddonDeed Deed => new SmallBrownCarpetDeed();
+}
+
+[SerializationGenerator(0)]
+public partial class SmallBrownCarpetDeed : BaseAddonDeed
+{
+    [Constructible]
+    public SmallBrownCarpetDeed()
+    {
+        LootType = LootType.Blessed;
+    }
+
+    public override BaseAddon Addon => new SmallBrownCarpetAddon();
+    public override string DefaultName => "a small brown carpet deed";
+}
+
+[SerializationGenerator(0)]
+public partial class VerySmallBlueCarpetAddon : BaseAddon
+{
+    [Constructible]
