+    // Levels on the fey: pixies, ki-rin and unicorns.
+    [SerializationGenerator(0)]
+    public partial class WarForkOfChaos : WarFork, ILevelable
+    {
+        private static readonly Type[] _types = [typeof(Pixie), typeof(Kirin), typeof(Unicorn)];
+
+        [SerializableField(0, getter: "private", setter: "private")]
+        private int _exp;
+
+        [SerializableField(1, getter: "private", setter: "private")]
+        private int _lvl;
+
+        [Constructible]
+        public WarForkOfChaos()
+        {
+            Hue = 0x485;
+            WeaponAttributes.UseBestSkill = 1;
+            LevelItemManager.InvalidateLevel(this);
+        }
+
+        public override string DefaultName => "warfork of chaos";
+        public override int ArtifactRarity => 11;
+        public override int InitMinHits => 255;
+        public override int InitMaxHits => 255;
