+        public override void GetContextMenuEntries(Mobile from, ref Server.Collections.PooledRefList<ContextMenus.ContextMenuEntry> list)
+        {
+            base.GetContextMenuEntries(from, ref list);
+
+            if (from.Alive && (from.Items.Contains(this) || IsChildOf(from.Backpack)))
+            {
+                list.Add(new LevelInfoEntry(this));
+            }
+        }
+
+        public void OnLevel(int oldLevel, int newLevel)
+        {
+            WeaponAttributes.HitLeechHits = LevelItemManager.CalculateProperty(50, _lvl);
+            Attributes.WeaponSpeed = LevelItemManager.CalculateProperty(15, _lvl);
+            Attributes.ReflectPhysical = LevelItemManager.CalculateProperty(15, _lvl);
+            Attributes.WeaponDamage = LevelItemManager.CalculateProperty(40, _lvl);
+        }
+
+        public string GetHtml() =>
+            "<div align=center><i>ENHANCEMENTS</i></div>HitLeechHits: 50%<br>WeaponSpeed: 15%<br>ReflectPhysical: 15%<br>" +
+            "WeaponDamage: 40%<br>" + LevelItemManager.LevelGainList();
+    }
+}
