+public static class EventRewardEffects
+{
+    public static void Play(Mobile from)
+    {
+        Effects.SendLocationParticles(
+            EffectItem.Create(from.Location, from.Map, EffectItem.DefaultDuration), 0x376A, 1, 29, 0x47D, 2, 9962, 0
+        );
+        Effects.SendLocationParticles(
+            EffectItem.Create(new Point3D(from.X, from.Y, from.Z - 7), from.Map, EffectItem.DefaultDuration), 0x37C4, 1, 29, 0x47D,
+            2, 9502, 0
+        );
+        from.PlaySound(0x212);
+        from.PlaySound(0x206);
+    }
+}
