+// DFI Network's event reward system: copper bars won at staff events, spent at the Event Reward Vendor.
+// Ported from DFI RUNUO Scripts/Custom/Engines/EventRewardSystem (CopperBar, EventRewardNPC, EventRewardSystem,
+// EventRewardItemGumps, ItemInfo). The wedding deed and the kill book are donation-system items DFI never
+// shipped here, so the catalogue leaves them out.
+
+using System;
+using System.Collections.Generic;
+using ModernUO.Serialization;
+using Server.Commands;
+using Server.Engines.Quests;
+using Server.Gumps;
+using Server.Items;
+using Server.Logging;
+using Server.Mobiles;
+using Server.Network;
+
+namespace Server.Custom.Dfi;
+
+// Cursed so it drops on death and stays out of the bank's insurance; it only buys event rewards.
+[SerializationGenerator(0)]
+public partial class CopperBar : Item
+{
+    [Constructible(AccessLevel.Administrator)]
+    public CopperBar(int amount = 1) : base(0x1BE3)
+    {
+        Stackable = true;
+        Amount = amount;
+        LootType = LootType.Cursed;
+    }
+
+    public override double DefaultWeight => 0.3;
+    public override string DefaultName => "Copper Bar";
+}
+
