+{
+    PlayItem = 1,
+    Deco = 2,
+    Fancy = 3
+}
+
+public record EventRewardInfo(
+    EventRewardCategory Category, string Name, string Info, int Price, int ItemID, int X, int Y, Func<Mobile, Item> Create
+);
+
+public static class EventRewardSystem
+{
+    private static readonly ILogger logger = LogFactory.GetLogger(typeof(EventRewardSystem));
+
+    // What a game master may hand out a day without an administrator.
+    public const int MaxCopper = 25;
