+// DFI Network's Last Man Pentagram: after a countdown, the first player to stand alone on the pentagram long
+// enough wins a random reward, which stays cursed and marks its carrier for ten minutes. Ported from DFI RUNUO
+// Scripts/Custom/Items/Misc/LastManPentagram.cs and Misc/CursedArtifactSystem.cs; DFI's world timer started it
+// every evening, here the item's own daily schedule does.
+
+using System;
+using System.Collections.Generic;
+using ModernUO.Serialization;
+using Server.Commands;
+using Server.Engines.Events;
+using Server.Gumps;
+using Server.Items;
+using Server.Mobiles;
+using Server.Targeting;
+
+namespace Server.Custom.Dfi;
+
+[SerializationGenerator(0)]
+public partial class LastManPentagram : Item
+{
+    // The timer ticks every six seconds.
+    private const double TickSeconds = 6.0;
+
+    [SerializableField(0)]
+    [InvalidateProperties]
+    [SerializedCommandProperty(AccessLevel.GameMaster)]
+    private string _pentagramLocation = "Luna";
+
+    [SerializableField(1)]
+    [SerializedCommandProperty(AccessLevel.GameMaster)]
+    private bool _giveReward = true;
+
+    [SerializableField(2, getter: "private", setter: "private")]
+    private int _ticksRequired = 10;
+
+    // Minutes of countdown before the pentagram becomes active.
+    [SerializableField(3)]
+    [SerializedCommandProperty(AccessLevel.GameMaster)]
+    private int _count = 10;
+
+    [SerializableField(4, getter: "private", setter: "private")]
+    private PentagramAddon _addon;
+
+    [SerializableField(5, setter: "private")]
+    private bool _daily;
+
+    [SerializableField(6, setter: "private")]
+    private TimeSpan _dailyAt = new(19, 15, 0);
+
+    private PentagramTimer _timer;
+    private CallbackScheduledEvent _schedule;
+
+    [Constructible(AccessLevel.Administrator)]
+    public LastManPentagram() : base(0x1F1C)
+    {
+        Movable = false;
+        Visible = false;
+        _addon = new PentagramAddon();
+    }
+
+    public override string DefaultName => "last man pentagram";
+
+    [CommandProperty(AccessLevel.GameMaster)]
+    public int SecondsRequired
+    {
+        get => (int)(_ticksRequired * TickSeconds);
+        set => TicksRequired = Math.Max(1, (int)(value / TickSeconds));
+    }
+
+    // Starts the event every day at DailyAt (UTC).
+    [CommandProperty(AccessLevel.GameMaster)]
+    public bool AutoDaily
+    {
+        get => _daily;
+        set
+        {
+            Daily = value;
+            Reschedule();
+        }
+    }
+
+    [CommandProperty(AccessLevel.GameMaster)]
+    public TimeSpan DailyAtUtc
+    {
+        get => _dailyAt;
+        set
+        {
+            DailyAt = new TimeSpan(value.Hours, value.Minutes, 0);
+            Reschedule();
+        }
+    }
+
+    [CommandProperty(AccessLevel.GameMaster)]
+    public bool Running
+    {
+        get => _timer?.Running == true;
+        set
+        {
+            if (value == Running)
+            {
+                return;
+            }
+
+            if (value)
+            {
+                Start();
+            }
+            else
+            {
+                Cancel();
+            }
+        }
+    }
+
+    public void Start()
+    {
+        if (Running || Map == null || Map == Map.Internal)
+        {
+            return;
+        }
+
+        _timer = new PentagramTimer(this);
+        _timer.Start();
+    }
+
+    public void Cancel()
+    {
+        if (!Running)
+        {
+            return;
+        }
+
+        _timer.Stop();
+        _timer = null;
+        CommandHandlers.BroadcastMessage(AccessLevel.Player, 1150, "The pentagram event has been cancelled.");
+    }
+
+    private void Reschedule()
+    {
+        _schedule?.Cancel();
+        _schedule = null;
+
+        if (_daily && !Deleted)
+        {
+            _schedule = new CallbackScheduledEvent(TimeOnly.FromTimeSpan(_dailyAt), Start, EventScheduler.Daily);
+            _schedule.Schedule(DateTime.UtcNow);
+        }
+    }
+
+    [AfterDeserialization]
+    private void AfterDeserialization()
+    {
+        if (_ticksRequired <= 0)
+        {
+            _ticksRequired = 10;
+        }
+
+        Reschedule();
+    }
+
+    public override void OnDoubleClick(Mobile from)
+    {
+        if (from.AccessLevel > AccessLevel.Player)
+        {
+            from.SendGump(new PropertiesGump(from, this));
+        }
+    }
+
+    public override void OnLocationChange(Point3D oldLocation)
+    {
+        base.OnLocationChange(oldLocation);
+
+        if (_addon?.Deleted == false)
+        {
+            _addon.Location = Location;
+        }
+    }
+
+    public override void OnMapChange()
+    {
+        base.OnMapChange();
+
+        if (_addon?.Deleted == false)
+        {
+            _addon.Map = Map;
+        }
+    }
+
+    public override void OnAfterDelete()
+    {
+        _timer?.Stop();
+        _timer = null;
+        _schedule?.Cancel();
+        _schedule = null;
+        _addon?.Delete();
+        _addon = null;
+        base.OnAfterDelete();
+    }
+
+    private string Announcement(int minutes) =>
+        $"The pentagram at {_pentagramLocation} will be active in {minutes} minutes. The first one who stands on it alone for {SecondsRequired} seconds will receive a random reward. Hiding at this pentagram is deadly mistake.";
+
+    private class PentagramTimer : Timer
+    {
+        private readonly LastManPentagram _pentagram;
+        private int _countdown;
+        private bool _active;
+        private Mobile _winner;
+        private int _held;
+
+        public PentagramTimer(LastManPentagram pentagram) : base(TimeSpan.FromSeconds(TickSeconds), TimeSpan.FromSeconds(TickSeconds))
+        {
+            _pentagram = pentagram;
+            _countdown = pentagram._count * 10;
+            CommandHandlers.BroadcastMessage(AccessLevel.Player, 1150, pentagram.Announcement(pentagram._count));
+        }
+
+        protected override void OnTick()
+        {
+            var p = _pentagram;
+
+            if (p.Deleted || p.Map == null || p.Map == Map.Internal)
+            {
+                Stop();
+                return;
+            }
+
+            string message = null;
+
+            if (!_active)
+            {
+                if (--_countdown < 1)
+                {
+                    _active = true;
+                    CommandHandlers.BroadcastMessage(AccessLevel.Player, 1150, $"The pentagram at {p._pentagramLocation} is active!");
+                }
+                else if (_countdown % 10 == 0)
+                {
+                    CommandHandlers.BroadcastMessage(AccessLevel.Player, 1150, p.Announcement(_countdown / 10));
+                }
+            }
+            else
+            {
+                message = CheckWinner(p);
+            }
+
+            if (!Running)
+            {
+                return;
+            }
+
+            // Everyone near the pentagram may be attacked freely.
+            var near = new List<Mobile>();
+
+            foreach (var m in p.Map.GetMobilesInRange(p.Location, 20))
+            {
+                if (m.Player && m.Alive)
+                {
+                    near.Add(m);
+                }
+            }
+
+            foreach (var m in near)
+            {
+                if (m.AccessLevel == AccessLevel.Player)
+                {
+                    m.Criminal = true;
+                }
+
+                if (message != null)
+                {
+                    m.SendMessage(message);
+                }
+            }
+        }
+
+        private string CheckWinner(LastManPentagram p)
+        {
+            var standing = new List<Mobile>();
+
+            foreach (var m in p.Map.GetMobilesInRange(p.Location, 2))
+            {
+                if (m.Player && m.Alive && m.AccessLevel == AccessLevel.Player)
+                {
+                    standing.Add(m);
+                }
+            }
+
+            for (var i = standing.Count - 1; i >= 0; i--)
+            {
+                if (standing[i].Hidden)
+                {
+                    standing[i].Kill();
+                    standing.RemoveAt(i);
+                }
+            }
+
+            var location = p._pentagramLocation;
+
+            if (standing.Count != 1)
+            {
+                _held = 0;
+                var none = $"No person could be appointed to be the only one standing on the {location} pentagram";
+
+                if (Utility.Random(6) == 0)
+                {
+                    CommandHandlers.BroadcastMessage(AccessLevel.Player, 1150, none);
+                    return null;
+                }
+
+                return none;
+            }
+
+            string message = null;
+
+            if (standing[0] == _winner)
+            {
+                var appointed = $"{_winner.Name} was appointed as the sole person standing on the {location} pentagram!";
+
+                if (_held == 0)
+                {
+                    CommandHandlers.BroadcastMessage(AccessLevel.Player, 1150, appointed);
+                }
+                else
+                {
+                    message = appointed;
+                }
+
+                _held++;
+            }
+            else
+            {
+                _winner = standing[0];
+                _held = 0;
+            }
+
+            if (_held >= p._ticksRequired)
+            {
+                if (p._giveReward)
+                {
+                    var reward = PentagramRewards.Give(_winner);
+                    CommandHandlers.BroadcastMessage(AccessLevel.Player, 1150, $"{_winner.Name} has won the pentagram event, and received {reward}.");
+                }
+                else
+                {
+                    CommandHandlers.BroadcastMessage(AccessLevel.Player, 1150, $"{_winner.Name} has won the pentagram event.");
+                }
+
+                Stop();
+                return null;
+            }
+
+            return message;
+        }
+    }
+}
+
+public static class PentagramRewards
+{
+    private static readonly Type[] _statues =
+    [
+        typeof(StatueSouth), typeof(StatueEast), typeof(StatueEast2), typeof(StatueNorth), typeof(StatueSouth2),
+        typeof(StatueWest), typeof(StatueSouthEast)
+    ];
+
+    private static readonly Type[] _minorArtifacts =
+    [
+        typeof(LunaLance), typeof(VioletCourage), typeof(CavortingClub), typeof(NightsKiss), typeof(CaptainQuacklebushsCutlass),
+        typeof(ShipModelOfTheHMSCape), typeof(AdmiralsHeartyRum), typeof(CandelabraOfSouls), typeof(IolosLute),
+        typeof(GwennosHarp), typeof(ArcticDeathDealer), typeof(EnchantedTitanLegBone), typeof(NoxRangersHeavyCrossbow),
+        typeof(BlazeOfDeath), typeof(DreadPirateHat), typeof(BurglarsBandana), typeof(GoldBricks), typeof(AlchemistsBauble),
+        typeof(PhillipsWoodenSteed), typeof(PolarBearMask), typeof(BowOfTheJukaKing), typeof(GlovesOfThePugilist),
+        typeof(OrcishVisage), typeof(StaffOfPower), typeof(ShieldOfInvulnerability), typeof(HeartOfTheLion), typeof(ColdBlood),
+        typeof(GhostShipAnchor), typeof(SeahorseStatuette), typeof(WrathOfTheDryad), typeof(PixieSwatter)
+    ];
+
+    // Commonest first: the roll favours the low end.
+    private static readonly Type[] _stealables =
+    [
+        typeof(RockArtifact), typeof(SkullCandleArtifact), typeof(BottleArtifact), typeof(DamagedBooksArtifact),
+        typeof(StretchedHideArtifact), typeof(BrazierArtifact), typeof(LampPostArtifact), typeof(BooksNorthArtifact),
+        typeof(BooksWestArtifact), typeof(BooksFaceDownArtifact), typeof(StuddedLeggingsArtifact), typeof(EggCaseArtifact),
+        typeof(SkinnedGoatArtifact), typeof(GruesomeStandardArtifact), typeof(BloodyWaterArtifact), typeof(TarotCardsArtifact),
+        typeof(BackpackArtifact), typeof(StuddedTunicArtifact), typeof(CocoonArtifact), typeof(SkinnedDeerArtifact),
+        typeof(SaddleArtifact), typeof(LeatherTunicArtifact)
+    ];
+
+    private static readonly (Type Type, string Name)[] _ingots =
+    [
+        (typeof(DullCopperIngot), "dull copper"), (typeof(ShadowIronIngot), "shadow iron"), (typeof(CopperIngot), "copper"),
+        (typeof(BronzeIngot), "bronze"), (typeof(GoldIngot), "golden"), (typeof(AgapiteIngot), "agapite"),
+        (typeof(VeriteIngot), "verite"), (typeof(ValoriteIngot), "valorite")
+    ];
+
+    // Gives the winner a reward and returns what to call it in the broadcast.
+    public static string Give(Mobile m)
+    {
+        if (Utility.Random(100) < 33)
+        {
+            var statue = _statues.RandomElement().CreateInstance<Item>();
+            var now = Core.Now;
+            statue.Name = $"{m.Name} - pentagram event winner - {now.Day}/{now.Month}/{now.Year}";
+            statue.LootType = LootType.Blessed;
+            m.AddToBackpack(statue);
+            return "a named statue!!!";
+        }
+
+        var chance = Utility.Random(1000);
+        Item reward = null;
+        string text;
+
+        switch (chance)
+        {
+            case < 60:
+                {
+                    EventRewardSystem.CreateCopperBar(m, Utility.Random(5) + 1, "Pentagram event");
+                    text = "a few copper bars";
+                    break;
+                }
+            case < 100:
+                {
+                    var bonus = Utility.Random(5) * 5 + 5;
+                    reward = new SkillBall(bonus);
+                    text = $"a skillball training {bonus} skill points";
+                    break;
+                }
+            case < 140:
+                {
+                    reward = new RunicSewingKit(CraftResource.SpinedLeather, 5);
+                    text = "5 uses spined runic sewing kit";
+                    break;
+                }
+            case < 160:
+                {
+                    reward = new RunicSewingKit(CraftResource.HornedLeather, 2);
+                    text = "2 uses horned runic sewing kit";
+                    break;
+                }
+            case < 165:
+                {
+                    reward = new RunicSewingKit(CraftResource.BarbedLeather, 1);
+                    text = "1 use barbed runic sewing kit";
+                    break;
+                }
+            case < 345:
+                {
+                    (reward, text) = chance switch
+                    {
+                        < 205 => (new RunicHammer(CraftResource.DullCopper, 10), "10 uses dull copper runic hammer"),
+                        < 240 => (new RunicHammer(CraftResource.ShadowIron, 7), "7 uses shadow iron runic hammer"),
+                        < 270 => (new RunicHammer(CraftResource.Copper, 5), "5 uses copper runic hammer"),
+                        < 295 => (new RunicHammer(CraftResource.Bronze, 4), "4 uses bronze runic hammer"),
+                        < 315 => (new RunicHammer(CraftResource.Gold, 3), "3 uses gold runic hammer"),
+                        < 330 => (new RunicHammer(CraftResource.Agapite, 2), "2 uses agapite runic hammer"),
+                        < 340 => (new RunicHammer(CraftResource.Verite, 1), "1 use verite runic hammer"),
+                        _     => ((Item)new RunicHammer(CraftResource.Valorite, 1), "1 use valorite runic hammer")
+                    };
+                    break;
+                }
+            case < 395:
+                {
+                    var (type, name) = _ingots.RandomElement();
+                    reward = type.CreateInstance<Item>();
+                    reward.Amount = Utility.Random(150, 151);
+                    text = $"some {name} ingots";
+                    break;
+                }
+            case < 445:
+                {
+                    m.AddToBackpack(new Gold(500, 3000));
+                    text = "some gold coins";
+                    break;
+                }
+            case < 500:
+                {
+                    var amount = Utility.Random(1, 10) * 5000;
+                    reward = new BankCheck(amount);
+                    text = $"a bank check worth {amount} gold";
+                    break;
+                }
+            case < 570:
+                {
+                    reward = _minorArtifacts.RandomElement().CreateInstance<Item>();
+                    text = "a random minor artifact";
+                    break;
+                }
+            case < 610:
+                {
+                    reward = new ClothingBlessDeed();
+                    text = "a clothing bless deed";
+                    break;
+                }
+            case < 650:
+                {
+                    reward = new PowerScroll(PowerScroll.Skills.RandomElement(), 100 + (Utility.Random(3) + 1) * 5);
+                    text = "a random powerscroll";
+                    break;
+                }
+            case < 710:
+                {
+                    new Barracoon().MoveToWorld(m.Location, m.Map);
+                    text = "nothing, but managed to spawn Barracoon at the Pentagram!!!";
+                    break;
+                }
+            case < 720:
+                {
+                    reward = new StatCapScroll(225 + (Utility.Random(4) + 1) * 5);
+                    text = "a random statscroll";
+                    break;
+                }
+            case < 735: // DFI's kill book, a donation item here
+                {
+                    EventRewardSystem.CreateCopperBar(m, Utility.Random(5) + 1, "Pentagram event");
+                    text = "a few copper bars";
+                    break;
+                }
+            case < 900:
+                {
+                    var rnd = Math.Min(Utility.Random(1, 22), Utility.Random(1, 22));
+                    reward = _stealables[Utility.Random(rnd)].CreateInstance<Item>();
+                    text = "a random stealable artifact";
+                    break;
+                }
+            case < 930:
+                {
+                    reward = new PetBondingDeed();
+                    text = "a pet bonding deed";
+                    break;
+                }
+            default:
+                {
+                    EventRewardSystem.CreateCopperBar(m, Utility.Random(3) + 1, "Pentagram event");
+                    text = "several copper bars";
+                    break;
+                }
+        }
+
+        if (reward != null)
+        {
+            m.AddToBackpack(reward);
+            new CursedArtifactTimer(reward, 10).Start();
+        }
+
+        return text;
+    }
+}
+
+// Keeps an event prize cursed for a while and hues whoever carries it, so the rest can hunt them down. It cannot
+// be banked meanwhile.
+public class CursedArtifactTimer : Timer
+{
+    public const int DefaultMinutes = 7;
+
+    private readonly Item _artifact;
+    private Mobile _carrier;
+    private Container _container;
+    private int _ticksLeft;
+
+    public CursedArtifactTimer(Item artifact, int minutes) : base(TimeSpan.Zero, TimeSpan.FromSeconds(1.0))
+    {
+        _artifact = artifact;
+        _artifact.LootType = LootType.Cursed;
+        _ticksLeft = (minutes <= 0 ? DefaultMinutes : minutes) * 60;
+    }
+
+    protected override void OnTick()
+    {
+        if (_artifact.Deleted)
+        {
+            Clear();
+            Stop();
+            return;
+        }
+
+        if (_ticksLeft <= 0)
+        {
+            _artifact.LootType = _artifact switch
+            {
+                PetBondingDeed or BankCheck or ClothingBlessDeed => LootType.Blessed,
+                PowerScroll or StatCapScroll                     => LootType.Cursed,
+                _                                                => LootType.Regular
+            };
+
+            Clear();
+            Stop();
+            return;
+        }
+
+        switch (_artifact.RootParent)
+        {
+            case Mobile mob:
+                {
+                    if (_container != null)
+                    {
+                        _container.Hue = 0;
+                        _container = null;
+                    }
+                    else if (_carrier != mob)
+                    {
+                        if (_carrier != null)
+                        {
+                            _carrier.SolidHueOverride = -1;
+                        }
+
+                        _carrier = mob;
+                        _carrier.SolidHueOverride = 18;
+                    }
+
+                    for (var parent = _artifact.Parent as Container; parent != null; parent = parent.Parent as Container)
+                    {
+                        if (parent is BankBox)
+                        {
+                            mob.AddToBackpack(_artifact);
+                            mob.SendMessage("You are not allowed to bank event items.");
+                            mob.Kill();
+                            break;
+                        }
+                    }
+
+                    if (_carrier != null)
+                    {
+                        _carrier.Criminal = true;
+                    }
+
+                    break;
+                }
+            case Container root:
+                {
+                    if (_carrier != null)
+                    {
+                        _carrier.SolidHueOverride = -1;
+                        _carrier = null;
+                    }
+                    else if (_container != root)
+                    {
+                        if (_container != null)
+                        {
+                            _container.Hue = 0;
+                        }
+
+                        _container = root;
+                        _container.Hue = 18;
+                    }
+
+                    break;
+                }
+            default:
+                {
+                    if (_carrier != null && _carrier.Holding != _artifact)
+                    {
+                        _carrier.SolidHueOverride = -1;
+                        _carrier = null;
+                    }
+
+                    if (_container != null)
+                    {
+                        _container.Hue = 0;
+                        _container = null;
+                    }
+
+                    break;
+                }
+        }
+
+        _ticksLeft--;
+
+        if (_carrier?.Hidden == true)
+        {
+            _carrier.Hidden = false;
+        }
+    }
+
+    private void Clear()
+    {
+        if (_carrier != null)
+        {
+            _carrier.SolidHueOverride = -1;
+        }
+
+        if (_container != null)
+        {
+            _container.Hue = 0;
+        }
+    }
+}
+
+public static class CurseArtifactCommand
+{
+    public static void Configure()
+    {
+        CommandSystem.Register("CurseArtifact", AccessLevel.GameMaster, OnCommand);
+    }
+
+    [Usage("CurseArtifact [duration minutes]")]
+    [Description("Temporarily makes an item Cursed and highlights whoever player is carrying it.")]
+    private static void OnCommand(CommandEventArgs e)
+    {
+        var minutes = e.Length >= 1 ? e.GetInt32(0) : CursedArtifactTimer.DefaultMinutes;
+        e.Mobile.SendMessage("Target the item you want to curse.");
+        e.Mobile.Target = new InternalTarget(minutes);
+    }
+
+    private class InternalTarget : Target
+    {
+        private readonly int _minutes;
+
+        public InternalTarget(int minutes) : base(12, true, TargetFlags.None) => _minutes = minutes;
+
+        protected override void OnTarget(Mobile from, object targeted)
+        {
+            if (targeted is not Item item)
+            {
+                return;
+            }
+
+            if (!item.Movable)
+            {
+                from.SendMessage("That item is not movable");
+            }
+            else
+            {
+                new CursedArtifactTimer(item, _minutes).Start();
+            }
+        }
+    }
+}
