+// DFI Network's dungeon treasure chests, ported from DFI RUNUO Scripts/Custom/Items/Containers/ItemChest
+// (BaseItemChest.cs, ItemChests.cs, SpawnEIC.cs, WorldTimer).
+
+using System;
+using System.Collections.Generic;
+using ModernUO.Serialization;
+using Server.Commands;
+using Server.Custom.Dfi;
+using Server.Logging;
+using Server.Mobiles;
+using Server.Regions;
+
+namespace Server.Items;
+
+// A locked, often trapped chest that fills when it is picked and locks itself again 20 to 40 minutes later,
+// emptied. Its level (1 to 7) sets the lock, the trap and the loot; relocking may call up a guard from the
+// dungeon it stands in. Level 7 is the Cursed Cave's.
+[SerializationGenerator(0)]
+public abstract partial class BaseItemChest : LockableContainer
+{
+    public const int MaxLevel = 7;
+
+    private static readonly HashSet<BaseItemChest> _waiting = [];
+    private static Timer _timer;
+
+    private static readonly Type[] _sePotions =
+        [typeof(ConflagrationPotion), typeof(GreaterConflagrationPotion), typeof(ConfusionBlastPotion), typeof(GreaterConfusionBlastPotion)];
+
+    [SerializableField(0)]
+    private bool _itemsCreated;
+
+    [SerializableField(1)]
+    [SerializedCommandProperty(AccessLevel.GameMaster)]
+    private int _level;
+
+    [SerializableField(2)]
+    [SerializedCommandProperty(AccessLevel.GameMaster)]
+    private TimeSpan _minDelay = TimeSpan.FromMinutes(20);
+
+    [SerializableField(3)]
+    [SerializedCommandProperty(AccessLevel.GameMaster)]
+    private TimeSpan _maxDelay = TimeSpan.FromMinutes(40);
+
+    [SerializableField(4)]
+    [SerializedCommandProperty(AccessLevel.GameMaster)]
+    private bool _canBeTrapped = true;
+
+    [SerializableField(5)]
+    private DateTime _relockAt;
+
+    public BaseItemChest(int level, int itemID) : base(itemID)
+    {
+        Movable = false;
+        _level = Math.Clamp(level, 1, MaxLevel);
+        SetLockAndTrap();
+    }
+
+    public override bool IsDecoContainer => false;
+
+    public static int Waiting => _waiting.Count;
+
+    public virtual void SetLockAndTrap()
+    {
+        if (!Locked || LockLevel == -255)
+        {
+            SpawnGuard();
+        }
+
+        Locked = true;
+        RequiredSkill = LockLevel = Utility.RandomMinMax(13 * _level, 14 * _level);
+        TrapPower = Utility.RandomMinMax(10 * _level, 14 * _level);
+
+        if (Utility.RandomBool() && _canBeTrapped && _level > Utility.Random(5))
+        {
+            TrapType = (TrapType)Utility.Random(5);
+        }
+
+        ItemsCreated = false;
+    }
+
+    public static bool CheckLootChance(int level, double chance) => level * chance > Utility.RandomDouble();
+
+    public override void LockPick(Mobile from)
+    {
+        base.LockPick(from);
+
+        if (!_itemsCreated)
+        {
+            if (CheckLootChance(_level, 0.15))
+            {
+                AddLoot(from, this, _level);
+            }
+
+            ItemsCreated = true;
+            ScheduleRelock();
+        }
+    }
+
+    public override void OnItemLifted(Mobile from, Item item)
+    {
+        from.RevealingAction();
+        base.OnItemLifted(from, item);
+    }
+
+    public static void AddLoot(Mobile from, Container c, int level)
+    {
+        var luck = (int)(Math.Pow(Math.Min(1200, from.Luck), 1 / 1.8) / 1000); // up to 0.05
+
+        if (CheckLootChance(level, 0.15 + luck))
+        {
+            c.DropItem(new Gold(level * 40, level * 80));
+        }
+
+        if (CheckLootChance(level, 0.10 + luck))
+        {
+            for (var i = 0; i < level; i++)
+            {
+                var necro = Utility.RandomBool();
+                var regs = Utility.RandomMinMax(1, 5);
+
+                for (var r = 0; r < regs; r++)
+                {
+                    c.DropItem(necro ? Loot.RandomNecromancyReagent() : Loot.RandomReagent());
+                }
+            }
+        }
+
+        if (CheckLootChance(level, 0.10 + luck))
+        {
+            for (var i = 0; i < level; i++)
+            {
+                c.DropItem(
+                    Utility.RandomBool()
+                        ? Loot.RandomScroll(0, 15, SpellbookType.Necromancer)
+                        : Loot.RandomScroll(0, 62, SpellbookType.Regular)
+                );
+            }
+        }
+
+        var minIntensity = level == 7 ? 50 + luck * 200 : level * luck * 200;
+        var minProps = Math.Max(1, Math.Min(4, (level + luck * 100) / 3));
+        var percentScale = luck * 10 + (level == 7 ? 30 : level * 3);
+        DfiLoot.AddRandomLoot(c, level, percentScale * 12, minProps, 5, minIntensity, 100);
+
+        if (CheckLootChance(level, 0.10))
+        {
+            if (level == 7)
+            {
+                var count = Utility.RandomMinMax(1, 5);
+
+                for (var i = 0; i < count; ++i)
+                {
+                    c.DropItem(Loot.Construct(_sePotions));
+                }
+            }
+
+            var potions = Utility.Random(level) + 1;
+
+            for (var i = 0; i < potions; i++)
+            {
+                c.DropItem(Loot.RandomPotion());
+            }
+        }
+
+        if (level == 7 && Utility.RandomDouble() < 0.05)
+        {
+            c.DropItem(new CCKey());
+        }
+
+        if (CheckLootChance(level, 0.10))
+        {
+            CursedCave.PackSkullsAndSmallBones(c, Utility.Random(1, 3));
+        }
+    }
+
+    private void ScheduleRelock()
+    {
+        RelockAt = Core.Now + TimeSpan.FromSeconds(Utility.RandomMinMax((int)_minDelay.TotalSeconds, (int)_maxDelay.TotalSeconds));
+        _waiting.Add(this);
+        _timer ??= Timer.DelayCall(TimeSpan.FromSeconds(30.0), TimeSpan.FromSeconds(30.0), CheckRelocks);
+    }
+
+    private static void CheckRelocks()
+    {
+        foreach (var chest in new List<BaseItemChest>(_waiting))
+        {
+            if (chest.Deleted)
+            {
+                _waiting.Remove(chest);
+            }
+            else if (chest._relockAt <= Core.Now)
+            {
+                _waiting.Remove(chest);
+                chest.Relock();
+            }
+        }
+    }
+
+    public void Relock()
+    {
+        for (var i = Items.Count - 1; i >= 0; --i)
+        {
+            Items[i].Delete();
+        }
+
+        SetLockAndTrap();
+    }
+
+    [AfterDeserialization]
+    private void AfterDeserialization()
+    {
+        if (!Locked || LockLevel == -255 || _itemsCreated)
+        {
+            ScheduleRelock();
+        }
+    }
+
+    public override void OnAfterDelete()
+    {
+        _waiting.Remove(this);
+        base.OnAfterDelete();
+    }
+
+    // One time in ten a relock calls a guard from the dungeon's own kind of creature.
+    private void SpawnGuard()
+    {
+        if (Map == null || Map == Map.Internal || Utility.Random(10) != 0)
+        {
+            return;
+        }
+
+        var region = Region.Find(Location, Map);
+        var group = region switch
+        {
+            _ when region.IsPartOf("Khaldun") || region.IsPartOf("Deceit") => 1,
+            _ when region.IsPartOf("Despise")                               => 2,
+            _ when region.IsPartOf("Shame")                                 => 3,
+            _ when region.IsPartOf("Orc Cave")                              => 4,
+            _ when region.IsPartOf("Hythloth")                              => 5,
+            _ when region.IsPartOf("Covetous")                              => 6,
+            _ when region.IsPartOf("Destard")                               => 7,
+            _ when region.IsPartOf("Fire")                                  => 8,
+            _ when region.IsPartOf("Ice")                                   => 9,
+            _ when region is CursedCaveRegion || _level == 7               => 10,
+            _ when _level == 6                                              => 11,
+            _ when _level == 5                                              => 12,
+            _ when _level == 4                                              => 13,
+            _                                                               => 0
+        };
+
+        var bc = _guards[group].RandomElement().CreateInstance<BaseCreature>();
+        bc.Home = Location;
+        bc.RangeHome = 5;
+
+        for (var i = 0; i < 10; ++i)
+        {
+            var x = X - 3 + Utility.Random(7);
+            var y = Y - 3 + Utility.Random(7);
+
+            if (Map.CanSpawnMobile(x, y, Z))
+            {
+                bc.MoveToWorld(new Point3D(x, y, Z), Map);
+                return;
+            }
+
+            var z = Map.GetAverageZ(x, y);
+
+            if (Map.CanSpawnMobile(x, y, z))
+            {
+                bc.MoveToWorld(new Point3D(x, y, z), Map);
+                return;
+            }
+        }
+
+        bc.Delete();
+    }
+
+    private static readonly Type[][] _guards =
+    [
+        [typeof(Mongbat), typeof(Ratman), typeof(HeadlessOne), typeof(Skeleton), typeof(Zombie), typeof(Mummy), typeof(Shade)],
+        [typeof(Lich), typeof(SpectralArmour), typeof(BoneKnight), typeof(BoneMagi), typeof(SkeletalMage), typeof(SkeletalKnight)],
+        [typeof(Ettin), typeof(Lizardman), typeof(Troll), typeof(EarthElemental)],
+        [typeof(Scorpion), typeof(EarthElemental), typeof(AirElemental), typeof(DullCopperElemental)],
+        [typeof(OrcishMage), typeof(OrcishLord), typeof(Orc), typeof(OrcBomber), typeof(DireWolf)],
+        [typeof(Gargoyle), typeof(FireGargoyle), typeof(StoneGargoyle), typeof(Gazer), typeof(ElderGazer), typeof(HellHound), typeof(Daemon), typeof(Imp)],
+        [typeof(Lich), typeof(Mummy), typeof(Shade), typeof(SkeletalKnight), typeof(DreadSpider), typeof(AirElemental), typeof(SwampTentacle), typeof(Gazer), typeof(ElderGazer)],
+        [typeof(Dragon), typeof(Drake), typeof(Wyvern), typeof(Snake), typeof(GiantSerpent), typeof(Lizardman)],
+        [typeof(FireElemental), typeof(LavaSerpent), typeof(LavaSnake), typeof(HellCat), typeof(HellHound), typeof(EvilMage)],
+        [typeof(IceElemental), typeof(SnowElemental), typeof(FrostSpider), typeof(IceSnake), typeof(FrostOoze), typeof(FrostTroll)],
+        [typeof(TheCursed), typeof(TheCursedArcher), typeof(TheCursedWarrior), typeof(TheCursedGuardian)],
+        [typeof(AncientWyrm), typeof(Balron), typeof(BloodElemental), typeof(PoisonElemental), typeof(Titan)],
+        [typeof(LichLord), typeof(Daemon), typeof(ElderGazer), typeof(PoisonElemental), typeof(BloodElemental)],
+        [typeof(DreadSpider), typeof(LichLord), typeof(Daemon), typeof(ElderGazer), typeof(OgreLord)]
+    ];
+}
