install -d "$(dirname $BASE/patches/0017-dfi-creatures.patch)"
cat > $BASE/patches/0017-dfi-creatures.patch <<'MUO_EOF_0'
diff --git a/Projects/UOContent.Tests/Tests/Custom/DfiCreatureTests.cs b/Projects/UOContent.Tests/Tests/Custom/DfiCreatureTests.cs
new file mode 100644
index 000000000..e04409830
--- /dev/null
+++ b/Projects/UOContent.Tests/Tests/Custom/DfiCreatureTests.cs
@@ -0,0 +1,159 @@
+using System;
+using System.Collections.Generic;
+using Server;
+using Server.Custom.Dfi;
+using Server.Items;
+using Server.Misc;
+using Server.Mobiles;
+using Xunit;
+
+namespace UOContent.Tests.Custom;
+
+[Collection("Sequential UOContent Tests")]
+public class DfiCreatureTests : IDisposable
+{
+    private readonly List<IEntity> _created = new();
+
+    public DfiCreatureTests()
+    {
+        if (NameList.GetNameList("male") == null)
+        {
+            NameList.Configure();
+        }
+    }
+
+    public static TheoryData<Type> Types =>
+    [
+        typeof(Paladin), typeof(FactionDaemon), typeof(FactionOgreLord), typeof(FactionSilverSerpent), typeof(FactionWisp),
+        typeof(EtherealSkeletalMount), typeof(EtherealWarHorse), typeof(CounselorStaff), typeof(AncientMIB), typeof(AncientSOS)
+    ];
+
+    public void Dispose()
+    {
+        foreach (var e in _created)
+        {
+            if (e is Mobile m)
+            {
+                SphynxFortunes.End(m);
+            }
+
+            e?.Delete();
+        }
+
+        _created.Clear();
+    }
+
+    private T Track<T>(T e) where T : IEntity
+    {
+        _created.Add(e);
+        return e;
+    }
+
+    private PlayerMobile Player()
+    {
+        var m = Track(new PlayerMobile());
+        m.Player = true;
+        m.Body = 0x190;
+        m.AddItem(new Backpack());
+        m.MoveToWorld(new Point3D(1500, 1600, 0), Map.Felucca);
+        return m;
+    }
+
+    [Theory]
+    [MemberData(nameof(Types))]
+    public void Type_Constructs(Type type)
+    {
+        var entity = Track(type.CreateInstance<IEntity>());
+
+        Assert.False(entity.Deleted);
+    }
+
+    [Theory]
+    [InlineData(6, 40, AosAttribute.Luck, 40)]
+    [InlineData(18, 70, AosAttribute.Luck, -70)]
+    [InlineData(7, 15, AosAttribute.EnhancePotions, 15)]
+    [InlineData(19, 5, AosAttribute.DefendChance, -5)]
+    [InlineData(10, 2, AosAttribute.RegenMana, 2)]
+    [InlineData(1, 10, AosAttribute.Luck, 0)]
+    public void Fortune_AddsToItsAttributeOnly(int type, int power, AosAttribute attribute, int expected)
+    {
+        var player = Player();
+
+        SphynxFortunes.Apply(player, type, power, Core.Now.AddHours(1));
+
+        Assert.Equal(expected, SphynxFortunes.GetBonus(player, attribute));
+    }
+
+    [Fact]
+    public void Fortune_ResistanceComesAndGoes()
+    {
+        var player = Player();
+        var before = player.PhysicalResistance;
+
+        SphynxFortunes.Apply(player, 11, 8, Core.Now.AddHours(1));
+        Assert.Equal(before - 8, player.PhysicalResistance);
+
+        SphynxFortunes.End(player);
+        Assert.Equal(before, player.PhysicalResistance);
+        Assert.False(SphynxFortunes.HasFortune(player));
+    }
+
+    [Fact]
+    public void Fortune_OneAtATimeAndItExpires()
+    {
+        var player = Player();
+
+        SphynxFortunes.Apply(player, 6, 40, Core.Now.AddHours(1));
+        SphynxFortunes.Apply(player, 8, 90, Core.Now.AddHours(1));
+        Assert.Equal(40, SphynxFortunes.GetBonus(player, AosAttribute.Luck));
+
+        SphynxFortunes.End(player);
+        SphynxFortunes.Apply(player, 6, 40, Core.Now.AddSeconds(-1));
+        Assert.False(SphynxFortunes.HasFortune(player));
+        Assert.Equal(0, SphynxFortunes.GetBonus(player, AosAttribute.Luck));
+    }
+
+    [Fact]
+    public void Fortune_ReadingAlwaysGivesOne()
+    {
+        for (var i = 0; i < 50; i++)
+        {
+            var player = Player();
+
+            SphynxFortunes.TellFortune(player);
+
+            Assert.True(SphynxFortunes.HasFortune(player));
+        }
+    }
+
+    [Fact]
+    public void Paladin_FightsWithItsOwnAI()
+    {
+        var paladin = Track(new Paladin());
+
+        Assert.IsType<PaladinAI>(paladin.AIObject);
+        Assert.NotNull(paladin.Backpack.FindItemByType<BookOfChivalry>());
+        Assert.Equal(1000, paladin.TithingPoints);
+    }
+
+    [Fact]
+    public void CounselorStaff_RefusesPlayers()
+    {
+        var player = Player();
+        player.RawStr = 100;
+        // The test server loads no tiledata, so the staff gets its layer here.
+        var staff = Track(new CounselorStaff { Layer = Layer.TwoHanded });
+
+        Assert.False(player.EquipItem(staff));
+
+        player.AccessLevel = AccessLevel.Counselor;
+        Assert.True(player.EquipItem(staff));
+    }
+
+    [Fact]
+    public void AncientBottle_HoldsAnAncientSOS()
+    {
+        Assert.Equal(4, Track(new AncientMIB()).Level);
+        Assert.True(Track(new AncientSOS()).IsAncient);
+    }
+}
diff --git a/Projects/UOContent/Custom/DFI/Mobiles/FactionCreatures.cs b/Projects/UOContent/Custom/DFI/Mobiles/FactionCreatures.cs
new file mode 100644
index 000000000..61bd0595f
--- /dev/null
+++ b/Projects/UOContent/Custom/DFI/Mobiles/FactionCreatures.cs
@@ -0,0 +1,140 @@
+// DFI Network's faction creatures and items, ported from DFI RUNUO Scripts/Custom/Engines/Faction/Mobiles,
+// Custom/Mobiles/Ethereal Mounts, Custom/Items/Staff/CounselorStaff.cs and Custom/Items/Misc/AncientMIB.cs,
+// AncientSOS.cs. Each faction creature serves one faction and leaves that faction's players alone.
+
+using ModernUO.Serialization;
+using Server.Factions;
+using Server.Items;
+
+namespace Server.Mobiles
+{
+    [SerializationGenerator(0)]
+    public partial class FactionDaemon : Daemon
+    {
+        [Constructible]
+        public FactionDaemon()
+        {
+        }
+
+        public override Faction FactionAllegiance => Shadowlords.Instance;
+
+        public override bool IsEnemy(Mobile m) =>
+            !(m.Player && Faction.Find(m) == Shadowlords.Instance) && base.IsEnemy(m);
+    }
+
+    [SerializationGenerator(0)]
+    public partial class FactionOgreLord : OgreLord
+    {
+        [Constructible]
+        public FactionOgreLord()
+        {
+        }
+
+        public override Faction FactionAllegiance => Minax.Instance;
+
+        public override bool IsEnemy(Mobile m) => !(m.Player && Faction.Find(m) == Minax.Instance) && base.IsEnemy(m);
+    }
+
+    [SerializationGenerator(0)]
+    public partial class FactionSilverSerpent : SilverSerpent
+    {
+        [Constructible]
+        public FactionSilverSerpent()
+        {
+        }
+
+        public override Faction FactionAllegiance => TrueBritannians.Instance;
+
+        public override bool IsEnemy(Mobile m) =>
+            !(m.Player && Faction.Find(m) == TrueBritannians.Instance) && base.IsEnemy(m);
+    }
+
+    [SerializationGenerator(0)]
+    public partial class FactionWisp : Wisp
+    {
+        [Constructible]
+        public FactionWisp()
+        {
+        }
+
+        public override Faction FactionAllegiance => CouncilOfMages.Instance;
+
+        public override bool IsEnemy(Mobile m) =>
+            !(m.Player && Faction.Find(m) == CouncilOfMages.Instance) && base.IsEnemy(m);
+    }
+
+    [SerializationGenerator(0)]
+    public partial class EtherealSkeletalMount : EtherealMount
+    {
+        [Constructible]
+        public EtherealSkeletalMount() : base(9751, 16059)
+        {
+        }
+
+        public override string DefaultName => "Ethereal Skeletal Steed Statuette";
+        public override int EtherealHue => 0;
+    }
+
+    // Only a faction member may ride it.
+    [SerializationGenerator(0)]
+    public partial class EtherealWarHorse : EtherealMount
+    {
+        [Constructible]
+        public EtherealWarHorse() : base(11676, 16018)
+        {
+        }
+
+        public override string DefaultName => "Ethereal War Horse Statuette";
+        public override int EtherealHue => 0;
+
+        public override void OnDoubleClick(Mobile from)
+        {
+            if (Faction.Find(from) == null)
+            {
+                from.SendMessage("You have to be a faction member to use this item!");
+                return;
+            }
+
+            base.OnDoubleClick(from);
+        }
+    }
+}
+
+namespace Server.Items
+{
+    [SerializationGenerator(0)]
+    public partial class CounselorStaff : BlackStaff
+    {
+        [Constructible(AccessLevel.Counselor)]
+        public CounselorStaff()
+        {
+            Hue = 3;
+            Attributes.NightSight = 1;
+        }
+
+        public override string DefaultName => "Counselor's Staff";
+        public override int InitMinHits => 10;
+        public override int InitMaxHits => 10;
+
+        public override bool OnEquip(Mobile from) => from.AccessLevel > AccessLevel.Player && base.OnEquip(from);
+    }
+
+    // A message in a bottle that always holds an ancient SOS.
+    [SerializationGenerator(0)]
+    public partial class AncientMIB : MessageInABottle
+    {
+        [Constructible]
+        public AncientMIB(Map map = null) : base(map ?? Map.Felucca, 4)
+        {
+        }
+    }
+
+    [SerializationGenerator(0)]
+    public partial class AncientSOS : SOS
+    {
+        [Constructible]
+        public AncientSOS(Map map = null) : base(map ?? Map.Felucca, 4)
+        {
+        }
+    }
+}
diff --git a/Projects/UOContent/Custom/DFI/Mobiles/Paladin.cs b/Projects/UOContent/Custom/DFI/Mobiles/Paladin.cs
new file mode 100644
index 000000000..d0cc4ff2c
--- /dev/null
+++ b/Projects/UOContent/Custom/DFI/Mobiles/Paladin.cs
@@ -0,0 +1,232 @@
+// DFI Network's Paladin, "the Dark Knight", ported from DFI RUNUO Scripts/Custom/Opticon/Paladin AI (Paladin.cs,
+// PaladinAI.cs). DFI's 936-line AI was a copy of the RunUO mage AI casting chivalry; this one keeps what it did
+// in a fight on top of ModernUO's melee AI: cleanse when poisoned, close wounds when hurt, lift curses, and
+// otherwise open with divine fury, enemy of one, consecrate weapon, holy light or dispel evil. Its blows deal a
+// mortal wound one time in ten.
+
+using System;
+using ModernUO.Serialization;
+using Server.Items;
+using Server.Spells;
+using Server.Spells.Chivalry;
+using Server.Spells.Fourth;
+using Server.Spells.First;
+
+namespace Server.Mobiles;
+
+[SerializationGenerator(0)]
+public partial class Paladin : BaseCreature
+{
+    private static readonly TimeSpan PlayerWound = TimeSpan.FromSeconds(6.0);
+    private static readonly TimeSpan CreatureWound = TimeSpan.FromSeconds(12.0);
+
+    [Constructible]
+    public Paladin() : base(AIType.AI_Melee, FightMode.Closest)
+    {
+        Title = "the Dark Knight";
+        Hue = Race.Human.RandomSkinHue();
+        Female = Utility.RandomBool();
+        Body = Female ? 0x191 : 0x190;
+        Name = NameList.RandomName(Female ? "female" : "male");
+        HairItemID = Race.Human.RandomHair(Female);
+        HairHue = Race.Human.RandomHairHue();
+        SetSpeed(0.2, 0.4);
+
+        TithingPoints = 1000;
+
+        SetStr(150);
+        SetDex(100);
+        SetInt(100);
+
+        SetHits(250, 300);
+        SetMana(400);
+
+        SetDamage(10, 20);
+
+        SetDamageType(ResistanceType.Physical, 60);
+        SetDamageType(ResistanceType.Fire, 20);
+        SetDamageType(ResistanceType.Energy, 20);
+
+        SetResistance(ResistanceType.Physical, 65);
+        SetResistance(ResistanceType.Fire, 50);
+        SetResistance(ResistanceType.Cold, 50);
+        SetResistance(ResistanceType.Poison, 100);
+        SetResistance(ResistanceType.Energy, 50);
+
+        SetSkill(SkillName.Chivalry, 95.1, 100.1);
+        SetSkill(SkillName.Focus, 90.1, 100.1);
+        SetSkill(SkillName.Meditation, 100.0);
+        SetSkill(SkillName.MagicResist, 85.1, 95.0);
+        SetSkill(SkillName.Magery, 95.1, 100.0);
+        SetSkill(SkillName.Anatomy, 90.1, 100.1);
+        SetSkill(SkillName.Parry, 85.1, 95.1);
+        SetSkill(SkillName.Tactics, 100.0);
+        SetSkill(SkillName.Swords, 100.0);
+
+        Fame = 5000;
+        Karma = -5000;
+        VirtualArmor = 35;
+
+        var weapon = new VikingSword
+        {
+            DamageLevel = (WeaponDamageLevel)Utility.Random(3, 3),
+            DurabilityLevel = (WeaponDurabilityLevel)Utility.Random(0, 1),
+            AccuracyLevel = (WeaponAccuracyLevel)Utility.Random(3, 3),
+            Skill = SkillName.Swords,
+            Speed = 40,
+            Hue = 0x8A5,
+            Weight = 0.5,
+            Quality = WeaponQuality.Exceptional,
+            Name = "Holy Avenger"
+        };
+        weapon.Attributes.SpellChanneling = 1;
+
+        Wear(weapon);
+        Wear(Female ? new FemalePlateChest { Hue = 0x47E } : new PlateChest { Hue = 0x47E });
+        Wear(new PlateGloves { Hue = 0x47E });
+        Wear(new PlateArms { Hue = 0x47E });
+        Wear(new PlateGorget { Hue = 0x47E });
+        Wear(new PlateHelm { Hue = 0x47E });
+        Wear(new OrderShield());
+        Wear(new PlateLegs { Hue = 0x47E });
+        Wear(new BodySash(0xCF));
+        Wear(new Cloak(0xCF));
+
+        PackItem(new BookOfChivalry { LootType = LootType.Blessed });
+        PackGold(200, 300);
+        PackGem(5, 8);
+        PackGem(3, 6);
+        PackMagicItems(3, 5, 0.50, 0.75);
+        PackMagicItems(3, 5, 0.50, 0.75);
+    }
+
+    public override string CorpseName => "a paladin's corpse";
+    public override Poison PoisonImmune => Poison.Lethal;
+    public override bool AlwaysMurderer => true;
+    public override bool ShowFameTitle => false;
+    public override bool BardImmune => true;
+    public override bool Unprovokable => true;
+    public override bool Uncalmable => true;
+
+    protected override BaseAI ForcedAI => new PaladinAI(this);
+
+    private void Wear(Item item)
+    {
+        item.Movable = false;
+        AddItem(item);
+    }
+
+    // Immune to pets and provoked creatures.
+    public override void AlterMeleeDamageFrom(Mobile from, ref int damage)
+    {
+        if (from is BaseCreature bc && (bc.Controlled || bc.BardTarget == this))
+        {
+            damage = 0;
+        }
+    }
+
+    public override void OnGaveMeleeAttack(Mobile defender, int damage)
+    {
+        base.OnGaveMeleeAttack(defender, damage);
+
+        if (Utility.RandomDouble() < 0.1)
+        {
+            defender.SendLocalizedMessage(1060087); // You have been mortally wounded!
+            defender.PlaySound(0x1E1);
+            defender.FixedParticles(0x37B9, 244, 25, 9944, 31, 0, EffectLayer.Waist);
+            MortalStrike.BeginWound(defender, defender.Player ? PlayerWound : CreatureWound);
+        }
+    }
+}
+
+public class PaladinAI : MeleeAI
+{
+    private long _nextCast;
+
+    public PaladinAI(BaseCreature m) : base(m) => _nextCast = Core.TickCount;
+
+    public override bool Think()
+    {
+        // Every chivalry spell it casts that wants a target is one it means for itself.
+        if (Mobile.Target is SpellTarget<Mobile> target && Mobile.Spell is not null)
+        {
+            target.Invoke(Mobile, Mobile);
+            return true;
+        }
+
+        return base.Think();
+    }
+
+    public override bool DoActionWander()
+    {
+        if (Mobile.Poisoned || Mobile.Hits < Mobile.HitsMax * 0.8)
+        {
+            TryCast(SelfCare());
+        }
+
+        return base.DoActionWander();
+    }
+
+    public override bool DoActionCombat()
+    {
+        var combatant = Mobile.Combatant;
+
+        if (combatant != null && Mobile.InRange(combatant, 12) && Core.TickCount - _nextCast >= 0)
+        {
+            TryCast(SelfCare() ?? Attack(combatant));
+        }
+
+        return base.DoActionCombat();
+    }
+
+    private Spell SelfCare()
+    {
+        if (Mobile.Poisoned)
+        {
+            return new CleanseByFireSpell(Mobile);
+        }
+
+        if (Mobile.Hits < Mobile.HitsMax / 2 && !MortalStrike.IsWounded(Mobile))
+        {
+            return new CloseWoundsSpell(Mobile);
+        }
+
+        if (CurseSpell.UnderEffect(Mobile))
+        {
+            return new RemoveCurseSpell(Mobile);
+        }
+
+        return null;
+    }
+
+    private Spell Attack(Mobile combatant)
+    {
+        // Someone healing with a spell gets the paladin's fury.
+        if (combatant.Spell is GreaterHealSpell or HealSpell)
+        {
+            return new DivineFurySpell(Mobile);
+        }
+
+        return Utility.Random(13) switch
+        {
+            < 3  => new DivineFurySpell(Mobile),
+            < 6  => new EnemyOfOneSpell(Mobile),
+            < 9  => new ConsecrateWeaponSpell(Mobile),
+            < 11 => new HolyLightSpell(Mobile),
+            _    => new DispelEvilSpell(Mobile)
+        };
+    }
+
+    private void TryCast(Spell spell)
+    {
+        if (spell == null || Mobile.Spell?.IsCasting == true || Core.TickCount - _nextCast < 0)
+        {
+            return;
+        }
+
+        if (spell.Cast())
+        {
+            _nextCast = Core.TickCount + Utility.RandomMinMax(4000, 8000);
+        }
+    }
+}
