+// Resurrects murderers and teaches the dark priest's skills.
+[SerializationGenerator(0)]
+public partial class PriestOfMondain : BaseHealer
+{
+    [Constructible]
+    public PriestOfMondain()
+    {
+        Title = "the priest of Mondain";
+        Karma = -10000;
+
+        SetSkill(SkillName.Forensics, 80.0, 100.0);
+        SetSkill(SkillName.SpiritSpeak, 80.0, 100.0);
+        SetSkill(SkillName.Swords, 80.0, 100.0);
+    }
+
+    public override bool CanTeach => true;
+    public override bool AlwaysMurderer => true;
+
+    public override bool CheckTeach(SkillName skill, Mobile from) =>
+        base.CheckTeach(skill, from) && skill is SkillName.Anatomy or SkillName.Parry or SkillName.EvalInt
+            or SkillName.Healing or SkillName.Magery or SkillName.MagicResist or SkillName.Tactics or SkillName.SpiritSpeak;
+
+    public override bool CheckResurrect(Mobile m) => true;
+}
+
+// A dark healer whose resurrection, for a price, restores hits and mana as well.
+[SerializationGenerator(0)]
+public partial class PaidFullHealer : BaseHealer
+{
+    [Constructible]
+    public PaidFullHealer() : base(1000)
+    {
+        Title = "the Priest Of Evil";
+        Karma = -10000;
+        Blessed = true;
+
+        SetDamageType(ResistanceType.Cold, 100);
+
+        SetResistance(ResistanceType.Physical, 40, 80);
+        SetResistance(ResistanceType.Fire, 40, 80);
+        SetResistance(ResistanceType.Cold, 40, 80);
+        SetResistance(ResistanceType.Poison, 40, 80);
+        SetResistance(ResistanceType.Energy, 40, 80);
+
+        SetSkill(SkillName.Wrestling, 100.0, 140.5);
+        SetSkill(SkillName.Anatomy, 75.0, 97.5);
+        SetSkill(SkillName.EvalInt, 100.0, 140.0);
+        SetSkill(SkillName.Healing, 75.0, 97.5);
+        SetSkill(SkillName.Magery, 100.0, 140.0);
+        SetSkill(SkillName.MagicResist, 100.0, 140.0);
+        SetSkill(SkillName.Tactics, 82.0, 100.0);
+    }
+
+    public override bool CanTeach => false;
+
+    public override void InitOutfit()
+    {
+        AddItem(new HoodedShroudOfShadows { LootType = LootType.Blessed });
+
+        var ring = new GoldRing { LootType = LootType.Blessed };
+        ring.Attributes.CastSpeed = 2;
+        ring.Attributes.CastRecovery = 6;
+        AddItem(ring);
+    }
+
+    public override void OfferResurrection(Mobile m)
+    {
+        Direction = GetDirectionTo(m);
+        m.PlaySound(0x214);
+        m.FixedEffect(0x376A, 10, 16);
+        m.SendGump(new PaidFullHealerGump(this), true);
+    }
+}
+
+public class PaidFullHealerGump : StaticGump<PaidFullHealerGump>
+{
+    private readonly PaidFullHealer _healer;
+
+    public PaidFullHealerGump(PaidFullHealer healer) : base(50, 50) => _healer = healer;
+
+    public override bool Singleton => true;
+
+    protected override void BuildLayout(ref StaticGumpBuilder builder)
+    {
+        builder.AddPage();
+        builder.AddBackground(0, 0, 400, 300, 3600);
+        builder.AddImage(-34, 16, 60970);
+        builder.AddImage(-34, 20, 60897, 1193);
+
+        builder.AddRadio(120, 180, 9727, 9730, true, 0);
+        builder.AddLabelPlaceholder(150, 180, 1149, "full");
+        builder.AddRadio(120, 210, 9727, 9730, false, 1);
+        builder.AddLabel(150, 210, 1149, "Regular Resurrection (free)");
+
+        builder.AddButton(270, 250, 247, 248, 1);
+        builder.AddButton(70, 250, 243, 241, 0);
+
+        builder.AddHtml(0, 28, 400, 25, "Resurrection Gump", "#FFFFFF", align: TextAlignment.Center);
+        builder.AddHtml(
+            118, 68, 253, 100,
+            "Psst... hey,<br>Come over here. I see you are in need of some assistance. I can offer you a resurrection and replenish your mana and health for a small price.",
+            "#FFFFFF"
+        );
+    }
+
+    protected override void BuildStrings(ref GumpStringsBuilder builder)
+    {
+        builder.SetStringSlot("full", $"Full Resurrection ({_healer.Price} gp)");
+    }
+
+    public override void OnResponse(NetState sender, in RelayInfo info)
+    {
+        var m = sender.Mobile;
+
+        if (info.ButtonID != 1 || m.Alive)
+        {
+            return;
+        }
+
+        if (!m.InRange(_healer, 16))
+        {
+            m.SendMessage("You have wandered to far off to gain any benefits from the healers practices.");
+            return;
+        }
+
+        if (info.IsSwitched(0) && Banker.Withdraw(m, _healer.Price))
+        {
+            m.Frozen = true;
+            Timer.StartTimer(TimeSpan.FromSeconds(10.0), () => FullResurrect(m));
+        }
+        else
+        {
+            m.Resurrect();
+            m.PlaySound(0x214);
+            m.FixedEffect(0x376A, 10, 16);
+        }
+    }
+
+    public static void FullResurrect(Mobile m)
+    {
+        m.Resurrect();
+        m.Hits = m.HitsMax;
+        m.Mana = m.ManaMax;
+        m.Frozen = false;
+        m.PlaySound(0x214);
+        m.FixedEffect(0x376A, 10, 16);
+    }
+}
