+
+public class SBNecromancer : SBInfo
+{
+    public override IShopSellInfo SellInfo { get; } = new InternalSellInfo();
+    public override List<GenericBuyInfo> BuyInfo { get; } = BuildBuyInfo();
+
+    private static List<GenericBuyInfo> BuildBuyInfo()
+    {
+        var list = new List<GenericBuyInfo>();
+        var types = Loot.RegularScrollTypes;
+
+        for (var i = 0; i < 3 * 8 && i < types.Length; ++i)
+        {
+            var itemID = 0x1F2E + i;
+
+            if (i == 6)
+            {
+                itemID = 0x1F2D;
+            }
+            else if (i > 6)
+            {
+                --itemID;
+            }
+
+            list.Add(new GenericBuyInfo(types[i], 12 + i / 8 * 10, 20, itemID, 0));
+        }
+
+        list.Add(new GenericBuyInfo(typeof(BlackPearl), 5, 999, 0xF7A, 0));
+        list.Add(new GenericBuyInfo(typeof(Bloodmoss), 5, 999, 0xF7B, 0));
+        list.Add(new GenericBuyInfo(typeof(MandrakeRoot), 3, 999, 0xF86, 0));
+        list.Add(new GenericBuyInfo(typeof(Garlic), 3, 999, 0xF84, 0));
+        list.Add(new GenericBuyInfo(typeof(Ginseng), 3, 999, 0xF85, 0));
+        list.Add(new GenericBuyInfo(typeof(Nightshade), 3, 999, 0xF88, 0));
+        list.Add(new GenericBuyInfo(typeof(SpidersSilk), 3, 999, 0xF8D, 0));
+        list.Add(new GenericBuyInfo(typeof(SulfurousAsh), 3, 999, 0xF8C, 0));
+
+        if (Core.AOS)
+        {
+            list.Add(new GenericBuyInfo(typeof(BatWing), 3, 999, 0xF78, 0));
+            list.Add(new GenericBuyInfo(typeof(GraveDust), 3, 999, 0xF8F, 0));
+            list.Add(new GenericBuyInfo(typeof(DaemonBlood), 6, 999, 0xF7D, 0));
+            list.Add(new GenericBuyInfo(typeof(NoxCrystal), 6, 999, 0xF8E, 0));
+            list.Add(new GenericBuyInfo(typeof(PigIron), 5, 999, 0xF8A, 0));
+            list.Add(new GenericBuyInfo(typeof(NecromancerSpellbook), 115, 10, 0x2253, 0));
+        }
+
+        list.Add(new GenericBuyInfo(typeof(BlankScroll), 5, 20, 0x0E34, 0));
+        list.Add(new GenericBuyInfo(typeof(RecallRune), 25, 10, 0x1f14, 0));
+        list.Add(new GenericBuyInfo(typeof(Spellbook), 50, 10, 0xEFA, 0));
+
+        return list;
+    }
+
+    public class InternalSellInfo : GenericSellInfo
+    {
+        public InternalSellInfo()
+        {
+            Add(typeof(Runebook), 1250);
+            Add(typeof(BlackPearl), 3);
+            Add(typeof(Bloodmoss), 3);
+            Add(typeof(MandrakeRoot), 2);
+            Add(typeof(Garlic), 2);
+            Add(typeof(Ginseng), 2);
+            Add(typeof(Nightshade), 2);
+            Add(typeof(SpidersSilk), 2);
+            Add(typeof(SulfurousAsh), 2);
+            Add(typeof(RecallRune), 8);
+            Add(typeof(Spellbook), 9);
+            Add(typeof(BlankScroll), 2);
+
+            Add(typeof(TotalRefreshPotion), 7);
+            Add(typeof(GreaterAgilityPotion), 7);
+            Add(typeof(GreaterHealPotion), 7);
+            Add(typeof(GreaterStrengthPotion), 7);
+            Add(typeof(GreaterPoisonPotion), 7);
+            Add(typeof(GreaterCurePotion), 7);
+            Add(typeof(GreaterExplosionPotion), 10);
+            Add(typeof(RefreshPotion), 7);
+            Add(typeof(AgilityPotion), 7);
+            Add(typeof(NightSightPotion), 7);
+            Add(typeof(LesserHealPotion), 7);
+            Add(typeof(StrengthPotion), 7);
+            Add(typeof(LesserPoisonPotion), 7);
+            Add(typeof(LesserCurePotion), 7);
+            Add(typeof(LesserExplosionPotion), 10);
+
+            if (Core.AOS)
+            {
+                Add(typeof(ConfusionBlastPotion), 10);
+                Add(typeof(ConflagrationPotion), 10);
+                Add(typeof(GreaterConflagrationPotion), 10);
+                Add(typeof(GreaterConfusionBlastPotion), 10);
+                Add(typeof(NoxCrystal), 3);
+                Add(typeof(BatWing), 1);
+                Add(typeof(GraveDust), 1);
+                Add(typeof(DaemonBlood), 3);
+                Add(typeof(PigIron), 2);
+
+                Add(typeof(AnimateDeadScroll), 26);
+                Add(typeof(BloodOathScroll), 26);
+                Add(typeof(CorpseSkinScroll), 26);
+                Add(typeof(CurseWeaponScroll), 26);
+                Add(typeof(EvilOmenScroll), 26);
+                Add(typeof(HorrificBeastScroll), 27);
+                Add(typeof(LichFormScroll), 64);
+                Add(typeof(MindRotScroll), 39);
+                Add(typeof(PainSpikeScroll), 26);
+                Add(typeof(PoisonStrikeScroll), 39);
+                Add(typeof(StrangleScroll), 64);
+                Add(typeof(SummonFamiliarScroll), 26);
+                Add(typeof(VampiricEmbraceScroll), 101);
+                Add(typeof(VengefulSpiritScroll), 114);
+                Add(typeof(WitherScroll), 64);
+                Add(typeof(WraithFormScroll), 51);
+                Add(typeof(ExorcismScroll), 114);
+            }
+
+            var types = Loot.RegularScrollTypes;
+
+            for (var i = 0; i < types.Length; ++i)
+            {
+                Add(types[i], 6 + i / 8 * 5);
+            }
+        }
+    }
+}
+
+// Haven's town crier: when a player comes near, it walks them through the young player region, a line every
+// ten seconds.
+[SerializationGenerator(0)]
+public partial class HavenCrier : BaseCreature
+{
+    private static readonly string[] _messages =
+    [
+        "Greetings young traveler, and welcome to the AOS shard of Defiance.",
+        "You are currently resisiding in the young player region, in this region you cannot harm players nor can they harm you.",
+        "The region around this city is inhabited by armed and dangerous creatures. The further you go the more dangerous the creatures will be.",
+        "Behind the blacksmith you will find some training dummies and a range to train your fighting skills up to 50 points.",
+        "If you want to go to Felucca, where most players are, follow the road south-east, until you see a sign pointing the Moongate.",
+        "Once you leave this region, you will NOT be able to return.",
+        "We hope you will have a pleasant stay, and good luck."
+    ];
+
+    private Timer _timer;
+
+    [Constructible]
+    public HavenCrier() : base(AIType.AI_Vendor, FightMode.None, 2, 1)
+    {
+        InitStats(100, 100, 25);
+        Title = "the town crier";
+        Hue = Race.Human.RandomSkinHue();
+        Female = Utility.RandomBool();
+        Body = Female ? 0x191 : 0x190;
+        Name = NameList.RandomName(Female ? "female" : "male");
+        HairItemID = Race.Human.RandomHair(Female);
+        HairHue = Race.Human.RandomHairHue();
+        Blessed = true;
+
+        AddItem(new FancyShirt(Utility.RandomBlueHue()));
+        AddItem(new Kilt(Utility.RandomGreenHue()));
+        AddItem(new FeatheredHat(Utility.RandomGreenHue()));
+        AddItem(new ThighBoots());
+    }
+
+    public override bool CanBeDamaged() => false;
+
+    public override void OnMovement(Mobile m, Point3D oldLocation)
+    {
+        base.OnMovement(m, oldLocation);
+
+        if (_timer?.Running != true && m.Player && m.AccessLevel == AccessLevel.Player && m.InRange(this, 12))
+        {
+            var line = 0;
+            _timer = Timer.DelayCall(TimeSpan.Zero, TimeSpan.FromSeconds(10.0), _messages.Length, () =>
+                PublicOverheadMessage(MessageType.Regular, 0x3B2, false, _messages[line++])
+            );
+        }
+    }
+
+    public override void OnDelete()
+    {
+        _timer?.Stop();
+        _timer = null;
+        base.OnDelete();
+    }
+}
