+[SerializationGenerator(0)]
+public partial class ExchangeNPC : BaseCreature
+{
+    private static readonly int[] _hues =
+    [
+        0x483, 0x48C, 0x488, 0x48A, 0x495, 0x48B, 0x486, 0x485, 0x48D, 0x490, 0x48E, 0x491, 0x48F, 0x494, 0x484, 0x497,
+        0x489, 0x47F, 0x482, 0x47E
+    ];
+
+    [SerializableField(0)]
+    [SerializedCommandProperty(AccessLevel.GameMaster)]
+    private ExchangeNpcCategory _category;
+
+    [Constructible(AccessLevel.GameMaster)]
+    public ExchangeNPC() : base(AIType.AI_Vendor, FightMode.None, 2, 1)
+    {
+        InitStats(100, 100, 25);
+        Title = "the trader";
+        Body = 0x190;
+        Hue = 33770;
+        Name = NameList.RandomName("male");
+        HairItemID = 8252;
+        HairHue = 2125;
+        FacialHairItemID = 8267;
+        FacialHairHue = 2125;
+        Blessed = true;
+        CantWalk = true;
+        Direction = Direction.South;
+
+        AddItem(new BodySash(1195) { Name = "I can make thee rich!", Layer = Layer.Talisman, Movable = false });
+        Wear(new Tunic());
+        Wear(new FurBoots());
+        Wear(new FurCape());
+        Wear(new Kilt());
+        Wear(new LongPants());
+        Wear(new Necklace());
+        Wear(new GoldRing());
+        Wear(new SilverBracelet());
