+    protected ExchangeCommodity Commodity { get; }
+
+    protected void AddBook(ref DynamicGumpBuilder builder, string subtitle)
+    {
+        AddFrame(ref builder, 620, 400, subtitle);
+
+        builder.AddLabel(40, 75, 0x34, "Bids");
+        builder.AddLabel(40, 95, 0x3B2, "Price");
+        builder.AddLabel(120, 95, 0x3B2, "Quantity");
+
+        for (var i = 0; i < 5 && i < Commodity.Bids.Count; i++)
+        {
+            builder.AddLabel(40, 115 + 18 * i, 0x481, Price(Commodity.Bids[i].Price));
+            builder.AddLabel(120, 115 + 18 * i, 0x481, $"{Commodity.Bids[i].Quantity}");
+        }
+
+        builder.AddLabel(230, 75, 0x34, "Offers");
+        builder.AddLabel(230, 95, 0x3B2, "Price");
+        builder.AddLabel(310, 95, 0x3B2, "Quantity");
+
+        for (var i = 0; i < 5 && i < Commodity.Offers.Count; i++)
+        {
+            builder.AddLabel(230, 115 + 18 * i, 0x481, Price(Commodity.Offers[i].Price));
+            builder.AddLabel(310, 115 + 18 * i, 0x481, $"{Commodity.Offers[i].Quantity}");
+        }
+
+        var c = Commodity;
+        var last = c.LastExchangeTime == DateTime.MinValue
+            ? "N/A"
+            : $"{(int)Math.Ceiling((Core.Now - c.LastExchangeTime).TotalHours)} h ago";
+
+        builder.AddLabel(430, 75, 0x34, "Market");
+        builder.AddLabel(430, 95, 0x3B2, "Last:");
+        builder.AddLabel(510, 95, 0x481, last);
+        builder.AddLabel(430, 113, 0x3B2, "Last-P:");
+        builder.AddLabel(510, 113, 0x481, Price(c.LastPrice));
+        builder.AddLabel(430, 131, 0x3B2, "Last-Q:");
+        builder.AddLabel(510, 131, 0x481, c.LastQuantity == 0 ? "N/A" : $"{c.LastQuantity}");
+        builder.AddLabel(430, 149, 0x3B2, "Highest-P:");
+        builder.AddLabel(510, 149, 0x481, Price(c.HighestPrice));
+        builder.AddLabel(430, 167, 0x3B2, "Lowest-P:");
+        builder.AddLabel(510, 167, 0x481, Price(c.LowestPrice));
+        builder.AddLabel(430, 185, 0x3B2, "Average-P:");
+        builder.AddLabel(510, 185, 0x481, Price(c.AveragePrice));
+        builder.AddLabel(430, 203, 0x3B2, "Total-Q:");
+        builder.AddLabel(510, 203, 0x481, $"{c.TotalQuantity}");
+        builder.AddLabel(430, 221, 0x3B2, "Total-R:");
+        builder.AddLabel(510, 221, 0x481, $"{c.TotalRevenue}");
+    }
+
+    protected static double ReadPrice(in RelayInfo info, double current) =>
+        double.TryParse(info.GetTextEntry(1)?.Trim(), out var price) ? Math.Round(price, 2) : current;
+}
+
+public class ExchangeBidGump : ExchangeOrderGump
+{
+    private readonly double _price;
+    private readonly int _quantity;
+
+    public ExchangeBidGump(ExchangeCommodity commodity, double price, int quantity) : base(commodity)
+    {
+        _price = price;
+        _quantity = quantity;
+    }
+
+    public override bool Singleton => true;
+
+    protected override void BuildLayout(ref DynamicGumpBuilder builder)
+    {
+        AddBook(ref builder, $"Buying {Commodity.Name}");
+
+        builder.AddLabel(40, 260, 0x481, "Commodity:");
+        builder.AddLabel(130, 260, 0x481, Commodity.Name);
+        builder.AddLabel(40, 285, 0x481, "Price:");
+        builder.AddImageTiled(130, 285, 120, 20, 0xBBC);
+        builder.AddTextEntry(132, 285, 116, 20, 0, 1, $"{_price:0.##}");
+        builder.AddButton(260, 285, 4029, 4030, UpdatePrice);
+        builder.AddLabel(40, 310, 0x481, "Quantity:");
+        builder.AddImageTiled(130, 310, 120, 20, 0xBBC);
+        builder.AddTextEntry(132, 310, 116, 20, 0, 2, $"{_quantity}");
+        builder.AddButton(260, 310, 4029, 4030, UpdateQuantity);
+        builder.AddLabel(320, 285, 0x481, $"Immediate acquisitions: {Commodity.ImmediateBuy(_price, _quantity)}");
+        builder.AddLabel(320, 310, 0x481, $"Cost: {(long)(_price * _quantity) + ExchangeConfig.BuyCosts} gp from the bank");
+
+        builder.AddButton(40, 350, 4011, 4012, Commit);
+        builder.AddLabel(75, 350, 0x481, "Commit");
+        builder.AddButton(180, 350, 4020, 4021, 0);
+        builder.AddLabel(215, 350, 0x481, "Cancel");
+    }
+
+    public override void OnResponse(NetState sender, in RelayInfo info)
+    {
+        var m = sender.Mobile;
+        var price = ReadPrice(info, _price);
+        var quantity = int.TryParse(info.GetTextEntry(2)?.Trim(), out var q) ? q : _quantity;
+
+        switch (info.ButtonID)
+        {
+            case UpdatePrice or UpdateQuantity:
+                {
+                    m.SendGump(new ExchangeBidGump(Commodity, price, quantity), true);
+                    break;
+                }
+            case Commit:
+                {
+                    if (ExchangeSystem.PlaceBid(m, Commodity, price, quantity) is { } error)
+                    {
+                        m.SendMessage(error);
+                        m.SendGump(new ExchangeBidGump(Commodity, price, quantity), true);
+                    }
+
+                    break;
+                }
+            default:
+                {
+                    m.SendMessage("Your bid has not been added to the exchange board.");
+                    m.SendGump(new ExchangeEntryGump(Commodity.Category), true);
+                    break;
+                }
+        }
+    }
+}
