+public class ExchangeCancelGump : ExchangeGump
+{
+    private readonly ExchangeCategory _category;
+    private readonly ExchangeOrder _order;
+
+    public ExchangeCancelGump(ExchangeCategory category, ExchangeOrder order)
+    {
+        _category = category;
+        _order = order;
+    }
+
+    public override bool Singleton => true;
+
+    protected override void BuildLayout(ref DynamicGumpBuilder builder)
+    {
+        AddFrame(ref builder, 500, 260, _order is ExchangeBid ? "Buying" : "Selling");
+
+        var warning = _order is ExchangeOffer offer
+            ? $"Warning!<br>Canceling this offer will result in the removal of {offer.Seizure} units of your goods."
+            : "Warning!<br>Canceling this bid will remove it from the exchange board, the incurred costs will not be returned";
+
+        builder.AddHtml(60, 90, 380, 90, warning, "#FFFFFF");
+        builder.AddButton(80, 200, 247, 248, 1);
+        builder.AddLabel(80, 180, 0x481, "Remove it");
+        builder.AddButton(340, 200, 241, 242, 0);
+    }
+
+    public override void OnResponse(NetState sender, in RelayInfo info)
+    {
+        var m = sender.Mobile;
+
+        if (info.ButtonID == 1 && _order.Mobile == m)
+        {
+            ExchangeSystem.Cancel(_order);
+            m.SendMessage("Your order has been removed from the exchange board; what it held went to your bank.");
+        }
+
+        m.SendGump(new ExchangeEntryGump(_category), true);
+    }
+}
+
+public class ExchangeHistoryGump : ExchangeGump
+{
+    private readonly List<ExchangeTransaction> _list;
+
+    public ExchangeHistoryGump(List<ExchangeTransaction> list) => _list = list;
+
+    public override bool Singleton => true;
+
+    protected override void BuildLayout(ref DynamicGumpBuilder builder)
+    {
+        var shown = Math.Min(_list.Count, 20);
+        var height = 160 + 20 * shown;
+        AddFrame(ref builder, 520, height, "Transaction History");
+
+        string[] heads = ["Commodity", "Action", "Price", "Quantity", "Revenue"];
+        int[] xs = [40, 170, 250, 330, 410];
+
+        for (var i = 0; i < heads.Length; i++)
+        {
+            builder.AddLabel(xs[i], 72, 0x34, heads[i]);
+        }
+
+        for (var i = 0; i < shown; i++)
+        {
+            var t = _list[_list.Count - shown + i];
+            var y = 95 + 20 * i;
+            builder.AddLabel(xs[0], y, 0x481, t.Name);
+            builder.AddLabel(xs[1], y, 0x481, t.Bought ? "Bought" : "Sold");
+            builder.AddLabel(xs[2], y, 0x481, Price(t.Price));
+            builder.AddLabel(xs[3], y, 0x481, $"{t.Quantity}");
+            builder.AddLabel(xs[4], y, 0x481, $"{(long)(t.Price * t.Quantity)}");
+        }
+
+        builder.AddLabel(40, height - 45, 0x3B2, "Goods and gold from trades are in your bank. OK clears this list.");
+        builder.AddButton(420, height - 45, 247, 248, 1);
+    }
+
+    public override void OnResponse(NetState sender, in RelayInfo info)
+    {
+        if (info.ButtonID == 1)
+        {
+            ExchangeSystem.History.Remove(sender.Mobile);
+        }
+    }
+}
+
+public class ExchangeInfoGump : ExchangeGump
+{
+    public override bool Singleton => true;
+
+    protected override void BuildLayout(ref DynamicGumpBuilder builder)
+    {
+        AddFrame(ref builder, 500, 520, "Information");
+
+        builder.AddHtml(
+            40, 80, 420, 380,
+            "Welcome to the West Britain Commodities Exchange!<br><br>We trade just about every commodity.<br>If you own a commodity you have to fill it into a commodity deed and than contact the designated trader that is able to exchange your goods. If you want to buy a commodity you can just fill out a bid at a trader. All bids and sale-entries are removed after a period of 5 days. All downpayment will be returned and goods will be returned minus the non-sale expenses as explained below.<br><br>Costs inclined:<br>As a bidder you have to pay 150 gp per bid, so in small bids this is a lot of money on  large bid it isn't much.<br>Sellers don't have to pay anything in the first place but if the goods havn't been sold within 5 days 2.5% will be held back to pay for the expenses.<br><br>What you buy, and the gold for what you sell, is put in your bank.<br><br>We hope you will enjoy our services!",
+            "#FFFFFF", background: false, scrollbar: true
+        );
+        builder.AddButton(210, 475, 247, 248, 0);
+    }
+}
MUO_EOF_0
