diff --git a/Projects/UOContent.Tests/Tests/Custom/DfiGamesTests.cs b/Projects/UOContent.Tests/Tests/Custom/DfiGamesTests.cs
new file mode 100644
index 000000000..fca4fbfea
--- /dev/null
+++ b/Projects/UOContent.Tests/Tests/Custom/DfiGamesTests.cs
@@ -0,0 +1,212 @@
+using System;
+using System.Collections.Generic;
+using Server;
+using Server.Custom.Dfi.Lottery;
+using Server.Custom.Dfi.Poker;
+using Server.Items;
+using Server.Misc;
+using Server.Mobiles;
+using Xunit;
+
+namespace UOContent.Tests.Custom;
+
+[Collection("Sequential UOContent Tests")]
+public class DfiGamesTests : IDisposable
+{
+    private readonly List<IEntity> _created = new();
+
+    public DfiGamesTests()
+    {
+        if (NameList.GetNameList("male") == null)
+        {
+            NameList.Configure();
+        }
+    }
+
+    public void Dispose()
+    {
+        foreach (var e in _created)
+        {
+            e?.Delete();
+        }
+
+        _created.Clear();
+        LotterySystem.Register.Clear();
+    }
+
+    private T Track<T>(T e) where T : IEntity
+    {
+        _created.Add(e);
+        return e;
+    }
+
+    private PlayerMobile Player(int bank = 0)
+    {
+        var m = Track(new PlayerMobile());
+        m.Player = true;
+        m.Body = 0x190;
+        m.AddItem(new Backpack());
+        m.AddItem(new BankBox(m));
+        m.MoveToWorld(new Point3D(1434, 1690, 0), Map.Felucca);
+
+        if (bank > 0)
+        {
+            m.BankBox.DropItem(new BankCheck(bank));
+        }
+
+        return m;
+    }
+
+    // Cards: suit * 13 + value - 1, suits hearts 0, diamonds 1, spades 2, clubs 3.
+    private static int C(int value, int suit) => suit * 13 + value - 1;
+
+    public static TheoryData<int[], PokerHand> Hands => new()
+    {
+        { [C(10, 0), C(11, 0), C(12, 0), C(13, 0), C(1, 0)], PokerHand.RoyalFlush },
+        { [C(5, 2), C(6, 2), C(7, 2), C(8, 2), C(9, 2)], PokerHand.StraightFlush },
+        { [C(7, 0), C(7, 1), C(7, 2), C(7, 3), C(2, 0)], PokerHand.FourOfAKind },
+        { [C(3, 0), C(3, 1), C(3, 2), C(9, 3), C(9, 0)], PokerHand.FullHouse },
+        { [C(2, 1), C(5, 1), C(9, 1), C(11, 1), C(13, 1)], PokerHand.Flush },
+        { [C(1, 0), C(2, 1), C(3, 2), C(4, 3), C(5, 0)], PokerHand.Straight },
+        { [C(10, 0), C(11, 1), C(12, 2), C(13, 3), C(1, 0)], PokerHand.Straight },
+        { [C(8, 0), C(8, 1), C(8, 2), C(2, 3), C(5, 0)], PokerHand.ThreeOfAKind },
+        { [C(8, 0), C(8, 1), C(4, 2), C(4, 3), C(5, 0)], PokerHand.TwoPairs },
+        { [C(8, 0), C(8, 1), C(4, 2), C(11, 3), C(5, 0)], PokerHand.Pair },
+        { [C(2, 0), C(4, 1), C(6, 2), C(9, 3), C(11, 0)], PokerHand.None }
+    };
+
+    [Theory]
+    [MemberData(nameof(Hands))]
+    public void Poker_RanksEveryHand(int[] hand, PokerHand expected)
+    {
+        Assert.Equal(expected, PokerCards.Evaluate(hand));
+    }
+
+    [Fact]
+    public void Poker_DealsFiveDifferentCardsAndDrawsOnlyWhatIsNotHeld()
+    {
+        var machine = Track(new PokerMachineLow());
+        var session = new PokerSession(machine);
+
+        session.Deal();
+        Assert.Equal(5, new HashSet<int>(session.Hand).Count);
+
+        session.Held[0] = session.Held[2] = true;
+        var kept = (session.Hand[0], session.Hand[2]);
+        session.Draw();
+
+        Assert.Equal(kept, (session.Hand[0], session.Hand[2]));
+    }
+
+    [Fact]
+    public void Poker_PaysByTheBetAndRoyalFlushTakesAThird()
+    {
+        var player = Player();
+        var machine = Track(new PokerMachineMedium());
+        machine.GoldInMachine = 90000;
+        var session = new PokerSession(machine) { Bet = 300 };
+
+        Assert.Equal(80 * 3, session.Winning(PokerHand.Pair));
+        Assert.Equal(30000, session.Winning(PokerHand.RoyalFlush));
+
+        session.Hand[0] = C(8, 0);
+        session.Hand[1] = C(8, 1);
+        session.Hand[2] = C(4, 2);
+        session.Hand[3] = C(11, 3);
+        session.Hand[4] = C(5, 0);
+        machine.Settle(player, session);
+
+        Assert.Equal(240, Banker.GetBalance(player));
+        Assert.Equal(90000 - 240, machine.GoldInMachine);
+    }
+
+    [Fact]
+    public void Poker_BetsCycleAndChargeTheBackpack()
+    {
+        var player = Player();
+        var machine = Track(new PokerMachineHigh());
+        var session = new PokerSession(machine);
+        var before = machine.GoldInMachine;
+
+        Assert.Equal(1000, session.Bet);
+        for (var i = 0; i < 5; i++)
+        {
+            session.NextBet();
+        }
+
+        Assert.Equal(1000, session.Bet);
+
+        Assert.False(machine.Charge(player, 1000, false));
+        player.Backpack.DropItem(new Gold(1500));
+        Assert.True(machine.Charge(player, 1000, false));
+        Assert.Equal(500, player.Backpack.GetAmount(typeof(Gold)));
+        Assert.Equal(before + 1000, machine.GoldInMachine);
+    }
+
+    [Fact]
+    public void Lottery_BuyingTakesTicketsFromTheBankAndClearingRefunds()
+    {
+        var player = Player(1000);
+        var entry = LotterySystem.GetEntry(player);
+        entry.Tickets.Add([1, 2, 3, 4]);
+        entry.Tickets.Add([5, 6, 7, 8]);
+
+        Assert.Null(LotterySystem.Buy(player));
+        Assert.True(entry.Bought);
+        Assert.Equal(1000 - 2 * LotterySystem.TicketPrice, Banker.GetBalance(player));
+
+        LotterySystem.Clear(player);
+        Assert.False(entry.Bought);
+        Assert.Empty(entry.Tickets);
+        Assert.Equal(1000, Banker.GetBalance(player));
+    }
+
+    [Fact]
+    public void Lottery_DrawingPaysByCorrectNumbersAndSplitsTheJackpot()
+    {
+        LotterySystem.UpdateJackpot();
+        var jackpot = LotterySystem.Jackpot;
+
+        var a = Player(10_000);
+        var b = Player(10_000);
+        var c = Player(10_000);
+        LotterySystem.GetEntry(a).Tickets.Add([1, 2, 3, 4]);
+        LotterySystem.GetEntry(b).Tickets.Add([1, 2, 3, 4]);
+        LotterySystem.GetEntry(c).Tickets.Add([1, 2, 30, 40]);
+        LotterySystem.GetEntry(c).Tickets.Add([1, 2, 3, 40]);
+
+        foreach (var m in (Mobile[])[a, b, c])
+        {
+            LotterySystem.Buy(m);
+        }
+
+        var balanceA = Banker.GetBalance(a);
+        var balanceC = Banker.GetBalance(c);
+
+        LotterySystem.Draw([1, 2, 3, 4]);
+
+        Assert.Equal(balanceA + jackpot / 2, Banker.GetBalance(a));
+        Assert.Equal(balanceC + LotterySystem.Prize2 + LotterySystem.Prize3, Banker.GetBalance(c));
+        Assert.False(LotterySystem.GetEntry(a).Bought);
+        Assert.True(LotterySystem.GetEntry(c).ShowWinnings);
+        Assert.Equal(2, LotterySystem.GetEntry(c).TotalCorrectNumbers[4]);
+    }
+
+    [Fact]
+    public void Lottery_UnboughtTicketsWinNothing()
+    {
+        var player = Player();
+        LotterySystem.GetEntry(player).Tickets.Add([1, 2, 3, 4]);
+
+        LotterySystem.Draw([1, 2, 3, 4]);
+
+        Assert.Equal(0, Banker.GetBalance(player));
+    }
+
+    [Fact]
+    public void Lottery_NpcAndMachinesConstruct()
+    {
+        Assert.False(Track(new LotteryNpc()).Deleted);
+        Assert.Contains(Track(new LotteryNpc()), LotterySystem.Npcs);
+    }
+}
diff --git a/Projects/UOContent/Custom/DFI/Games/DfiGamesGen.cs b/Projects/UOContent/Custom/DFI/Games/DfiGamesGen.cs
new file mode 100644
index 000000000..ad2a5b3f6
--- /dev/null
+++ b/Projects/UOContent/Custom/DFI/Games/DfiGamesGen.cs
@@ -0,0 +1,73 @@
+// Places DFI's town games: a lottery master and the three poker machines on Britain's main street, by the Lost
+// Lands gate. DFI's saves kept none of their spots.
+
+using System.Collections.Generic;
+using Server.Commands;
+using Server.Custom.Dfi.Lottery;
+using Server.Items;
+using Server.Logging;
+
+namespace Server.Custom.Dfi;
+
+public static class DfiGamesGen
+{
+    private static readonly ILogger logger = LogFactory.GetLogger(typeof(DfiGamesGen));
+
+    public static readonly Point3D LotterySpot = new(1442, 1700, 0);
+    public static readonly Point3D[] PokerSpots = [new(1439, 1698, 0), new(1440, 1697, 0), new(1441, 1698, 0)];
+
+    public static void Configure()
+    {
+        CommandSystem.Register("DfiGames", AccessLevel.Administrator, OnCommand);
+    }
+
+    [Usage("DfiGames")]
+    [Description("Places DFI's lottery master and poker machines in Britain, replacing any placed before.")]
+    private static void OnCommand(CommandEventArgs e)
+    {
+        var removed = Remove();
+        var placed = Place();
+        e.Mobile.SendMessage($"DfiGames: removed {removed}, placed {placed}.");
+        logger.Information("{User} placed {Placed} DFI game fixtures ({Removed} removed)", e.Mobile, placed, removed);
+    }
+
+    public static int Remove()
+    {
+        var doomed = new List<IEntity>();
+
+        foreach (var m in World.Mobiles.Values)
+        {
+            if (m is LotteryNpc && m.Map == Map.Felucca && m.Location == LotterySpot)
+            {
+                doomed.Add(m);
+            }
+        }
+
+        foreach (var item in World.Items.Values)
+        {
+            if (item is PokerMachine && item.Map == Map.Felucca && System.Array.IndexOf(PokerSpots, item.Location) >= 0)
+            {
+                doomed.Add(item);
+            }
+        }
+
+        foreach (var entity in doomed)
+        {
+            entity.Delete();
+        }
+
+        return doomed.Count;
+    }
+
+    public static int Place()
+    {
+        var npc = new LotteryNpc { Home = LotterySpot, RangeHome = 0, CantWalk = true, Direction = Direction.South };
+        npc.MoveToWorld(LotterySpot, Map.Felucca);
+
+        new PokerMachineLow().MoveToWorld(PokerSpots[0], Map.Felucca);
+        new PokerMachineMedium().MoveToWorld(PokerSpots[1], Map.Felucca);
+        new PokerMachineHigh().MoveToWorld(PokerSpots[2], Map.Felucca);
+
+        return 1 + PokerSpots.Length;
+    }
+}
diff --git a/Projects/UOContent/Custom/DFI/Games/Lottery.cs b/Projects/UOContent/Custom/DFI/Games/Lottery.cs
new file mode 100644
index 000000000..35b1fe4c3
--- /dev/null
+++ b/Projects/UOContent/Custom/DFI/Games/Lottery.cs
@@ -0,0 +1,720 @@
+// DFI Network's lottery, ported from DFI RUNUO Scripts/Custom/Engines/LotterySystem. Players pick four numbers
+// from 1 to 49 per ticket, up to five tickets at 100 gp each paid from the bank, at a lottery master. A drawing
+// every day at 17:00 (UTC here) pays 5,000 gp for two correct numbers, 30,000 for three and the jackpot, 80% of
+// the money in the system (never under a million), split between all four-number tickets. Results wait at the
+// lottery master; lottery masters cry the drawing out every minute.
+
+using System;
+using System.Collections.Generic;
+using ModernUO.Serialization;
+using Server.Collections;
+using Server.Commands;
+using Server.ContextMenus;
+using Server.Gumps;
+using Server.Items;
+using Server.Mobiles;
+using Server.Network;
+
+namespace Server.Custom.Dfi.Lottery;
+
+public class LotteryEntry
+{
+    public LotteryEntry(Mobile player) => Player = player;
+
+    public Mobile Player { get; }
+    public List<int[]> Tickets { get; } = [];
+    public bool Bought { get; set; }
+    public bool ShowWinnings { get; set; }
+    public DateTime TicketBought { get; set; }
+    public DateTime LastAccess { get; set; }
+    public int WinMoney { get; set; }
+    public int[] WinningNumbers { get; set; } = new int[LotterySystem.NumbersPerTicket];
+    public int[] CorrectNumbers { get; set; } = [];
+    public int[] TotalCorrectNumbers { get; set; } = new int[LotterySystem.NumbersPerTicket + 1];
+}
+
+public class LotterySystem : GenericPersistence
+{
+    public const int MaxNumbers = 49;
+    public const int NumbersPerTicket = 4;
+    public const int MaxTicketsPerPlayer = 5;
+    public const int SystemHue = 0x38A;
+    public const int MinimumSystemGold = 1_000_000;
+    public const int TicketPrice = 100;
+    public const double JackpotPercent = 0.8;
+    public const int Prize1 = 0;
+    public const int Prize2 = 5000;
+    public const int Prize3 = 30000;
+
+    public static readonly TimeSpan DrawTime = TimeSpan.FromHours(17.0);
+    public static readonly TimeSpan DecayTime = TimeSpan.FromDays(30.0);
+
+    public static int Jackpot { get; private set; }
+    public static long TotalLotteryMoney { get; private set; } = MinimumSystemGold;
+    public static DateTime NextDrawing { get; private set; }
+    public static List<LotteryEntry> Register { get; } = [];
+    public static List<LotteryNpc> Npcs { get; } = [];
+
+    private static Timer _timer;
+
+    public LotterySystem() : base("DfiLottery", 10)
+    {
+    }
+
+    public static void Configure()
+    {
+        _ = new LotterySystem();
+    }
+
+    public static void Initialize()
+    {
+        UpdateTime();
+
+        if (Jackpot == 0)
+        {
+            UpdateJackpot();
+        }
+
+        Register.RemoveAll(e => e.LastAccess + DecayTime < Core.Now || e.Player?.Deleted != false);
+        _timer = Timer.DelayCall(TimeSpan.FromMinutes(1.0), TimeSpan.FromMinutes(1.0), OnTick);
+    }
+
+    private static void OnTick()
+    {
+        foreach (var npc in Npcs)
+        {
+            if (!npc.Deleted)
+            {
+                npc.Advertise();
+            }
+        }
+
+        if (NextDrawing < Core.Now)
+        {
+            UpdateTime();
+            Draw();
+        }
+    }
+
+    public static void UpdateTime()
+    {
+        NextDrawing = Core.Now.Date + DrawTime;
+
+        if (NextDrawing < Core.Now)
+        {
+            NextDrawing += TimeSpan.FromDays(1.0);
+        }
+    }
+
+    public static void UpdateJackpot()
+    {
+        TotalLotteryMoney = Math.Max(TotalLotteryMoney, MinimumSystemGold);
+        Jackpot = (int)Math.Min(int.MaxValue, TotalLotteryMoney * JackpotPercent);
+    }
+
+    public static bool TakeGold(Mobile from, int amount)
+    {
+        if (!Banker.Withdraw(from, amount))
+        {
+            return false;
+        }
+
+        TotalLotteryMoney += amount;
+        return true;
+    }
+
+    public static void GiveGold(Mobile to, int amount)
+    {
+        if (to?.Deleted == false && amount > 0)
+        {
+            Banker.Deposit(to, amount);
+            TotalLotteryMoney -= amount;
+        }
+    }
+
+    public static LotteryEntry GetEntry(Mobile from)
+    {
+        var entry = Register.Find(e => e.Player == from);
+
+        if (entry == null)
+        {
+            entry = new LotteryEntry(from);
+            Register.Add(entry);
+        }
+
+        entry.LastAccess = Core.Now;
+        return entry;
+    }
+
+    // Returns null when bought, or why not.
+    public static string Buy(Mobile from)
+    {
+        var entry = GetEntry(from);
+
+        if (entry.Tickets.Count == 0)
+        {
+            return "No tickets have been added to the list!";
+        }
+
+        var cost = TicketPrice * entry.Tickets.Count;
+
+        if (!TakeGold(from, cost))
+        {
+            return "Not enough gold in your bankbox.";
+        }
+
+        entry.Bought = true;
+        entry.TicketBought = Core.Now;
+        return null;
+    }
+
+    public static string Clear(Mobile from)
+    {
+        var entry = GetEntry(from);
+        var refund = "";
+
+        if (entry.Bought)
+        {
+            var gold = TicketPrice * entry.Tickets.Count;
+            GiveGold(from, gold);
+            refund = $" {gold}gp added to your bankbox.";
+            entry.Bought = false;
+        }
+
+        entry.Tickets.Clear();
+        return $"Number list cleared.{refund}";
+    }
+
+    // Draws four numbers (or uses the ones given), pays out and returns them.
+    public static int[] Draw(int[] winning = null)
+    {
+        if (winning == null)
+        {
+            var drawn = new HashSet<int>();
+
+            while (drawn.Count < NumbersPerTicket)
+            {
+                drawn.Add(Utility.Random(MaxNumbers) + 1);
+            }
+
+            winning = [..drawn];
+        }
+
+        var winSet = new HashSet<int>(winning);
+        var totals = new int[NumbersPerTicket + 1];
+
+        foreach (var entry in Register)
+        {
+            if (!entry.Bought)
+            {
+                continue;
+            }
+
+            entry.CorrectNumbers = new int[entry.Tickets.Count];
+
+            for (var i = 0; i < entry.Tickets.Count; i++)
+            {
+                var correct = 0;
+
+                foreach (var n in entry.Tickets[i])
+                {
+                    if (winSet.Contains(n))
+                    {
+                        correct++;
+                    }
+                }
+
+                entry.CorrectNumbers[i] = correct;
+                totals[correct]++;
+            }
+
+            entry.TotalCorrectNumbers = totals;
+            entry.WinningNumbers = (int[])winning.Clone();
+            entry.ShowWinnings = true;
+        }
+
+        int[] prizes = [0, Prize1, Prize2, Prize3, totals[NumbersPerTicket] == 0 ? Jackpot : Jackpot / totals[NumbersPerTicket]];
+
+        foreach (var entry in Register)
+        {
+            if (!entry.Bought)
+            {
+                continue;
+            }
+
+            entry.WinMoney = 0;
+
+            foreach (var correct in entry.CorrectNumbers)
+            {
+                if (prizes[correct] > 0 && entry.Player?.Deleted == false)
+                {
+                    entry.WinMoney += prizes[correct];
+                    GiveGold(entry.Player, prizes[correct]);
+                }
+            }
+
+            entry.Bought = false;
+        }
+
+        UpdateJackpot();
+        CommandHandlers.BroadcastMessage(AccessLevel.Player, SystemHue, $"Lottery drawing... {string.Join(" ", winning)}");
+        return winning;
+    }
+
+    public static string FormatTickets(LotteryEntry entry, bool showCorrect)
+    {
+        var text = "";
+
+        for (var i = 0; i < entry.Tickets.Count; i++)
+        {
+            text += $"#{i + 1} Numbers: {string.Join(" ", entry.Tickets[i])}";
+            text += showCorrect && i < entry.CorrectNumbers.Length ? $"  Correct Numbers: {entry.CorrectNumbers[i]}<br>" : "<br>";
+        }
+
+        return text;
+    }
+
+    public override void Serialize(IGenericWriter writer)
+    {
+        writer.WriteEncodedInt(0); // version
+        writer.Write(NextDrawing);
+        writer.Write(Jackpot);
+        writer.Write(TotalLotteryMoney);
+
+        writer.WriteEncodedInt(Register.Count);
+
+        foreach (var e in Register)
+        {
+            writer.Write(e.Player);
+            writer.Write(e.Bought);
+            writer.Write(e.ShowWinnings);
+            writer.Write(e.WinMoney);
+            writer.Write(e.LastAccess);
+            writer.Write(e.TicketBought);
+            writer.WriteEncodedInt(e.Tickets.Count);
+
+            foreach (var t in e.Tickets)
+            {
+                WriteInts(writer, t);
+            }
+
+            WriteInts(writer, e.CorrectNumbers);
+            WriteInts(writer, e.TotalCorrectNumbers);
+            WriteInts(writer, e.WinningNumbers);
+        }
+    }
+
+    private static void WriteInts(IGenericWriter writer, int[] values)
+    {
+        writer.WriteEncodedInt(values.Length);
+
+        foreach (var v in values)
+        {
+            writer.WriteEncodedInt(v);
+        }
+    }
+
+    private static int[] ReadInts(IGenericReader reader)
+    {
+        var values = new int[reader.ReadEncodedInt()];
+
+        for (var i = 0; i < values.Length; i++)
+        {
+            values[i] = reader.ReadEncodedInt();
+        }
+
+        return values;
+    }
+
+    public override void Deserialize(IGenericReader reader)
+    {
+        reader.ReadEncodedInt(); // version
+        NextDrawing = reader.ReadDateTime();
+        Jackpot = reader.ReadInt();
+        TotalLotteryMoney = reader.ReadLong();
+
+        var count = reader.ReadEncodedInt();
+
+        for (var i = 0; i < count; i++)
+        {
+            var entry = new LotteryEntry(reader.ReadEntity<Mobile>())
+            {
+                Bought = reader.ReadBool(),
+                ShowWinnings = reader.ReadBool(),
+                WinMoney = reader.ReadInt(),
+                LastAccess = reader.ReadDateTime(),
+                TicketBought = reader.ReadDateTime()
+            };
+
+            var tickets = reader.ReadEncodedInt();
+
+            for (var t = 0; t < tickets; t++)
+            {
+                entry.Tickets.Add(ReadInts(reader));
+            }
+
+            entry.CorrectNumbers = ReadInts(reader);
+            entry.TotalCorrectNumbers = ReadInts(reader);
+            entry.WinningNumbers = ReadInts(reader);
+
+            if (entry.Player != null)
+            {
+                Register.Add(entry);
+            }
+        }
+    }
+}
