+public class LotteryGump : DynamicGump
+{
+    private const int Close = 0;
+    private const int AddTicket = 1;
+    private const int BuyTickets = 2;
+    private const int ClearTickets = 3;
+
+    private readonly LotteryEntry _entry;
+    private readonly string _status;
+
+    public LotteryGump(Mobile from, string status) : base(40, 40)
+    {
+        _entry = LotterySystem.GetEntry(from);
+        _status = status;
+    }
+
+    public override bool Singleton => true;
+
+    protected override void BuildLayout(ref DynamicGumpBuilder builder)
+    {
+        var entry = _entry;
+
+        builder.AddPage();
+        builder.AddBackground(0, 0, 500, 350, 9200);
+        builder.AddLabel(219, 20, 0, "Lottery Tickets");
+        builder.AddLabel(34, 45, 0, "Information");
+        builder.AddHtml(
+            32, 63, 178, 230,
+            $"Ticket price: {LotterySystem.TicketPrice}<br><br><I>Winning List</I><BR>1 Correct: {LotterySystem.Prize1}gp<br>2 Correct: {LotterySystem.Prize2}gp<br>3 Correct: {LotterySystem.Prize3}gp<br>4 Correct: {LotterySystem.Jackpot}gp<br><BR><I>Next Drawing</I><BR>{LotterySystem.NextDrawing:HH:mm} UTC, {LotterySystem.NextDrawing:d MMMM yyyy}",
+            background: true, scrollbar: true
+        );
+
+        builder.AddHtml(217, 63, 246, 121, LotterySystem.FormatTickets(entry, false), background: true, scrollbar: true);
+
+        if (!entry.Bought)
+        {
+            builder.AddHtml(217, 187, 246, 47, $"Total cost of tickets: {LotterySystem.TicketPrice * entry.Tickets.Count}", background: true);
+            builder.AddButton(432, 236, 4023, 4024, AddTicket);
+            builder.AddLabel(324, 236, 0, "Add a new ticket");
+            builder.AddButton(432, 281, 4023, 4024, BuyTickets);
+            builder.AddLabel(265, 281, 0, "Buy the tickets in the list");
+        }
+        else
+        {
+            builder.AddHtml(217, 187, 246, 47, "Please wait for the number drawing to see if you have won.", background: true);
+        }
+
+        builder.AddButton(432, 258, 4023, 4024, ClearTickets);
+        builder.AddLabel(324, 258, 0, "Clear ticket list");
+        builder.AddHtml(28, 308, 349, 24, _status);
+        builder.AddButton(442, 308, 4017, 4018, Close);
+        builder.AddLabel(403, 308, 0, "Close");
+    }
+
+    public override void OnResponse(NetState sender, in RelayInfo info)
+    {
+        var m = sender.Mobile;
+
+        if (m is not PlayerMobile)
+        {
+            return;
+        }
+
+        var entry = LotterySystem.GetEntry(m);
+        string status;
+
+        switch (info.ButtonID)
+        {
+            case BuyTickets when !entry.Bought:
+                {
+                    status = LotterySystem.Buy(m) ?? $"{LotterySystem.TicketPrice * entry.Tickets.Count}gp has been removed from your bankbox.";
+                    break;
+                }
+            case ClearTickets:
+                {
+                    status = LotterySystem.Clear(m);
+                    break;
+                }
+            case AddTicket when !entry.Bought:
+                {
+                    if (entry.Tickets.Count < LotterySystem.MaxTicketsPerPlayer)
+                    {
+                        m.SendGump(new LotteryNumbersGump(""), true);
+                        return;
+                    }
+
+                    status = $"You can not add more than {LotterySystem.MaxTicketsPerPlayer} tickets!";
+                    break;
+                }
+            default:
+                {
+                    return;
+                }
+        }
+
+        m.SendGump(new LotteryGump(m, status), true);
+    }
+}
+
+public class LotteryNumbersGump : DynamicGump
+{
+    private readonly string _status;
+
+    public LotteryNumbersGump(string status) : base(20, 20) => _status = status;
+
+    public override bool Singleton => true;
+
+    protected override void BuildLayout(ref DynamicGumpBuilder builder)
+    {
+        builder.AddPage();
+        builder.AddBackground(0, 0, 580, 360, 9200);
+        builder.AddLabel(242, 21, 0, "Lottery Ticket");
+        builder.AddHtml(
+            375, 57, 172, 227,
+            $"Choose {LotterySystem.NumbersPerTicket} numbers to add to the ticket.<br><br>You can buy up to {LotterySystem.MaxTicketsPerPlayer} tickets.",
+            background: true
+        );
+        builder.AddHtml(35, 326, 522, 23, _status);
+
+        for (var n = 1; n <= LotterySystem.MaxNumbers; n++)
+        {
+            var col = (n - 1) % 10 + 1;
+            var row = (n - 1) / 10;
+            builder.AddLabel(20 + col * 30, 55 + row * 50, 0, $"{n}");
+            builder.AddCheckbox(15 + col * 30, 77 + row * 50, 210, 211, false, n);
+        }
+
+        builder.AddButton(414, 297, 247, 248, 2);
+        builder.AddButton(482, 297, 241, 242, 1);
+    }
+
+    public override void OnResponse(NetState sender, in RelayInfo info)
+    {
+        var m = sender.Mobile;
+
+        if (m is not PlayerMobile || info.ButtonID == 0)
+        {
+            return;
+        }
+
+        if (info.ButtonID == 1)
+        {
+            m.SendGump(new LotteryGump(m, ""), true);
+            return;
+        }
+
+        var picked = new List<int>();
+
+        for (var n = 1; n <= LotterySystem.MaxNumbers; n++)
+        {
+            if (info.IsSwitched(n))
+            {
+                picked.Add(n);
+            }
+        }
+
+        var entry = LotterySystem.GetEntry(m);
+
+        if (picked.Count != LotterySystem.NumbersPerTicket)
+        {
+            m.SendGump(
+                new LotteryNumbersGump($"Invalid amount of numbers! Choose {LotterySystem.NumbersPerTicket} numbers and click the Okay button."),
+                true
+            );
+            return;
+        }
+
+        if (!entry.Bought && entry.Tickets.Count < LotterySystem.MaxTicketsPerPlayer)
+        {
+            entry.Tickets.Add([..picked]);
+        }
+
+        m.SendGump(new LotteryGump(m, "Ticket added to the list."), true);
+    }
+}
