+// DFI Network's video poker machines, ported from DFI RUNUO Scripts/Custom/Engines/PokerSystem. Five-card draw:
+// the bet is paid from the backpack (or the bank), five cards are dealt, the player holds any and draws once.
+// Winnings come out of the machine's gold into the bank; a royal flush wins a third of the machine. Machines
+// with under 50,000 gold are refilled every two hours. Three machines: low (10-50 gp), medium (100-500 gp) and
+// high (1,000-5,000 gp).
+
+using System;
+using System.Collections.Generic;
+using ModernUO.Serialization;
+using Server.Custom.Dfi.Poker;
+using Server.Gumps;
+using Server.Items;
+using Server.Mobiles;
+using Server.Network;
+
+namespace Server.Custom.Dfi.Poker
+{
+    public enum PokerHand
+    {
+        RoyalFlush,
+        StraightFlush,
+        FourOfAKind,
+        FullHouse,
+        Flush,
+        Straight,
+        ThreeOfAKind,
+        TwoPairs,
+        Pair,
+        None
+    }
+
+    // A card is 0-51: suit = card / 13 (hearts, diamonds, spades, clubs), value = card % 13 + 1 (1 is the ace).
+    public static class PokerCards
+    {
+        public static int Value(int card) => card % 13 + 1;
+        public static int Suit(int card) => card / 13;
+
+        public static string ValueText(int card) =>
+            Value(card) switch
+            {
+                1  => "A",
+                11 => "J",
+                12 => "Q",
+                13 => "K",
+                var v => $"{v}"
+            };
+
+        public static string SuitText(int card) => Suit(card) switch { 0 => "H", 1 => "D", 2 => "S", _ => "C" };
+
+        public static bool IsRed(int card) => Suit(card) < 2;
+
+        public static PokerHand Evaluate(IReadOnlyList<int> hand)
+        {
+            var values = new List<int>(hand.Count);
+            var flush = true;
+
+            for (var i = 0; i < hand.Count; i++)
+            {
+                values.Add(Value(hand[i]));
+                flush &= Suit(hand[i]) == Suit(hand[0]);
+            }
+
+            values.Sort();
+
+            var counts = new Dictionary<int, int>();
+
+            foreach (var v in values)
+            {
+                counts[v] = counts.GetValueOrDefault(v) + 1;
+            }
+
+            var groups = new List<int>(counts.Values);
+            groups.Sort((a, b) => b.CompareTo(a));
+
+            var distinct = counts.Count == 5;
+            var lowStraight = distinct && values[4] - values[0] == 4;
+            var broadway = distinct && values[0] == 1 && values[1] == 10; // 10 J Q K A
+            var straight = lowStraight || broadway;
+
+            return (flush, straight, broadway, groups[0], groups.Count > 1 ? groups[1] : 0) switch
+            {
+                (true, true, true, _, _)  => PokerHand.RoyalFlush,
+                (true, true, _, _, _)     => PokerHand.StraightFlush,
+                (_, _, _, 4, _)           => PokerHand.FourOfAKind,
+                (_, _, _, 3, 2)           => PokerHand.FullHouse,
+                (true, _, _, _, _)        => PokerHand.Flush,
+                (_, true, _, _, _)        => PokerHand.Straight,
+                (_, _, _, 3, _)           => PokerHand.ThreeOfAKind,
+                (_, _, _, 2, 2)           => PokerHand.TwoPairs,
+                (_, _, _, 2, _)           => PokerHand.Pair,
+                _                         => PokerHand.None
+            };
+        }
+    }
+
+    // One player's game at a machine: the deck, the hand, what is held and the bet.
+    public class PokerSession
+    {
+        private readonly List<int> _deck = [];
+
+        public PokerSession(PokerMachine machine)
+        {
+            Machine = machine;
+            Bet = machine.MinBet;
+        }
+
+        public PokerMachine Machine { get; }
+        public int Bet { get; set; }
+        public int[] Hand { get; } = [-1, -1, -1, -1, -1];
+        public bool[] Held { get; } = new bool[5];
+        public bool Drawing { get; set; }
+
+        private int NextCard()
+        {
+            if (_deck.Count == 0)
+            {
+                for (var i = 0; i < 52; i++)
+                {
+                    _deck.Add(i);
+                }
+            }
+
+            var at = Utility.Random(_deck.Count);
+            var card = _deck[at];
+            _deck.RemoveAt(at);
+            return card;
+        }
+
+        public void Deal()
+        {
+            _deck.Clear();
+            Array.Clear(Held);
+
+            for (var i = 0; i < Hand.Length; i++)
+            {
+                Hand[i] = NextCard();
+            }
+        }
+
+        public void Draw()
+        {
+            for (var i = 0; i < Hand.Length; i++)
+            {
+                if (!Held[i])
+                {
+                    Hand[i] = NextCard();
+                }
+            }
+        }
+
+        public void NextBet() => Bet = Bet >= Machine.MaxBet ? Machine.MinBet : Bet + Machine.BetChange;
+
+        public int Winning(PokerHand hand) =>
+            hand == PokerHand.RoyalFlush ? Machine.GoldInMachine / 3 : Machine.WinningsTable[(int)hand] * (Bet / Machine.BetChange);
+    }
+
+    public class PokerGump : DynamicGump
+    {
+        private const int Close = 0;
+        private const int Ok = 1;
+        private const int HoldBase = 2;
+        private const int ChangeBet = 7;
+        private const int UseBankCheck = 8;
+
+        private const int CardWidth = 50;
+        private const int CardHeight = 74;
+        private const int CardX = 25;
+        private const int CardY = 100;
+        private const int CardSpace = 70;
+
+        private readonly PokerSession _session;
+        private readonly string _status;
+        private readonly bool _useBank;
+        private readonly int _balance;
+
+        public PokerGump(Mobile from, PokerSession session, string status, bool useBank) : base(50, 35)
+        {
+            _session = session;
+            _status = status;
+            _useBank = useBank;
+            _balance = Banker.GetBalance(from);
+        }
+
+        public override bool Singleton => true;
+
+        protected override void BuildLayout(ref DynamicGumpBuilder builder)
+        {
+            builder.AddPage();
+            builder.AddBackground(0, 0, 524, 341, 2620);
+            builder.AddAlphaRegion(5, 7, 513, 326);
+
+            for (var i = 0; i < 5; i++)
+            {
+                var x = CardX + CardSpace * i;
+                var card = _session.Hand[i];
+                builder.AddImageTiled(x, CardY, CardWidth, CardHeight, 9354);
+
+                if (card < 0)
+                {
+                    builder.AddImage(x + CardWidth / 2 - 12, CardY + CardHeight / 2 - 12, 11320);
+                }
+                else
+                {
+                    var value = PokerCards.ValueText(card);
+                    builder.AddLabel(x + 4, CardY + 1, 0, value);
+                    builder.AddLabel(x + CardWidth - (8 + value.Length * 4), CardY + CardHeight - 20, 0, value);
+                    builder.AddLabel(x + CardWidth / 2 - 3, CardY + CardHeight / 2 - 10, PokerCards.IsRed(card) ? 1171 : 0, PokerCards.SuitText(card));
+                }
+
+                if (_session.Drawing)
+                {
+                    builder.AddCheckbox(x + CardWidth / 2 - 10, CardY + CardHeight + 10, 210, 211, _session.Held[i], HoldBase + i);
+                }
+            }
+
+            builder.AddButton(476, 275, 4017, 4018, Close);
+            builder.AddLabel(434, 277, 940, "Close");
+            builder.AddButton(175, 218, 4023, 4024, Ok);
+            builder.AddLabel(210, 218, 940, _session.Drawing ? "Draw" : "Deal");
+
+            if (!_session.Drawing)
+            {
+                builder.AddButton(476, 246, 4014, 4015, ChangeBet);
+                builder.AddLabel(398, 248, 940, "Change Bet");
+            }
+
+            builder.AddCheckbox(191, 271, 210, 211, _useBank, UseBankCheck);
+            builder.AddLabel(18, 272, 940, "Withdraw money from bank.");
+            builder.AddLabel(18, 252, 940, $"Bank balance: {_balance}gp.");
+
+            builder.AddBackground(366, 16, 144, 226, 3000);
+
+            for (var i = 0; i < (int)PokerHand.None; i++)
+            {
+                builder.AddLabel(370, 20 + i * 20, 0, $"{(PokerHand)i}");
+                builder.AddLabel(450, 20 + i * 20, 0, $"{_session.Winning((PokerHand)i)}gp");
+            }
+
+            builder.AddLabel(370, 200, 0, $"Current Bet: {_session.Bet}gp");
+            builder.AddHtml(13, 302, 497, 27, _status, background: true);
+        }
+
+        public override void OnResponse(NetState sender, in RelayInfo info)
+        {
+            var m = sender.Mobile;
+            var machine = _session.Machine;
+
+            if (m is not PlayerMobile || info.ButtonID == Close || machine.Deleted)
+            {
+                return;
+            }
+
+            if (!m.InRange(machine.GetWorldLocation(), 2))
+            {
+                m.SendLocalizedMessage(1060178); // You are too far away to perform that action!
+                return;
+            }
+
+            if (machine.GoldInMachine <= 0)
+            {
+                m.SendMessage("This machine is out of gold.");
+                return;
+            }
+
+            var useBank = info.IsSwitched(UseBankCheck);
+            var status = "";
+
+            for (var i = 0; i < 5; i++)
+            {
+                _session.Held[i] = info.IsSwitched(HoldBase + i);
+            }
+
+            switch (info.ButtonID)
+            {
+                case ChangeBet when !_session.Drawing:
+                    {
+                        _session.NextBet();
+                        break;
+                    }
+                case Ok when !_session.Drawing:
+                    {
+                        if (!machine.Charge(m, _session.Bet, useBank))
+                        {
+                            status = useBank ? "You do not have enough gold in your bankbox!" : "You do not have enough gold in your backpack!";
+                            break;
+                        }
+
+                        _session.Deal();
+                        _session.Drawing = true;
+                        status = "Choose the cards to hold, then draw.";
+                        break;
+                    }
+                case Ok:
+                    {
+                        _session.Draw();
+                        _session.Drawing = false;
+                        status = machine.Settle(m, _session);
+                        break;
+                    }
+            }
+
+            m.SendGump(new PokerGump(m, _session, status, useBank), true);
+        }
+    }
+}
+
+namespace Server.Items
+{
+    [SerializationGenerator(0)]
+    public abstract partial class PokerMachine : Item
+    {
+        public static readonly TimeSpan RefillDelay = TimeSpan.FromHours(2.0);
+        private static readonly List<PokerMachine> _machines = [];
+        private static Timer _refill;
+
+        [SerializableField(0)]
+        [InvalidateProperties]
+        [SerializedCommandProperty(AccessLevel.Administrator)]
+        private int _goldInMachine;
+
+        protected PokerMachine() : base(0x1173)
+        {
+            Movable = false;
+            Hue = 0x58;
+            _goldInMachine = 30000 + (Utility.Random(700) + 1) * 100;
+            Register();
+        }
+
+        public override string DefaultName => "a Poker Machine";
+
+        public abstract int MinBet { get; }
+        public abstract int MaxBet { get; }
+        public abstract int BetChange { get; }
+        public abstract int[] WinningsTable { get; }
+
+        private void Register()
+        {
+            _machines.Add(this);
+            _refill ??= Timer.DelayCall(RefillDelay, RefillDelay, RefillAll);
+        }
+
+        [AfterDeserialization]
+        private void AfterDeserialization() => Register();
+
+        public override void OnAfterDelete()
+        {
+            _machines.Remove(this);
+            base.OnAfterDelete();
+        }
+
+        private static void RefillAll()
+        {
+            foreach (var machine in _machines)
+            {
+                Timer.DelayCall(TimeSpan.FromSeconds(Utility.Random(200)), machine.Refill);
+            }
+        }
+
+        public void Refill()
+        {
+            if (Deleted || GoldInMachine >= 50000)
+            {
+                return;
+            }
+
+            GoldInMachine = 100000 + Utility.Random(10000);
+            Visible = true;
+            PublicOverheadMessage(MessageType.Regular, 0x0, true, "Calculating gold in machine");
+
+            for (var i = 0; i <= 6; i += 2)
+            {
+                Timer.DelayCall(TimeSpan.FromSeconds(i), () => Effects.PlaySound(Location, Map, 0x36));
+            }
+        }
+
+        public override void GetProperties(IPropertyList list)
+        {
+            base.GetProperties(list);
+            list.Add(1060658, $"{"Bets"}\t{MinBet}gp - {MaxBet}gp"); // ~1_val~: ~2_val~
+            list.Add(1060659, $"{"Jackpot"}\t{_goldInMachine / 3}gp"); // ~1_val~: ~2_val~
+        }
+
+        public override void OnDoubleClick(Mobile from)
+        {
+            if (!from.InRange(GetWorldLocation(), 2))
+            {
+                from.SendLocalizedMessage(500446); // That is too far away.
+            }
+            else if (_goldInMachine <= 0)
+            {
+                from.SendMessage("This machine is out of gold.");
+            }
+            else
+            {
+                Effects.PlaySound(Location, Map, 533);
+                from.SendGump(new PokerGump(from, new PokerSession(this), "Welcome to Defiance AOS Poker Machine.", false), true);
+            }
+        }
+
+        public bool Charge(Mobile player, int amount, bool useBank)
+        {
+            var paid = useBank ? Banker.Withdraw(player, amount) : player.Backpack?.ConsumeTotal(typeof(Gold), amount) == true;
+
+            if (!paid)
+            {
+                return false;
+            }
+
+            player.SendMessage(useBank ? $"{amount}gp has been removed from your bankbox." : $"{amount}gp has been removed from your backpack.");
+            Effects.PlaySound(Location, Map, 0x36);
+            GoldInMachine += amount;
+            return true;
+        }
+
+        // Pays the hand's winnings out of the machine and returns what to tell the player.
+        public string Settle(Mobile player, PokerSession session)
+        {
+            var hand = PokerCards.Evaluate(session.Hand);
+
+            if (hand == PokerHand.None)
+            {
+                return "You did not win anything.";
+            }
+
+            var amount = Math.Min(session.Winning(hand), GoldInMachine);
+            GoldInMachine -= amount;
+
+            if (GoldInMachine == 0)
+            {
+                Visible = false;
+            }
+
+            Effects.PlaySound(Location, Map, 0x36);
+            PublicOverheadMessage(MessageType.Regular, 0x0, true, "Winner!");
+            PublicOverheadMessage(MessageType.Regular, 0x0, true, $"{hand}");
+
+            if (Banker.Deposit(player, amount))
+            {
+                return $"You won! ( {hand} ) {amount} gp have been placed in your bank box.";
+            }
+
+            for (var left = amount; left > 0; left -= 1_000_000)
+            {
+                player.AddToBackpack(new BankCheck(Math.Min(left, 1_000_000)));
+            }
+
+            return $"You won! ( {hand} ) {amount} gp have been placed in your backpack, because your bank box is full.";
+        }
+    }
+
+    [SerializationGenerator(0)]
+    [Flippable(0x1173, 0x1174)]
+    public partial class PokerMachineLow : PokerMachine
+    {
+        private static readonly int[] _table = [1000, 600, 300, 150, 55, 50, 35, 15, 10, 0];
+
+        [Constructible(AccessLevel.GameMaster)]
+        public PokerMachineLow()
+        {
+        }
+
+        public override int MinBet => 10;
+        public override int MaxBet => 50;
+        public override int BetChange => 10;
+        public override int[] WinningsTable => _table;
+    }
+
+    [SerializationGenerator(0)]
+    [Flippable(0x1173, 0x1174)]
+    public partial class PokerMachineMedium : PokerMachine
+    {
+        private static readonly int[] _table = [10000, 6000, 3000, 1500, 550, 500, 350, 150, 80, 0];
+
+        [Constructible(AccessLevel.GameMaster)]
+        public PokerMachineMedium()
+        {
+        }
+
+        public override int MinBet => 100;
+        public override int MaxBet => 500;
+        public override int BetChange => 100;
+        public override int[] WinningsTable => _table;
+    }
+
+    [SerializationGenerator(0)]
+    [Flippable(0x1173, 0x1174)]
+    public partial class PokerMachineHigh : PokerMachine
+    {
+        private static readonly int[] _table = [100000, 50000, 30000, 10000, 5000, 4500, 2500, 1500, 500, 0];
+
+        [Constructible(AccessLevel.GameMaster)]
+        public PokerMachineHigh()
+        {
+        }
+
+        public override int MinBet => 1000;
+        public override int MaxBet => 5000;
+        public override int BetChange => 1000;
+        public override int[] WinningsTable => _table;
+    }
+}
MUO_EOF_0
chmod 0644 $BASE/patches/0021-dfi-lottery-poker.patch
install -d "$(dirname $BASE/patches/0022-dfi-crate-race.patch)"
cat > $BASE/patches/0022-dfi-crate-race.patch <<'MUO_EOF_0'
diff --git a/Projects/UOContent.Tests/Tests/Custom/DfiCrateRaceTests.cs b/Projects/UOContent.Tests/Tests/Custom/DfiCrateRaceTests.cs
new file mode 100644
index 000000000..63f6bbf3a
--- /dev/null
+++ b/Projects/UOContent.Tests/Tests/Custom/DfiCrateRaceTests.cs
@@ -0,0 +1,253 @@
+using System;
+using System.Collections.Generic;
+using Server;
+using Server.Custom.Dfi.CrateRace;
+using Server.Custom.Dfi.Events;
+using Server.Items;
+using Server.Misc;
+using Server.Mobiles;
+using Xunit;
+
+namespace UOContent.Tests.Custom;
+
+[Collection("Sequential UOContent Tests")]
+public class DfiCrateRaceTests : IDisposable
+{
+    private static readonly Point3D StoneAt = new(5300, 1300, 0);
+
+    private readonly List<IEntity> _created = new();
+
+    public DfiCrateRaceTests()
+    {
+        if (NameList.GetNameList("male") == null)
+        {
+            NameList.Configure();
+        }
+    }
+
+    public void Dispose()
+    {
+        EventSystem.Stop();
+
+        foreach (var e in _created)
+        {
+            e?.Delete();
+        }
+
+        _created.Clear();
+        CrateRace.PartData.Clear();
+        CrateRace.PartList.Clear();
+        CrateRace.FinData.Clear();
+    }
+
+    private T Track<T>(T e) where T : IEntity
+    {
+        _created.Add(e);
+        return e;
+    }
+
+    private PlayerMobile Player(int bank = 0)
+    {
+        var m = Track(new PlayerMobile());
+        m.Player = true;
+        m.Body = 0x190;
+        m.RawStr = 100;
+        m.AddItem(new Backpack());
+        m.AddItem(new BankBox(m));
+        m.MoveToWorld(new Point3D(1434, 1690, 0), Map.Felucca);
+
+        if (bank > 0)
+        {
+            m.BankBox.DropItem(new BankCheck(bank));
+        }
+
+        return m;
+    }
+
+    private CrateStone Stone()
+    {
+        var stone = Track(new CrateStone { Price = 1000, MinutesOpen = 2 });
+        stone.MoveToWorld(StoneAt, Map.Felucca);
+        return stone;
+    }
+
+    [Fact]
+    public void Track_BuildsDfisTrackAroundTheStone()
+    {
+        var stone = Stone();
+
+        stone.BuildTrack();
+        var track = Assert.IsType<RaceTrackAddon>(stone.Track);
+        Track(track);
+
+        Assert.Equal(RaceTrackData.Tiles.Length / 4, track.Components.Count);
+        Assert.Equal(new Rectangle2D(StoneAt.X - 22, StoneAt.Y - 32, 45, 65), stone.RegionRect);
+
+        // The default layout: four lanes clockwise from the top straight, and a finish line across it.
+        var lines = CrateRace.FinishLines.FindAll(l => l.Map == Map.Felucca && l.X == StoneAt.X);
+        lines.ForEach(l => Track(l));
+        Assert.Equal(4, stone.Rectangles.Count);
+        Assert.Equal(Direction.East, stone.Rectangles[0].FirstDirection);
+        Assert.Equal(9, lines.Count);
+        Assert.All(lines, l => Assert.True(stone.Rectangles[0].Contains(l.X, l.Y)));
+
+        stone.DemolishTrack();
+        Assert.True(track.Deleted);
+    }
+
+    [Fact]
+    public void Stone_KeepsRectanglesWithTheirDirections()
+    {
+        var stone = Stone();
+
+        stone.Rectangles =
+        [
+            new CrateRectangle(new Rectangle2D(10, 10, 5, 20), Direction.North, Direction.East),
+            new CrateRectangle(new Rectangle2D(20, 10, 20, 5), Direction.East, Direction.South)
+        ];
+
+        var back = stone.Rectangles;
+        Assert.Equal(2, back.Count);
+        Assert.Equal(Direction.East, back[0].SecondDirection);
+        Assert.Equal(Direction.South, back[1].SecondDirection);
+        Assert.Equal(new Rectangle2D(20, 10, 20, 5), back[1].Rectangle);
+    }
+
+    [Fact]
+    public void Joining_ChargesUndressesAndBringsTheRacerToTheTrack()
+    {
+        var stone = Stone();
+        var player = Player(5000);
+        var shirt = new FancyShirt { Layer = Layer.Shirt };
+        player.EquipItem(shirt);
+        player.Backpack.DropItem(new Gold(50));
+
+        CrateRace.Start(stone);
+        Assert.True(EventSystem.Open);
+
+        Assert.Null(CrateRace.Join(player));
+
+        Assert.True(CrateRace.Participant(player));
+        // The fee left the bank; the backpack's 50 gold went into the wardrobe bag in the bank.
+        Assert.Equal(4050, Banker.GetBalance(player));
+        Assert.Equal(1000, CrateRace.BankedMoney);
+        Assert.Empty(player.Backpack.Items);
+        Assert.Null(player.FindItemOnLayer(Layer.Shirt));
+        Assert.Equal(StoneAt, player.Location);
+
+        Assert.NotNull(CrateRace.Join(player));
+    }
+
+    [Fact]
+    public void Wardrobe_GivesEverythingBack()
+    {
+        var player = Player();
+        var shirt = new FancyShirt { Layer = Layer.Shirt };
+        player.EquipItem(shirt);
+        var gold = new Gold(50);
+        player.Backpack.DropItem(gold);
+
+        Assert.True(EventWardrobe.Undress(player));
+        Assert.False(EventWardrobe.Undress(player));
+        Assert.True(EventWardrobe.Redress(player));
+
+        Assert.Same(shirt, player.FindItemOnLayer(Layer.Shirt));
+        Assert.True(gold.IsChildOf(player.Backpack));
+        Assert.False(EventWardrobe.IsUndressed(player));
+    }
+
+    [Fact]
+    public void Crates_StackThreeAndPushTheOldestOut()
+    {
+        var rd = new RaceData(Player());
+        var freeze = new FreezeCrateType();
+        var quake = new EarthQuakeCrateType();
+
+        rd.Store(freeze);
+        rd.Store(quake);
+        rd.Store(freeze);
+        rd.Store(quake);
+
+        Assert.Same(quake, rd.Crate1);
+        Assert.Same(freeze, rd.Crate2);
+        Assert.Same(quake, rd.Crate3);
+    }
+
+    [Fact]
+    public void Damage_IsTakenByShieldsFirst()
+    {
+        var player = Player();
+        player.Hits = player.HitsMax;
+        var rd = new RaceData(player) { Mirror = true, TempMirror = true };
+
+        CrateRace.HandleDamage(rd, .5);
+        Assert.False(rd.TempMirror);
+        Assert.Equal(player.HitsMax, player.Hits);
+
+        CrateRace.HandleDamage(rd, .5);
+        Assert.False(rd.Mirror);
+        Assert.Equal(player.HitsMax, player.Hits);
+
+        CrateRace.HandleDamage(rd, .5);
+        Assert.True(player.Hits < player.HitsMax);
+    }
+
+    [Fact]
+    public void Finishing_TheLastLapPlacesTheRacer()
+    {
+        var player = Player();
+        var rd = new RaceData(player) { Lap = 0 };
+        CrateRace.Laps = 2;
+        CrateRace.PartData[player] = rd;
+        CrateRace.PartList.Add(rd);
+        CrateRace.Map = Map.Felucca;
+
+        Assert.True(CrateRace.MobFinish(player));
+        Assert.True(CrateRace.MobFinish(player));
+        Assert.False(CrateRace.MobFinish(player));
+
+        Assert.Single(CrateRace.FinData);
+        Assert.Equal(1, CrateRace.FinData[0].Place);
+        Assert.False(CrateRace.Participant(player));
+    }
+
+    [Fact]
+    public void Placing_RanksByLapThenByRectangle()
+    {
+        var a = Player();
+        var b = Player();
+        var stone = Stone();
+        stone.Rectangles =
+        [
+            new CrateRectangle(new Rectangle2D(1400, 1680, 20, 20)),
+            new CrateRectangle(new Rectangle2D(1420, 1680, 20, 20))
+        ];
+        CrateRace.Map = Map.Felucca;
+        typeof(CrateRace).GetProperty(nameof(CrateRace.Rectangles))!.SetValue(null, stone.Rectangles);
+
+        a.Location = new Point3D(1405, 1690, 0);
+        b.Location = new Point3D(1425, 1690, 0);
+        var ra = new RaceData(a) { Lap = 1 };
+        var rb = new RaceData(b) { Lap = 1 };
+        CrateRace.PartList.Add(ra);
+        CrateRace.PartList.Add(rb);
+
+        CrateRace.CheckPlace();
+        Assert.Equal(1, rb.Place);
+        Assert.Same(b, CrateRace.FirstPlace);
+
+        ra.Lap = 2;
+        CrateRace.CheckPlace();
+        Assert.Equal(1, ra.Place);
+        Assert.Equal(2, rb.Place);
+    }
+
+    [Fact]
+    public void EventMaster_AndRaceItemsConstruct()
+    {
+        Assert.Contains(Track(new EventNpc()), EventSystem.Npcs);
+        Assert.False(Track(new RaceCrate()).Deleted);
+        Assert.False(Track(new CrateApple()).Deleted);
+        Assert.Contains(Track(new RaceFinishLine()), CrateRace.FinishLines);
+    }
+}
diff --git a/Projects/UOContent/Custom/DFI/Games/CrateRace.cs b/Projects/UOContent/Custom/DFI/Games/CrateRace.cs
new file mode 100644
index 000000000..a6739b40f
--- /dev/null
+++ b/Projects/UOContent/Custom/DFI/Games/CrateRace.cs
@@ -0,0 +1,1517 @@
+// DFI Network's crate race ("a Sunny Production, 2005"), ported from DFI RUNUO Scripts/Custom/Engines/Crate Race.
+// Players pay to join through the event masters, are undressed, and race laps of a walled track. Crates drop on
+// the track: running into one either takes effect (healing, a shield, damage) or stores it for later use by
+// saying "use first/second/third crate" or clicking it on the race gump (explosive drop, slick patch, freeze,
+// earthquake, energy bolt on the leader, chain lightning, flying bomb). Apples restore stamina or health. A
+// racer who dies is set twenty tiles back along the track. The first three take a third, a sixth and a ninth of
+// the entry fees, and copper bars if rewards are on.
+//
+// Staff set it up at the crate stone: build DFI's track around it, draw the track's rectangles in racing order
+// (each with the two directions a racer leaves it by), lay a finish line, set the region, then start it.
+
+using System;
+using System.Collections.Generic;
+using ModernUO.Serialization;
+using Server.Custom.Dfi.Events;
+using Server.Gumps;
+using Server.Items;
+using Server.Mobiles;
+using Server.Network;
+using Server.Regions;
+using Server.Spells;
+
+namespace Server.Custom.Dfi.CrateRace
+{
+    public class CrateRectangle
+    {
+        public CrateRectangle(Rectangle2D rect, Direction first = Direction.North, Direction second = Direction.North)
+        {
+            Rectangle = rect;
+            FirstDirection = first;
+            SecondDirection = second;
+        }
+
+        public Rectangle2D Rectangle { get; set; }
+        public Direction FirstDirection { get; set; }
+        public Direction SecondDirection { get; set; }
+
+        public bool Contains(int x, int y) =>
+            Rectangle.Start.X <= x && Rectangle.Start.Y <= y && Rectangle.End.X >= x && Rectangle.End.Y >= y;
+    }
+
+    public class RaceData : IComparable<RaceData>
+    {
+        public RaceData(Mobile m) => Part = m;
+
+        public Mobile Part { get; }
+        public bool Mirror, TempMirror, SwitchGump, Frozen;
+        public CrateType Crate1, Crate2, Crate3;
+        public int Place, Lap;
+
+        public bool UsedMirror()
+        {
+            if (TempMirror)
+            {
+                TempMirror = false;
+                return true;
+            }
+
+            if (Mirror)
+            {
+                Mirror = false;
+                return true;
+            }
+
+            return false;
+        }
+
+        // Ahead first: more laps, then further along the track's rectangles.
+        public int CompareTo(RaceData other) =>
+            Lap != other.Lap
+                ? other.Lap - Lap
+                : CrateRace.GetRectangleID(other.Part.X, other.Part.Y) - CrateRace.GetRectangleID(Part.X, Part.Y);
+
+        public void Store(CrateType type)
+        {
+            if (Crate1 == null)
+            {
+                Crate1 = type;
+            }
+            else if (Crate2 == null)
+            {
+                Crate2 = type;
+            }
+            else if (Crate3 == null)
+            {
+                Crate3 = type;
+            }
+            else
+            {
+                Crate3 = Crate2;
+                Crate2 = Crate1;
+                Crate1 = type;
+                CrateRace.OpenCrates--;
+            }
+
+            CrateRace.OpenCrates++;
+        }
+
+        public void Use(int slot)
+        {
+            var type = slot switch { 1 => Crate1, 2 => Crate2, _ => Crate3 };
+
+            if (type == null)
+            {
+                return;
+            }
+
+            switch (slot)
+            {
+                case 1:
+                    {
+                        Crate1 = null;
+                        break;
+                    }
+                case 2:
+                    {
+                        Crate2 = null;
+                        break;
+                    }
+                default:
+                    {
+                        Crate3 = null;
+                        break;
+                    }
+            }
+
+            type.OnUsage(Part);
+        }
+    }
+
+    public record FinishedData(Mobile Racer, int Place, TimeSpan Time);
+
+    public static class CrateRace
+    {
+        public const string Name = "Crate Race Event";
+        public const int DeathMoves = 20;
+
+        private static readonly Point3D _evictTo = new(1434, 1707, 18);
+
+        public static Dictionary<Mobile, RaceData> PartData { get; } = [];
+        public static List<RaceData> PartList { get; } = [];
+        public static List<RaceCrate> CrateList { get; } = [];
+        public static List<CrateApple> AppleList { get; } = [];
+        public static List<FinishedData> FinData { get; } = [];
+        public static List<RaceFinishLine> FinishLines { get; } = [];
+        public static List<CrateRectangle> Rectangles { get; private set; } = [];
+
+        public static int OpenCrates, BankedMoney, MaxCrates, Price, Laps, X, Y, Z;
+        public static bool Running, Animalised, QuickSpeed, Rewards;
+        public static Point3D StoneLocation;
+        public static Map Map;
+        public static Mobile FirstPlace;
+        public static Timer FreezeTimer;
+
+        private static CrateRegion _region;
+        private static double[] _rectangleChance = [];
+        private static DateTime _started;
+        private static int _countdown;
+        private static int _tick;
+        private static Timer _startTimer, _raceTimer, _stopTimer;
+
+        public static int Crates => CrateList.Count;
+        public static int Participants => PartData.Count;
+        public static bool Participant(Mobile m) => PartData.ContainsKey(m);
+
+        public static int GetRectangleID(int x, int y) => Rectangles.FindIndex(r => r.Contains(x, y));
+        public static CrateRectangle GetRectangle(int x, int y) => Rectangles.Find(r => r.Contains(x, y));
+
+        public static int GetHighestZ(int x, int y)
+        {
+            var z = Map.Tiles.GetLandTile(x, y).Z;
+
+            foreach (var item in Map.GetItemsInBounds(new Rectangle2D(x, y, 1, 1)))
+            {
+                z = Math.Max(z, item.GetSurfaceTop().Z);
+            }
+
+            return z;
+        }
+
+        public static void SetPlayerSpeed(RaceData rd)
+        {
+            // With quick speed racers run as if mounted and freezes bring them to normal; otherwise freezes walk.
+            var setting = QuickSpeed
+                ? rd.Frozen ? SpeedControlSetting.Disable : SpeedControlSetting.Mount
+                : rd.Frozen ? SpeedControlSetting.Walk : SpeedControlSetting.Disable;
+
+            rd.Part.NetState.SendSpeedControl(setting);
+        }
+
+        public static void SetPlayerSpeed(Mobile m)
+        {
+            if (PartData.TryGetValue(m, out var rd))
+            {
+                SetPlayerSpeed(rd);
+            }
+        }
+
+        public static void RequestJoin(Mobile m)
+        {
+            if (m.Player)
+            {
+                m.SendGump(new CrateJoinGump(), true);
+            }
+        }
+
+        public static string Join(PlayerMobile pm)
+        {
+            if (!EventSystem.Open || Participant(pm))
+            {
+                return "The race has already started.";
+            }
+
+            if (Price > 0 && !Banker.Withdraw(pm, Price))
+            {
+                return "You do not have enough money to participate.";
+            }
+
+            if (!EventWardrobe.Undress(pm))
+            {
+                if (Price > 0)
+                {
+                    Banker.Deposit(pm, Price);
+                }
+
+                return "You could not be undressed for the race.";
+            }
+
+            BankedMoney += Math.Max(Price, 0);
+            var data = new RaceData(pm);
+            PartData[pm] = data;
+            PartList.Add(data);
+            SetPlayerSpeed(data);
+            pm.MoveToWorld(StoneLocation, Map);
+
+            if (Animalised)
+            {
+                pm.SendGump(new CrateRaceCharGump(), true);
+            }
+
+            return null;
+        }
+
+        public static void Start(CrateStone stone)
+        {
+            Map = stone.Map;
+            X = stone.X;
+            Y = stone.Y;
+            Z = stone.Z;
+            StoneLocation = stone.Location;
+            Rewards = stone.Rewards;
+            Animalised = stone.Animalised;
+            QuickSpeed = stone.QuickSpeed;
+            MaxCrates = stone.MaxCrates;
+            Price = stone.Price;
+            Laps = stone.Laps;
+            Rectangles = stone.Rectangles;
+
+            if (stone.RegionRect.Width > 0)
+            {
+                _region = new CrateRegion(stone.RegionRect, Map);
+                _region.Register();
+            }
+
+            Running = true;
+            EventSystem.Start(stone.MinutesOpen, Name, StartNewRace, StopRace, RequestJoin);
+        }
+
+        private static void StartNewRace()
+        {
+            if (Rectangles.Count < 4 || PartData.Count == 0)
+            {
+                EventSystem.Stop();
+                return;
+            }
+
+            SetRectangleChances();
+            _started = Core.Now;
+
+            var row = 0;
+            var column = 1;
+
+            foreach (var m in PartData.Keys)
+            {
+                m.CloseGump<CrateRaceCharGump>();
+
+                if (Animalised && (int)m.BodyMod is 0 or 400 or 401)
+                {
+                    m.BodyMod = 0xD0;
+                }
+
+                m.Frozen = true;
+                m.Location = new Point3D(X - column, Y - 22 - row, Z);
+
+                if (++row % 8 == 0)
+                {
+                    row = 0;
+                    column++;
+                }
+            }
+
+            _countdown = 3;
+            _startTimer = Timer.DelayCall(TimeSpan.FromSeconds(1), TimeSpan.FromSeconds(1), CountDown);
+        }
+
+        private static void SetRectangleChances()
+        {
+            var total = 0;
+
+            foreach (var r in Rectangles)
+            {
+                total += r.Rectangle.Width * r.Rectangle.Height;
+            }
+
+            _rectangleChance = new double[Rectangles.Count];
+            var cumulative = 0.0;
+
+            for (var i = 0; i < Rectangles.Count; i++)
+            {
+                cumulative += (double)Rectangles[i].Rectangle.Width * Rectangles[i].Rectangle.Height / Math.Max(1, total);
+                _rectangleChance[i] = cumulative;
+            }
+        }
+
+        private static void CountDown()
+        {
+            _countdown--;
+
+            foreach (var m in PartData.Keys)
+            {
+                if (_countdown == 0)
+                {
+                    m.Frozen = false;
+                    m.SendMessage("The race has started!");
+                }
+                else
+                {
+                    m.SendMessage($"{_countdown} seconds untill the race begins!");
+                }
+            }
+
+            if (_countdown == 0)
+            {
+                _startTimer.Stop();
+                FinData.Clear();
+                _raceTimer = Timer.DelayCall(TimeSpan.Zero, TimeSpan.FromMilliseconds(500), OnRaceTimer);
+            }
+        }
+
+        private static void OnRaceTimer()
+        {
+            _tick++;
+            DropCrate();
+            DropApple();
+
+            if (_tick % 2 == 0)
+            {
+                foreach (var rd in PartList)
+                {
+                    rd.Part.SendGump(new CrateRaceGump(rd), true);
+                }
+            }
+
+            if (_tick == 4)
+            {
+                _tick = 0;
+                CheckPlace();
+            }
+        }
+
+        private static Point3D RandomDropLocation()
+        {
+            var roll = Utility.RandomDouble();
+            var rect = Rectangles[^1].Rectangle;
+
+            for (var i = 0; i < _rectangleChance.Length; i++)
+            {
+                if (roll <= _rectangleChance[i])
+                {
+                    rect = Rectangles[i].Rectangle;
+                    break;
+                }
+            }
+
+            var x = Utility.RandomMinMax(rect.Start.X, rect.End.X);
+            var y = Utility.RandomMinMax(rect.Start.Y, rect.End.Y);
+            return new Point3D(x, y, GetHighestZ(x, y));
+        }
+
+        private static void DropCrate()
+        {
+            if (Crates >= MaxCrates)
+            {
+                return;
+            }
+
+            var crate = new RaceCrate();
+            var loc = RandomDropLocation();
+            crate.MoveToWorld(loc, Map);
+            Effects.PlaySound(loc, Map, 0x202);
+            Effects.SendLocationEffect(loc, Map, 0x376A, 30, crate.Hue, 3);
+            Effects.SendLocationEffect(loc, Map, 0x3779, 30, crate.Hue, 3);
+            CrateList.Add(crate);
+        }
+
+        private static void DropApple()
+        {
+            if (AppleList.Count < 15)
+            {
+                var apple = new CrateApple();
+                apple.MoveToWorld(RandomDropLocation(), Map);
+                AppleList.Add(apple);
+            }
+        }
+
+        public static void CheckPlace()
+        {
+            PartList.Sort();
+            var place = FinData.Count + 1;
+
+            foreach (var rd in PartList)
+            {
+                if (place == FinData.Count + 1)
+                {
+                    FirstPlace = rd.Part;
+                }
+
+                rd.Place = place++;
+            }
+        }
+
+        // A racer who dies is set back DeathMoves tiles along the track's directions.
+        public static void OnDeath(Mobile m)
+        {
+            var x = m.X;
+            var y = m.Y;
+            var moves = DeathMoves;
+            var rect = GetRectangle(x, y);
+            var first = true;
+            var crossedStart = false;
+
+            while (rect != null && !NewLocation(rect, first, ref x, ref y, ref moves))
+            {
+                if (rect == Rectangles[0])
+                {
+                    crossedStart = true;
+                }
+
+                first = !first;
+
+                if (first)
+                {
+                    rect = GetRectangle(x, y);
+                }
+            }
+
+            if (rect == null)
+            {
+                return;
+            }
+
+            if (rect == Rectangles[0])
+            {
+                foreach (var line in FinishLines)
+                {
+                    if (line.X == x && line.Y == y)
+                    {
+                        switch (rect.FirstDirection)
+                        {
+                            case Direction.North:
+                                {
+                                    y++;
+                                    break;
+                                }
+                            case Direction.East:
+                                {
+                                    x--;
+                                    break;
+                                }
+                            case Direction.South:
+                                {
+                                    y--;
+                                    break;
+                                }
+                            case Direction.West:
+                                {
+                                    x++;
+                                    break;
+                                }
+                        }
+
+                        break;
+                    }
+                }
+            }
+            else if (crossedStart && PartData.TryGetValue(m, out var rd))
+            {
+                rd.Lap--;
+            }
+
+            m.MoveToWorld(new Point3D(x, y, GetHighestZ(x, y)), Map);
+        }
+
+        private static bool NewLocation(CrateRectangle rect, bool first, ref int x, ref int y, ref int moves)
+        {
+            var (edge, vertical, positive) = (first ? rect.FirstDirection : rect.SecondDirection) switch
+            {
+                Direction.North => (rect.Rectangle.Start.Y, true, false),
+                Direction.East  => (rect.Rectangle.End.X, false, true),
+                Direction.South => (rect.Rectangle.End.Y, true, true),
+                _               => (rect.Rectangle.Start.X, false, false)
+            };
+
+            var coord = vertical ? y : x;
+            var completed = false;
+            var difference = 0;
+
+            if (positive && coord + moves <= edge)
+            {
+                coord += moves;
+                completed = true;
+            }
+            else if (!positive && coord - moves >= edge)
+            {
+                coord -= moves;
+                completed = true;
+            }
+            else
+            {
+                difference = edge - coord + (first ? 0 : positive ? 1 : -1);
+                coord += difference;
+            }
+
+            if (vertical)
+            {
+                y = coord;
+            }
+            else
+            {
+                x = coord;
+            }
+
+            moves -= Math.Abs(difference);
+            return completed;
+        }
+
+        // Shields absorb a hit; otherwise the damage is a share of the racer's hits, softened as the track fills.
+        public static void HandleDamage(RaceData rd, double amount)
+        {
+            if (rd.TempMirror)
+            {
+                rd.Part.SendMessage("But your temporary shield has saved you from any harm done.");
+                rd.TempMirror = false;
+            }
+            else if (rd.Mirror)
+            {
+                rd.Part.SendMessage("But your shield has saved you from any harm done.");
+                rd.Mirror = false;
+            }
+            else
+            {
+                var damage = (int)(rd.Part.HitsMax * amount);
+                damage -= damage * (OpenCrates + Crates / 2) / 100;
+                rd.Part.Damage(Math.Max(0, damage));
+            }
+        }
+
+        public static void StopFreeze()
+        {
+            foreach (var rd in PartList)
+            {
+                if (rd.Frozen)
+                {
+                    rd.Frozen = false;
+                    SetPlayerSpeed(rd);
+                    rd.Part.SendMessage("The effect of a freezecrate has worn off!");
+                }
+            }
+        }
+
+        // Returns true while the racer still has laps to go.
+        public static bool MobFinish(Mobile m)
+        {
+            if (!PartData.TryGetValue(m, out var rd))
+            {
+                return false;
+            }
+
+            rd.Lap++;
+
+            if (rd.Lap != Laps + 1)
+            {
+                return true;
+            }
+
+            var place = FinData.Count + 1;
+            FinData.Add(new FinishedData(m, place, Core.Now - _started));
+
+            m.Location = place switch
+            {
+                1 => new Point3D(X, Y - 15, Z + 23),
+                2 => new Point3D(X, Y - 17, Z + 20),
+                3 => new Point3D(X, Y - 13, Z + 20),
+                _ => new Point3D(X + 3, Y - 17, Z)
+            };
+
+            if (place == 1)
+            {
+                _stopTimer = Timer.DelayCall(TimeSpan.FromMinutes(3), EventSystem.Stop);
+            }
+
+            PartData.Remove(m);
+            PartList.Remove(rd);
+
+            if (PartData.Count == 0)
+            {
+                EventSystem.Stop();
+            }
+
+            return false;
+        }
+
+        private static void StopRace()
+        {
+            foreach (var m in PartData.Keys)
+            {
+                m.SendMessage("The race has stopped!");
+            }
+
+            _stopTimer?.Stop();
+            _raceTimer?.Stop();
+            _startTimer?.Stop();
+            _region?.Unregister();
+            _region = null;
+
+            foreach (var crate in CrateList.ToArray())
+            {
+                crate.Delete();
+            }
+
+            foreach (var apple in AppleList.ToArray())
+            {
+                apple.Delete();
+            }
+
+            foreach (var rd in PartList.ToArray())
+            {
+                RemovePlayer(rd.Part);
+            }
+
+            PartList.Clear();
+            PartData.Clear();
+
+            foreach (var fd in FinData)
+            {
+                var (money, text, bars) = fd.Place switch
+                {
+                    1 => (BankedMoney / 3, "You have won this Crate Race, Congratulations!", 3),
+                    2 => (BankedMoney / 6, "You have managed to become second in this Crate Race, Congratulations!", 2),
+                    3 => (BankedMoney / 9, "You have managed to become third in this Crate Race, Congratulations!", 1),
+                    _ => (0, "Thank you for participating in this Crate Race, unfortunately you have not won anything. Good luck next time!", 0)
+                };
+
+                if (Rewards && bars > 0)
+                {
+                    EventRewardSystem.CreateCopperBar(fd.Racer, bars, "Crate Race Event");
+                }
+
+                fd.Racer.SendMessage(text);
+
+                if (money > 0)
+                {
+                    fd.Racer.AddToBackpack(new BankCheck(money));
+                }
+
+                RemovePlayer(fd.Racer);
+                fd.Racer.SendGump(new RaceRankGump(new List<FinishedData>(FinData), 0), true);
+            }
+
+            OpenCrates = 0;
+            BankedMoney = 0;
+            Running = false;
+        }
+
+        private static void RemovePlayer(Mobile m)
+        {
+            m.CloseGump<CrateRaceGump>();
+            m.NetState.SendSpeedControl(SpeedControlSetting.Disable);
+            m.BodyMod = 0;
+            m.Frozen = false;
+            EventWardrobe.Redress(m);
+            EventSystem.RemoveToRandomLoc(m);
+        }
+
+        public static void Evict(Mobile m) => Timer.DelayCall(() => m.MoveToWorld(_evictTo, Map.Felucca));
+    }
+
+    public class CrateRegion : BaseRegion
+    {
+        public CrateRegion(Rectangle2D rect, Map map) : base("A Crate Race Track", map, 150, rect)
+        {
+        }
+
+        public override bool AllowHousing(Mobile from, Point3D p) => false;
+        public override bool AllowSpawn() => false;
+        public override bool AllowBeneficial(Mobile from, Mobile target) => false;
+        public override bool AllowHarmful(Mobile from, Mobile target) => false;
+        public override bool CanUseStuckMenu(Mobile m) => false;
+
+        public override bool OnBeginSpellCast(Mobile from, ISpell s)
+        {
+            if (from.AccessLevel == AccessLevel.Player)
+            {
+                from.SendMessage("You cannot cast spells on a race track.");
+                return false;
+            }
+
+            return base.OnBeginSpellCast(from, s);
+        }
+
+        public override bool OnSkillUse(Mobile m, int skill)
+        {
+            if (m.AccessLevel == AccessLevel.Player)
+            {
+                m.SendMessage("You cannot use that skill here.");
+                return false;
+            }
+
+            return base.OnSkillUse(m, skill);
+        }
+
+        public override void OnSpeech(SpeechEventArgs e)
+        {
+            if (CrateRace.Running && CrateRace.PartData.TryGetValue(e.Mobile, out var rd))
+            {
+                var speech = e.Speech.ToLowerInvariant();
+                var slot = speech.Contains("use first crate") ? 1 :
+                    speech.Contains("use second crate") ? 2 :
+                    speech.Contains("use third crate") ? 3 : 0;
+
+                if (slot > 0)
+                {
+                    rd.Use(slot);
+                    e.Blocked = true;
+                    return;
+                }
+            }
+
+            base.OnSpeech(e);
+        }
+
+        public override void OnEnter(Mobile m)
+        {
+            if (CrateRace.Participant(m) || m.AccessLevel > AccessLevel.Player)
+            {
+                CrateRace.SetPlayerSpeed(m);
+
+                if (CrateRace.Animalised && CrateRace.Participant(m) && m.BodyMod == 0)
+                {
+                    m.BodyMod = 208;
+                }
+
+                base.OnEnter(m);
+            }
+            else if (m.Player)
+            {
+                CrateRace.Evict(m);
+            }
+        }
+
+        public override void OnExit(Mobile m)
+        {
+            if (!CrateRace.Participant(m) && m.Player)
+            {
+                m.BodyMod = 0;
+                m.NetState.SendSpeedControl(SpeedControlSetting.Disable);
+            }
+
+            base.OnExit(m);
+        }
+
+        public override bool OnBeforeDeath(Mobile m)
+        {
+            if (!CrateRace.Participant(m))
+            {
+                return base.OnBeforeDeath(m);
+            }
+
+            // Racers do not die: they are healed and set back along the track.
+            m.Hits = m.HitsMax;
+            m.Stam = m.StamMax;
+            CrateRace.OnDeath(m);
+            return false;
+        }
+
+        public override TimeSpan GetLogoutDelay(Mobile m) =>
+            m.AccessLevel == AccessLevel.Player ? TimeSpan.FromMinutes(60) : base.GetLogoutDelay(m);
+    }
