+    // A crate dropped behind a racer that blows up when anyone else comes near, or after three seconds.
+    public class DropBombType : SingleUseCrateType
+    {
+        private readonly RaceCrate _crate;
+
+        public DropBombType(Mobile owner, RaceCrate crate)
+        {
+            Owner = owner;
+            _crate = crate;
+            Timer.DelayCall(TimeSpan.FromSeconds(3), Explode);
+        }
+
+        public Mobile Owner { get; }
+        public override int Hue => 33;
+
+        public override void OnMoveOver(Mobile m)
+        {
+            if (m != Owner)
+            {
+                Explode();
+            }
+        }
+
+        private void Explode()
+        {
+            if (_crate.Deleted)
+            {
+                return;
+            }
+
+            var hit = new List<RaceData>();
+
+            foreach (var m in _crate.Map.GetMobilesInRange(_crate.Location, 3))
+            {
+                if (CrateRace.PartData.TryGetValue(m, out var rd))
+                {
+                    hit.Add(rd);
+                }
+            }
+
+            foreach (var rd in hit)
+            {
+                rd.Part.SendMessage("You have been hit by a dropbomb!");
+                rd.Part.FixedParticles(0x36BD, 20, 10, 5044, EffectLayer.Head);
+                rd.Part.PlaySound(0x307);
+                CrateRace.HandleDamage(rd, .30);
+            }
+
+            _crate.Delete();
+        }
+    }
