+    // A bomb thrown ahead of the racer; it travels up to thirty tiles and hurts the first racer in its path.
+    public static class FlyingBomb
+    {
+        public static void Launch(Mobile from)
+        {
+            var (dx, dy) = (from.Direction & Direction.Mask) switch
+            {
+                Direction.North => (0, -1),
+                Direction.Right => (1, -1),
+                Direction.East  => (1, 0),
+                Direction.Down  => (1, 1),
+                Direction.South => (0, 1),
+                Direction.Left  => (-1, 1),
+                Direction.West  => (-1, 0),
+                _               => (-1, -1)
+            };
+
+            var map = from.Map;
+            var point = from.Location;
+            var target = new Entity(Serial.Zero, new Point3D(point.X + dx * 30, point.Y + dy * 30, point.Z), map);
+            Effects.SendMovingEffect(from, target, 10249, 7, 10, true, false);
+
+            var steps = 0;
+            Timer timer = null;
+            timer = Timer.DelayCall(TimeSpan.FromSeconds(0.1), TimeSpan.FromSeconds(0.1), 30, () =>
+            {
+                steps++;
+                var at = new Point3D(point.X + dx * steps, point.Y + dy * steps, point.Z);
+
+                foreach (var m in map.GetMobilesInRange(at, 0))
+                {
+                    if (m != from && CrateRace.PartData.TryGetValue(m, out var rd))
+                    {
+                        m.FixedParticles(0x36BD, 20, 10, 5044, EffectLayer.Head);
+                        m.PlaySound(0x307);
+                        Timer.DelayCall(() => CrateRace.HandleDamage(rd, .20));
+                        timer?.Stop();
+                        return;
+                    }
+                }
+            });
+        }
+    }
+
+    [SerializationGenerator(0)]
+    public partial class RaceCrate : Item
+    {
+        // Must add up to 1.
+        private static readonly (double Chance, CrateType Type)[] _types =
+        [
+            (0.125, new TempMirrorCrateType()), (0.075, new MirrorCrateType()), (0.20, new ExplosionCrateType()),
+            (0.05, new FreezeCrateType()), (0.10, new EarthQuakeCrateType()), (0.075, new EnergyBoltCrateType()),
+            (0.05, new ChainLightningCrateType()), (0.075, new HealingCrateType()), (0.15, new MovingBombCrateType()),
+            (0.10, new SlickCrateType())
+        ];
+
+        private static readonly CrateType _damaged = new DamagedCrateType();
+
+        public RaceCrate() : base(3645)
+        {
+            Movable = false;
+
+            var roll = Utility.RandomDouble();
+            var cumulative = 0.0;
+
+            foreach (var (chance, type) in _types)
+            {
+                cumulative += chance;
+
+                if (roll <= cumulative)
+                {
+                    Type = type;
+                    break;
+                }
+            }
+
+            Type ??= _types[^1].Type;
+            Hue = Type.Hue;
+
+            // One crate in twenty is a trap that looks like any other.
+            if (Utility.RandomDouble() < 0.05 && Type is not HealingCrateType)
+            {
+                Type = _damaged;
+            }
+        }
+
+        public CrateType Type { get; set; }
+
+        public override string DefaultName => "Special Race Crate";
+        public override bool HandlesOnMovement => true;
+
+        public override void OnMovement(Mobile m, Point3D oldLocation)
+        {
+            if (Utility.InRange(m.Location, Location, 1) && CrateRace.PartData.TryGetValue(m, out var rd))
+            {
+                Type.OnMoveOver(m);
+
+                if (Type is not SingleUseCrateType)
+                {
+                    rd.Store(Type);
+                }
+
+                if (Type is not DropBombType bomb || m != bomb.Owner)
+                {
+                    Delete();
+                }
+            }
+
+            base.OnMovement(m, oldLocation);
+        }
+
+        public override void OnDelete()
+        {
+            CrateRace.CrateList.Remove(this);
+            base.OnDelete();
+        }
+
+        [AfterDeserialization]
+        private void AfterDeserialization() => Timer.DelayCall(Delete);
+    }
+
+    [SerializationGenerator(0)]
+    public partial class CrateApple : Item
+    {
+        private readonly bool _health;
+
+        public CrateApple() : base(2512)
+        {
+            Movable = false;
+            Hue = 68;
+
+            if (Utility.RandomDouble() < .20)
+            {
+                Hue = 53;
+                _health = true;
+            }
+        }
+
+        public override string DefaultName => "Stamina apple";
+
+        public override bool OnMoveOver(Mobile m)
+        {
+            if (_health)
+            {
+                m.Hits += m.HitsMax / 10;
+            }
+            else
+            {
+                m.Stam += m.StamMax / 10;
+            }
+
+            Delete();
+            return true;
+        }
+
+        public override void OnDelete()
+        {
+            CrateRace.AppleList.Remove(this);
+            base.OnDelete();
+        }
+
+        [AfterDeserialization]
+        private void AfterDeserialization() => Timer.DelayCall(Delete);
+    }
+
+    [SerializationGenerator(0)]
+    public partial class SlickPatch : Item
+    {
+        public SlickPatch() : base(0x914)
+        {
+            Movable = false;
+            Hue = 1736;
+            Timer.DelayCall(TimeSpan.FromSeconds(10.0), Delete);
+        }
+
+        public override bool OnMoveOver(Mobile m)
+        {
+            if (CrateRace.PartData.TryGetValue(m, out var rd))
+            {
+                rd.Frozen = true;
+                CrateRace.SetPlayerSpeed(rd);
+                m.SendMessage("Your movement has slowed down as you have stepped into a slick patch");
+                Timer.DelayCall(TimeSpan.FromSeconds(6), () =>
+                {
+                    if (CrateRace.Running)
+                    {
+                        rd.Frozen = false;
+                        CrateRace.SetPlayerSpeed(rd);
+                    }
+                });
+                Delete();
+            }
+
+            return true;
+        }
+
+        [AfterDeserialization]
+        private void AfterDeserialization() => Timer.DelayCall(Delete);
+    }
+
+    // A chequered tile racers cross eastwards to finish a lap.
+    [SerializationGenerator(0)]
+    public partial class RaceFinishLine : Item
+    {
+        private static bool _white;
+
+        [SerializableField(0)]
+        private Static _companion;
+
+        [Constructible(AccessLevel.GameMaster)]
+        public RaceFinishLine() : base(0x709)
+        {
+            _white = !_white;
+            Hue = _white ? 1153 : 2333;
+            Movable = false;
+            CrateRace.FinishLines.Add(this);
+            Timer.DelayCall(AddCompanion);
+        }
+
+        public override bool HandlesOnMovement => true;
+
+        private void AddCompanion()
+        {
+            if (Deleted || Map == null || Map == Map.Internal)
+            {
+                return;
+            }
+
+            Companion = new Static(0x70D) { Hue = Hue == 1153 ? 2333 : 1153 };
+            _companion.MoveToWorld(new Point3D(X - 1, Y, Z), Map);
+        }
+
+        public override void OnMovement(Mobile m, Point3D oldLocation)
+        {
+            if (CrateRace.Running && oldLocation.X == X && oldLocation.Y == Y && m.X == X + 1)
+            {
+                CrateRace.MobFinish(m);
+            }
+        }
+
+        [AfterDeserialization]
+        private void AfterDeserialization() => CrateRace.FinishLines.Add(this);
+
+        public override void OnAfterDelete()
+        {
+            CrateRace.FinishLines.Remove(this);
+            _companion?.Delete();
+            base.OnAfterDelete();
+        }
+    }
+
+    // DFI's race track, built from the data DFI kept for it.
+    [SerializationGenerator(0)]
+    public partial class RaceTrackAddon : BaseAddon
+    {
+        [Constructible(AccessLevel.GameMaster)]
+        public RaceTrackAddon()
+        {
+            var t = RaceTrackData.Tiles;
+
+            for (var i = 0; i + 3 < t.Length; i += 4)
+            {
+                AddComponent(new AddonComponent(t[i]), t[i + 1], t[i + 2], t[i + 3]);
+            }
+        }
+    }
+
+    // The race's control stone, hidden from players.
+    [SerializationGenerator(0)]
+    public partial class CrateStone : Item
+    {
+        [SerializableField(0)]
+        [SerializedCommandProperty(AccessLevel.GameMaster)]
+        private bool _quickSpeed;
+
+        [SerializableField(1)]
+        [SerializedCommandProperty(AccessLevel.GameMaster)]
+        private int _laps = 3;
+
+        [SerializableField(2)]
+        [SerializedCommandProperty(AccessLevel.GameMaster)]
+        private int _price = 5000;
+
+        [SerializableField(3, setter: "private")]
+        private int _maxCrates = 50;
+
+        [SerializableField(4)]
+        [SerializedCommandProperty(AccessLevel.GameMaster)]
+        private int _minutesOpen = 5;
+
+        [SerializableField(5)]
+        [SerializedCommandProperty(AccessLevel.GameMaster)]
+        private bool _animalised;
+
+        [SerializableField(6)]
+        [SerializedCommandProperty(AccessLevel.GameMaster)]
+        private bool _rewards = true;
+
+        [SerializableField(7)]
+        [SerializedCommandProperty(AccessLevel.GameMaster)]
+        private Rectangle2D _regionRect;
+
+        [SerializableField(8, getter: "private", setter: "private")]
+        private List<Rectangle2D> _rects = [];
+
+        [SerializableField(9, getter: "private", setter: "private")]
+        private List<int> _directions = [];
+
+        [SerializableField(10)]
+        [SerializedCommandProperty(AccessLevel.GameMaster)]
+        private Item _track;
+
+        [Constructible(AccessLevel.Administrator)]
+        public CrateStone() : base(3796)
+        {
+            Hue = 1122;
+            Movable = false;
+            Visible = false;
+        }
+
+        public override string DefaultName => "Crate Race Stone";
+
+        [CommandProperty(AccessLevel.GameMaster)]
+        public int MaxCratesOnTrack
+        {
+            get => _maxCrates;
+            set => MaxCrates = Math.Clamp(value, 0, 200);
+        }
+
+        [CommandProperty(AccessLevel.GameMaster)]
+        public bool Running
+        {
+            get => EventSystem.Running;
+            set
+            {
+                if (value == EventSystem.Running)
+                {
+                    return;
+                }
+
+                if (value)
+                {
+                    CrateRace.Start(this);
+                }
+                else
+                {
+                    EventSystem.Stop();
+                }
+            }
+        }
+
+        // The track's rectangles in racing order; each keeps the two directions a racer leaves it by.
+        public List<CrateRectangle> Rectangles
+        {
+            get
+            {
+                var list = new List<CrateRectangle>();
+
+                for (var i = 0; i < _rects.Count; i++)
+                {
+                    var dirs = i < _directions.Count ? _directions[i] : 0;
+                    list.Add(new CrateRectangle(_rects[i], (Direction)(dirs & 0xFF), (Direction)(dirs >> 8)));
+                }
+
+                return list;
+            }
+            set
+            {
+                Rects = value.ConvertAll(r => r.Rectangle);
+                Directions = value.ConvertAll(r => (int)r.FirstDirection | (int)r.SecondDirection << 8);
+            }
+        }
+
+        public void BuildTrack()
+        {
+            if (_track?.Deleted == false)
+            {
+                return;
+            }
+
+            var track = new RaceTrackAddon();
+            track.MoveToWorld(Location, Map);
+            Track = track;
+
+            if (_regionRect.Width == 0)
+            {
+                RegionRect = new Rectangle2D(X - 22, Y - 32, 45, 65);
+            }
+
+            if (_rects.Count == 0)
+            {
+                SetDefaultLayout();
+            }
+        }
+
+        // DFI's track: a ten-wide lane between walls at 21/31 and 11/21 tiles from the stone, raced clockwise
+        // from the top straight, where the start grid and the finish line are.
+        public void SetDefaultLayout()
+        {
+            Rectangles =
+            [
+                new CrateRectangle(new Rectangle2D(X - 20, Y - 30, 41, 9), Direction.East, Direction.South),
+                new CrateRectangle(new Rectangle2D(X + 12, Y - 21, 9, 52), Direction.South, Direction.West),
+                new CrateRectangle(new Rectangle2D(X - 20, Y + 22, 32, 9), Direction.West, Direction.North),
+                new CrateRectangle(new Rectangle2D(X - 20, Y - 21, 9, 43), Direction.North, Direction.East)
+            ];
+
+            foreach (var line in CrateRace.FinishLines.ToArray())
+            {
+                if (line.Map == Map && Utility.InRange(line.Location, Location, 40))
+                {
+                    line.Delete();
+                }
+            }
+
+            for (var y = Y - 30; y <= Y - 22; y++)
+            {
+                new RaceFinishLine().MoveToWorld(new Point3D(X, y, Z), Map);
+            }
+        }
+
+        public void DemolishTrack()
+        {
+            _track?.Delete();
+            Track = null;
+        }
+
+        public override void OnDoubleClick(Mobile from)
+        {
+            if (from.AccessLevel > AccessLevel.Counselor)
+            {
+                from.SendGump(new CrateStoneGump(this), true);
+            }
+        }
+
+        public override void OnAfterDelete()
+        {
+            _track?.Delete();
+            base.OnAfterDelete();
+        }
+    }
+}
diff --git a/Projects/UOContent/Custom/DFI/Games/CrateRaceGumps.cs b/Projects/UOContent/Custom/DFI/Games/CrateRaceGumps.cs
