+// The crate race's gumps, ported from DFI RUNUO Scripts/Custom/Engines/Crate Race (CrateRaceGumps.cs, ModGumps.cs):
+// joining, the racer's status, the rankings, and the stone's control centre with its track-rectangle editor.
+// DFI let each racer place their status gump anywhere on screen; here it sits at DFI's default spot.
+
+using System;
+using System.Collections.Generic;
+using Server.Commands;
+using Server.Gumps;
+using Server.Items;
+using Server.Mobiles;
+using Server.Network;
+
+namespace Server.Custom.Dfi.CrateRace
+{
+    public class CrateJoinGump : DynamicGump
+    {
+        public CrateJoinGump() : base(30, 30)
+        {
+        }
+
+        public override bool Singleton => true;
+
+        protected override void BuildLayout(ref DynamicGumpBuilder builder)
+        {
+            builder.AddPage();
+            builder.AddBackground(0, 0, 500, 280, 9200);
+            builder.AddLabel(196, 15, 0, "Crate Race Gump");
+            builder.AddHtml(
+                30, 50, 440, 170,
+                $"Welcome,<br><br>You are about to join a crate race event. It will cost you {Math.Max(0, CrateRace.Price)}gp to join. Your belongings will be kept safe in your bank while you race and returned to you afterwards.<br><br>Run over crates to collect them, and say \"use first crate\", \"use second crate\" or \"use third crate\" to use them. Apples restore your stamina. The first three across the finish line share the entry money.",
+                background: true, scrollbar: true
+            );
+            builder.AddButton(290, 230, 247, 248, 1);
+            builder.AddButton(150, 230, 242, 241, 0);
+        }
+
+        public override void OnResponse(NetState sender, in RelayInfo info)
+        {
+            if (info.ButtonID == 1 && sender.Mobile is PlayerMobile pm)
+            {
+                pm.SendMessage(CrateRace.Join(pm) ?? "You have entered the race!");
+            }
+        }
+    }
+
+    public class CrateRaceCharGump : DynamicGump
+    {
+        private static readonly (int GumpItem, int Body)[] _characters =
+        [
+            (8401, 0xD0), (8423, 50), (8426, 0xE1), (8473, 0xD6), (8437, 0x1D), (8416, 0x11), (8424, 0x33), (8417, 0xD5)
+        ];
+
+        public CrateRaceCharGump() : base(0, 0)
+        {
+        }
+
+        public override bool Singleton => true;
+
+        protected override void BuildLayout(ref DynamicGumpBuilder builder)
+        {
+            builder.AddPage();
+            builder.AddBackground(130, 130, 300, 300, 9200);
+            builder.AddLabel(166, 146, 0, "Choose your character");
+
+            for (var i = 0; i < _characters.Length; i++)
+            {
+                var x = i < 4 ? 160 : 300;
+                var y = 200 + i % 4 * 50;
+                builder.AddRadio(x, y, 210, 211, false, i);
+                builder.AddItem(x + 30, y, _characters[i].GumpItem);
+            }
+
+            builder.AddButton(190, 385, 241, 242, 0);
+            builder.AddButton(320, 385, 247, 248, 1);
+        }
+
+        public override void OnResponse(NetState sender, in RelayInfo info)
+        {
+            if (info.ButtonID != 1)
+            {
+                return;
+            }
+
+            for (var i = 0; i < _characters.Length; i++)
+            {
+                if (info.IsSwitched(i))
+                {
+                    sender.Mobile.BodyMod = _characters[i].Body;
+                    return;
+                }
+            }
+        }
+    }
+
+    public class CrateRaceGump : DynamicGump
+    {
+        private readonly RaceData _rd;
+
+        public CrateRaceGump(RaceData rd) : base(100, 450) => _rd = rd;
+
+        public override bool Singleton => true;
+
+        protected override void BuildLayout(ref DynamicGumpBuilder builder)
+        {
+            builder.SetNoClose();
+            builder.SetNoMove();
+            builder.AddPage();
+            builder.AddBackground(50, 15, 500, 260, 5054);
+            builder.AddImage(143, 22, 2440, 2105);
+            builder.AddLabel(173, 23, 1152, "Crate Race Gump");
+
+            AddCrate(ref builder, _rd.Crate1, 1, 55);
+            AddCrate(ref builder, _rd.Crate2, 2, 125);
+            AddCrate(ref builder, _rd.Crate3, 3, 195);
+
+            if (_rd.TempMirror)
+            {
+                builder.AddImage(355, 55, 2275);
+            }
+
+            if (_rd.Mirror)
+            {
+                builder.AddImage(425, 55, 2265);
+            }
+
+            var hits = 100 * _rd.Part.Hits / Math.Max(1, _rd.Part.HitsMax);
+            var hitsHue = hits < 30 ? 38 : hits < 50 ? 55 : 73;
+
+            builder.AddLabel(155, 130, hitsHue, "Health:");
+            builder.AddLabel(235, 130, hitsHue, $"{hits}%");
+            builder.AddLabel(155, 150, 1152, "Lap:");
+            builder.AddLabel(235, 150, 1152, $"{_rd.Lap}");
+            builder.AddLabel(155, 170, 1152, "Laps to go:");
+            builder.AddLabel(235, 170, 1152, $"{CrateRace.Laps - _rd.Lap}");
+            builder.AddLabel(155, 190, 1152, "Rank:");
+            builder.AddLabel(235, 190, 1152, $"{_rd.Place}");
+            builder.AddLabel(295, 150, 1152, "Crates:");
+            builder.AddLabel(375, 150, 1152, $"{CrateRace.Crates}");
+            builder.AddLabel(295, 170, 1152, "Opponents:");
+            builder.AddLabel(375, 170, 1152, $"{CrateRace.Participants - 1}");
+            builder.AddLabel(295, 190, 1152, "First Place:");
+            builder.AddLabel(375, 190, 1152, CrateRace.FirstPlace?.Name ?? "Noone");
+        }
+
+        private static void AddCrate(ref DynamicGumpBuilder builder, CrateType crate, int slot, int y)
+        {
+            if (crate != null)
+            {
+                builder.AddButton(85, y, crate.GumpID, crate.GumpID, slot);
+            }
+        }
+
+        public override void OnResponse(NetState sender, in RelayInfo info)
+        {
+            if (info.ButtonID is >= 1 and <= 3 && CrateRace.Running && CrateRace.PartData.TryGetValue(sender.Mobile, out var rd))
+            {
+                rd.Use(info.ButtonID);
+            }
+        }
+    }
+
+    public class RaceRankGump : DynamicGump
+    {
+        private readonly List<FinishedData> _list;
+        private readonly int _page;
+
+        public RaceRankGump(List<FinishedData> list, int page) : base(50, 50)
+        {
+            _list = list;
+            _page = Math.Clamp(page, 0, Math.Max(0, (list.Count - 1) / 10));
+        }
+
+        public override bool Singleton => true;
+
+        protected override void BuildLayout(ref DynamicGumpBuilder builder)
+        {
+            var pages = Math.Max(1, (_list.Count + 9) / 10);
+
+            builder.AddPage();
+            builder.AddBackground(130, 100, 340, 340, 9200);
+            builder.AddHtml(130, 118, 340, 23, "Crate Race Rankings", align: TextAlignment.Center);
+            builder.AddLabel(170, 150, 0, "Place:");
+            builder.AddLabel(210, 150, 0, "Name:");
+            builder.AddLabel(360, 150, 0, "Time:");
+
+            for (var i = _page * 10; i < Math.Min(_list.Count, _page * 10 + 10); i++)
+            {
+                var fd = _list[i];
+                var y = 170 + (i - _page * 10) * 20;
+                builder.AddLabel(170, y, 0, $"{fd.Place}");
+                builder.AddLabel(210, y, 0, fd.Racer?.Name ?? "Anonymous");
+                builder.AddLabel(360, y, 0, $"{(int)fd.Time.TotalMinutes}:{fd.Time.Seconds:00}");
+            }
+
+            builder.AddHtml(130, 400, 340, 20, $"{_page + 1}/{pages}", align: TextAlignment.Center);
+            builder.AddButton(169, 400, 9772, 9770, 1);
+            builder.AddButton(408, 400, 9773, 9771, 2);
+        }
+
+        public override void OnResponse(NetState sender, in RelayInfo info)
+        {
+            if (info.ButtonID is 1 or 2)
+            {
+                sender.Mobile.SendGump(new RaceRankGump(_list, _page + (info.ButtonID == 1 ? -1 : 1)), true);
+            }
+        }
+    }
+
+    public class CrateStoneGump : DynamicGump
+    {
+        private const int Build = 1;
+        private const int Demolish = 2;
+        private const int Settings = 3;
+        private const int NewRects = 4;
+        private const int EditRects = 5;
+        private const int Start = 6;
+        private const int Stop = 7;
+        private const int SetRegion = 8;
+
+        private readonly CrateStone _stone;
+
+        public CrateStoneGump(CrateStone stone) : base(100, 100) => _stone = stone;
+
+        public override bool Singleton => true;
+
+        protected override void BuildLayout(ref DynamicGumpBuilder builder)
+        {
+            builder.AddPage();
+            builder.AddBackground(0, 0, 420, 330, 9270);
+            builder.AddAlphaRegion(10, 10, 400, 310);
+            builder.AddLabel(130, 20, 0x480, "Crate Race Control Center");
+
+            builder.AddLabel(30, 55, 0x34, $"Running: {_stone.Running}   Racers: {CrateRace.Participants}   Crates: {CrateRace.Crates}");
+            builder.AddLabel(30, 75, 0x34, $"Rectangles: {_stone.Rectangles.Count}   Finish lines: {CrateRace.FinishLines.Count}   Track: {(_stone.Track?.Deleted == false ? "built" : "none")}");
+
+            AddRow(ref builder, 0, Build, "Build RaceTrack");
+            AddRow(ref builder, 1, Demolish, "Demolish RaceTrack");
+            AddRow(ref builder, 2, Settings, "Change Settings (laps, price, crates...)");
+            AddRow(ref builder, 3, NewRects, "Set New Track Rectangles");
+            AddRow(ref builder, 4, EditRects, "Edit Track Rectangles");
+            AddRow(ref builder, 5, SetRegion, "Set the race region");
+            AddRow(ref builder, 6, _stone.Running ? Stop : Start, _stone.Running ? "Stop the race" : "Start the race");
+        }
+
+        private static void AddRow(ref DynamicGumpBuilder builder, int row, int button, string text)
+        {
+            builder.AddButton(30, 110 + row * 28, 4005, 4006, button);
+            builder.AddLabel(65, 110 + row * 28, 0x480, text);
+        }
+
+        public override void OnResponse(NetState sender, in RelayInfo info)
+        {
+            var from = sender.Mobile;
+
+            if (from.AccessLevel < AccessLevel.GameMaster || _stone.Deleted)
+            {
+                return;
+            }
+
+            switch (info.ButtonID)
+            {
+                case Build:
+                    {
+                        _stone.BuildTrack();
+                        break;
+                    }
+                case Demolish:
+                    {
+                        _stone.DemolishTrack();
+                        break;
+                    }
+                case Settings:
+                    {
+                        from.SendGump(new PropertiesGump(from, _stone));
+                        return;
+                    }
+                case NewRects:
+                    {
+                        new RectangleSetup(from, _stone, []).Pick(0);
+                        return;
+                    }
+                case EditRects:
+                    {
+                        new RectangleSetup(from, _stone, _stone.Rectangles).Show(0);
+                        return;
+                    }
+                case SetRegion:
+                    {
+                        from.SendMessage("Target the corners of the race region.");
+                        BoundingBoxPicker.Begin(from, (map, start, end) =>
+                        {
+                            _stone.RegionRect = new Rectangle2D(new Point2D(start.X, start.Y), new Point2D(end.X + 1, end.Y + 1));
+                            from.SendGump(new CrateStoneGump(_stone), true);
+                        });
+                        return;
+                    }
+                case Start:
+                    {
+                        _stone.Running = true;
+                        break;
+                    }
+                case Stop:
+                    {
+                        _stone.Running = false;
+                        break;
+                    }
+                default:
+                    {
+                        return;
+                    }
+            }
+
+            from.SendGump(new CrateStoneGump(_stone), true);
+        }
+    }
+
+    // Draws the track's rectangles one at a time, in racing order, with the two directions a racer leaves each by.
+    public class RectangleSetup
+    {
+        private readonly Mobile _from;
+        private readonly CrateStone _stone;
+        private readonly List<Item> _markers = [];
+
+        public RectangleSetup(Mobile from, CrateStone stone, List<CrateRectangle> list)
+        {
+            _from = from;
+            _stone = stone;
+            List = list;
+        }
+
+        public List<CrateRectangle> List { get; }
+
+        public void Pick(int index)
+        {
+            _from.SendMessage("Target the corners of the track rectangle.");
+            BoundingBoxPicker.Begin(_from, (map, start, end) =>
+            {
+                var rect = new CrateRectangle(new Rectangle2D(new Point2D(start.X, start.Y), new Point2D(end.X + 1, end.Y + 1)));
+
+                if (index < List.Count)
+                {
+                    List[index] = rect;
+                }
+                else
+                {
+                    List.Add(rect);
+                    index = List.Count - 1;
+                }
+
+                Show(index);
+            });
+        }
+
+        public void Show(int index)
+        {
+            ClearMarkers();
+
+            if (List.Count > 0)
+            {
+                Mark(List[0].Rectangle, 1150);
+
+                if (index < List.Count && index > 0)
+                {
+                    Mark(List[index].Rectangle, 1151);
+                }
+            }
+
+            _from.SendGump(new TrackRectangleGump(this, index), true);
+        }
+
+        public void Save()
+        {
+            ClearMarkers();
+            _stone.Rectangles = List;
+            _from.SendMessage($"The track now has {List.Count} rectangles.");
+        }
+
+        public void ClearMarkers()
+        {
+            foreach (var item in _markers)
+            {
+                item.Delete();
+            }
+
+            _markers.Clear();
+        }
+
+        private void Mark(Rectangle2D rect, int hue)
+        {
+            var map = _stone.Map;
+
+            for (var x = rect.Start.X; x < rect.End.X; x++)
+            {
+                for (var y = rect.Start.Y; y < rect.End.Y; y++)
+                {
+                    var marker = new Static(0x1822) { Hue = hue, Name = "track marker" };
+                    marker.MoveToWorld(new Point3D(x, y, map.Tiles.GetLandTile(x, y).Z), map);
+                    _markers.Add(marker);
+                }
+            }
+        }
+    }
+
+    public class TrackRectangleGump : DynamicGump
+    {
+        private const int AddRect = 1;
+        private const int Finish = 2;
+        private const int Remove = 3;
+        private const int Redo = 4;
+        private const int Previous = 5;
+        private const int Next = 6;
+        private const int FirstBase = 10;
+        private const int SecondBase = 20;
+
+        private static readonly Direction[] _dirs = [Direction.North, Direction.East, Direction.South, Direction.West];
+
+        private readonly RectangleSetup _setup;
+        private readonly int _index;
+
+        public TrackRectangleGump(RectangleSetup setup, int index) : base(50, 50)
+        {
+            _setup = setup;
+            _index = index;
+        }
+
+        public override bool Singleton => true;
+
+        protected override void BuildLayout(ref DynamicGumpBuilder builder)
+        {
+            builder.AddPage();
+            builder.AddBackground(0, 0, 420, 330, 9270);
+            builder.AddAlphaRegion(10, 10, 400, 310);
+            builder.AddLabel(150, 20, 1152, "Track Rectangles");
+            builder.AddLabel(30, 50, 1152, $"Rectangle {_index + 1} of {_setup.List.Count} (the first is blue-white)");
+
+            if (_index < _setup.List.Count)
+            {
+                var r = _setup.List[_index];
+                builder.AddLabel(30, 75, 1152, $"{r.Rectangle}");
+                builder.AddLabel(30, 105, 1152, "First direction:");
+                builder.AddLabel(30, 165, 1152, "Second direction:");
+
+                for (var i = 0; i < _dirs.Length; i++)
+                {
+                    builder.AddButton(30 + i * 90, 130, r.FirstDirection == _dirs[i] ? 4006 : 4005, 4006, FirstBase + i);
+                    builder.AddLabel(65 + i * 90, 130, 1152, $"{_dirs[i]}");
+                    builder.AddButton(30 + i * 90, 190, r.SecondDirection == _dirs[i] ? 4006 : 4005, 4006, SecondBase + i);
+                    builder.AddLabel(65 + i * 90, 190, 1152, $"{_dirs[i]}");
+                }
+
+                builder.AddButton(30, 225, 4017, 4018, Remove);
+                builder.AddLabel(65, 225, 1152, "Remove this rectangle");
+                builder.AddButton(230, 225, 4011, 4012, Redo);
+                builder.AddLabel(265, 225, 1152, "Retarget it");
+            }
+
+            builder.AddButton(30, 260, 4014, 4015, Previous);
+            builder.AddButton(70, 260, 4005, 4006, Next);
+            builder.AddLabel(110, 260, 1152, "Previous / next");
+            builder.AddButton(30, 290, 4005, 4006, AddRect);
+            builder.AddLabel(65, 290, 1152, "Add Rectangle");
+            builder.AddButton(230, 290, 4023, 4024, Finish);
+            builder.AddLabel(265, 290, 1152, "Finish");
+        }
+
+        public override void OnResponse(NetState sender, in RelayInfo info)
+        {
+            var id = info.ButtonID;
+
+            switch (id)
+            {
+                case 0:
+                    {
+                        _setup.ClearMarkers();
+                        return;
+                    }
+                case AddRect:
+                    {
+                        _setup.Pick(_setup.List.Count);
+                        return;
+                    }
+                case Finish:
+                    {
+                        _setup.Save();
+                        return;
+                    }
+                case Remove when _index < _setup.List.Count:
+                    {
+                        _setup.List.RemoveAt(_index);
+                        _setup.Show(Math.Max(0, _index - 1));
+                        return;
+                    }
+                case Redo:
+                    {
+                        _setup.Pick(_index);
+                        return;
+                    }
+                case Previous:
+                    {
+                        _setup.Show(Math.Max(0, _index - 1));
+                        return;
+                    }
+                case Next:
+                    {
+                        _setup.Show(Math.Min(_setup.List.Count, _index + 1));
+                        return;
+                    }
+                case >= SecondBase and < SecondBase + 4 when _index < _setup.List.Count:
+                    {
+                        _setup.List[_index].SecondDirection = _dirs[id - SecondBase];
+                        break;
+                    }
+                case >= FirstBase and < FirstBase + 4 when _index < _setup.List.Count:
+                    {
+                        _setup.List[_index].FirstDirection = _dirs[id - FirstBase];
+                        break;
+                    }
+            }
+
+            _setup.Show(_index);
+        }
+    }
+}
diff --git a/Projects/UOContent/Custom/DFI/Games/DfiCrateRaceGen.cs b/Projects/UOContent/Custom/DFI/Games/DfiCrateRaceGen.cs
new file mode 100644
index 000000000..81104fdf1
--- /dev/null
+++ b/Projects/UOContent/Custom/DFI/Games/DfiCrateRaceGen.cs
@@ -0,0 +1,64 @@
+// Places the crate race's event masters by the banks of Britain and Buccaneer's Den, where DFI's announcements
+// sent players. With "here", also a crate stone at the caller's feet with DFI's track built round it and its
+// default layout: the track needs a flat, empty 45 by 65 tiles.
+
+using System.Collections.Generic;
+using Server.Commands;
+using Server.Custom.Dfi.CrateRace;
+using Server.Custom.Dfi.Events;
+using Server.Logging;
+
+namespace Server.Custom.Dfi;
+
+public static class DfiCrateRaceGen
+{
+    private static readonly ILogger logger = LogFactory.GetLogger(typeof(DfiCrateRaceGen));
+
+    public static readonly Point3D[] EventMasterSpots = [new(1427, 1695, 0), new(2731, 2187, 0)];
+
+    public static void Configure()
+    {
+        CommandSystem.Register("DfiCrateRace", AccessLevel.Administrator, OnCommand);
+    }
+
+    [Usage("DfiCrateRace [here]")]
+    [Description("Places the event masters; with \"here\", also a crate stone and DFI's race track at your feet.")]
+    private static void OnCommand(CommandEventArgs e)
+    {
+        var removed = 0;
+        var doomed = new List<Mobile>();
+
+        foreach (var m in World.Mobiles.Values)
+        {
+            if (m is EventNpc && m.Map == Map.Felucca && System.Array.IndexOf(EventMasterSpots, m.Location) >= 0)
+            {
+                doomed.Add(m);
+            }
+        }
+
+        foreach (var m in doomed)
+        {
+            m.Delete();
+            removed++;
+        }
+
+        foreach (var spot in EventMasterSpots)
+        {
+            var npc = new EventNpc { Home = spot, RangeHome = 0, CantWalk = true, Direction = Direction.South };
+            npc.MoveToWorld(spot, Map.Felucca);
+        }
+
+        var placed = EventMasterSpots.Length;
+
+        if (e.Length > 0 && e.GetString(0).Equals("here", System.StringComparison.OrdinalIgnoreCase))
+        {
+            var stone = new CrateStone();
+            stone.MoveToWorld(e.Mobile.Location, e.Mobile.Map);
+            stone.BuildTrack();
+            placed++;
+        }
+
+        e.Mobile.SendMessage($"DfiCrateRace: removed {removed}, placed {placed}.");
+        logger.Information("{User} placed {Placed} crate race fixtures ({Removed} removed)", e.Mobile, placed, removed);
+    }
+}
diff --git a/Projects/UOContent/Custom/DFI/Games/EventSystem.cs b/Projects/UOContent/Custom/DFI/Games/EventSystem.cs
new file mode 100644
index 000000000..32f33c8af
--- /dev/null
+++ b/Projects/UOContent/Custom/DFI/Games/EventSystem.cs
@@ -0,0 +1,385 @@
+// DFI Network's event signup, ported from DFI RUNUO Scripts/Custom/Sunny/EventSystem and the undress code in
+// Custom/Sunny/SunnySystem.cs. One staff event at a time: once started it is announced every minute for its
+// join time, while event masters take players in; then it begins. Players are undressed into a bag in their
+// bank when they join and dressed again afterwards, their pets stabled meanwhile. When an event ends its
+// players are set down at one of Britain's edges, blessed for twenty seconds.
+
+using System;
+using System.Collections.Generic;
+using ModernUO.Serialization;
+using Server.Collections;
+using Server.Commands;
+using Server.ContextMenus;
+using Server.Items;
+using Server.Mobiles;
+
+namespace Server.Custom.Dfi.Events;
+
+public static class EventSystem
+{
+    public const int SystemHue = 0x38A;
+
+    private static readonly Point3D[] _exitLocations =
+        [new(1522, 1757, 28), new(1519, 1619, 10), new(1457, 1538, 30), new(1607, 1568, 20), new(1643, 1680, 18)];
+
+    private static Timer _joinTimer;
+    private static Action _start;
+    private static Action _stop;
+
+    public static bool Open { get; private set; }
+    public static bool Running { get; private set; }
+    public static string EventName { get; private set; }
+    public static Action<Mobile> JoinMethod { get; private set; }
+    public static List<EventNpc> Npcs { get; } = [];
+
+    public static void Start(int joinMinutes, string name, Action start, Action stop, Action<Mobile> join)
+    {
+        Open = true;
+        Running = true;
+        EventName = name;
+        _start = start;
+        _stop = stop;
+        JoinMethod = join;
+
+        var broadcasts = Math.Max(2, joinMinutes);
+        _joinTimer?.Stop();
+        _joinTimer = Timer.DelayCall(TimeSpan.Zero, TimeSpan.FromMinutes(1.0), () => Announce(ref broadcasts));
+    }
+
+    private static void Announce(ref int broadcasts)
+    {
+        var name = EventName;
+
+        if (broadcasts == 0)
+        {
+            CommandHandlers.BroadcastMessage(AccessLevel.Player, SystemHue, $"---- {name} ----");
+            CommandHandlers.BroadcastMessage(AccessLevel.Player, SystemHue, $"The {name} is starting... Event Masters do not accept new players.");
+            StartGame();
+            return;
+        }
+
+        foreach (var npc in Npcs)
+        {
+            npc.Say("Hear Ye! Hear Ye!");
+            npc.Say(broadcasts == 1 ? $"Last call for the {name}!" : $"Hurry up and join the {name}!");
+        }
+
+        CommandHandlers.BroadcastMessage(AccessLevel.Player, SystemHue, $"---- {name} ----");
+        CommandHandlers.BroadcastMessage(AccessLevel.Player, SystemHue, $"A {name} will start in {broadcasts} minutes!");
+        CommandHandlers.BroadcastMessage(
+            AccessLevel.Player, SystemHue,
+            broadcasts == 1 ? "Event Masters will not accept new players soon..." : "Event Masters at Britain Bank will now accept new players."
+        );
+
+        broadcasts--;
+    }
+
+    public static void StartGame()
+    {
+        Open = false;
+        _joinTimer?.Stop();
+        _joinTimer = null;
+        _start?.Invoke();
+    }
+
+    public static void Stop()
+    {
+        if (!Open && !Running)
+        {
+            return;
+        }
+
+        Open = false;
+        Running = false;
+        _joinTimer?.Stop();
+        _joinTimer = null;
+        _stop?.Invoke();
+    }
+
+    public static void RemoveToRandomLoc(Mobile m)
+    {
+        m.Blessed = true;
+        Timer.DelayCall(TimeSpan.FromSeconds(20.0), () => m.Blessed = false);
+        m.MoveToWorld(_exitLocations.RandomElement(), Map.Felucca);
+    }
+}
+
+// What a player wore and carried when an event undressed them, held in a bag in their bank.
+public class UndressedPlayer
+{
+    public Bag Bag { get; init; }
+    public List<Item> Worn { get; } = [];
+    public List<Item> Pack { get; } = [];
+    public List<BaseCreature> Pets { get; } = [];
+}
+
+public class EventWardrobe : GenericPersistence
+{
+    private static readonly Dictionary<Mobile, UndressedPlayer> _undressed = [];
+
+    public EventWardrobe() : base("DfiEventWardrobe", 10)
+    {
+    }
+
+    public static void Configure()
+    {
+        _ = new EventWardrobe();
+    }
+
+    public static bool IsUndressed(Mobile m) => _undressed.ContainsKey(m);
+
+    public static bool Undress(Mobile m)
+    {
+        if (!m.Alive)
+        {
+            m.Resurrect();
+            m.Hits = m.HitsMax;
+        }
+
+        if (m.Backpack == null)
+        {
+            m.SendMessage("Unfortunately we could not undress you, as you have no backpack, please contact the staff.");
+            return false;
+        }
+
+        if (_undressed.ContainsKey(m))
+        {
+            return false;
+        }
+
+        var bag = new Bag();
+        m.BankBox.DropItem(bag);
+        var ud = new UndressedPlayer { Bag = bag };
+        _undressed[m] = ud;
+
+        if (m.Holding != null)
+        {
+            m.Backpack.DropItem(m.Holding);
+        }
+
+        StablePets(m, ud);
+
+        foreach (var item in new List<Item>(m.Items))
+        {
+            if (item.Layer is not (Layer.Backpack or Layer.Bank or Layer.FacialHair or Layer.Hair))
+            {
+                ud.Worn.Add(item);
+                bag.DropItem(item);
+            }
+        }
+
+        foreach (var item in new List<Item>(m.Backpack.Items))
+        {
+            ud.Pack.Add(item);
+            bag.DropItem(item);
+        }
+
+        return true;
+    }
+
+    public static bool Redress(Mobile m)
+    {
+        if (!_undressed.Remove(m, out var ud))
+        {
+            m.SendMessage("Unfortunately we could not find your belongings, please contact the staff.");
+            return false;
+        }
+
+        if (!m.Alive)
+        {
+            m.Resurrect();
+        }
+
+        foreach (var item in ud.Worn)
+        {
+            if (item.Deleted)
+            {
+                continue;
+            }
+
+            if (!item.CanEquip(m) || !m.EquipItem(item))
+            {
+                m.AddToBackpack(item);
+            }
+        }
+
+        foreach (var item in ud.Pack)
+        {
+            if (!item.Deleted)
+            {
+                m.AddToBackpack(item);
+            }
+        }
+
+        if (ud.Bag.Items.Count == 0)
+        {
+            ud.Bag.Delete();
+        }
+
+        foreach (var pet in ud.Pets)
+        {
+            if (pet.Deleted)
+            {
+                continue;
+            }
+
+            if (m is PlayerMobile pm)
+            {
+                pm.Stabled.Remove(pet);
+            }
+
+            pet.SetControlMaster(m);
+            pet.ControlTarget = m;
+            pet.ControlOrder = OrderType.Follow;
+            pet.MoveToWorld(m.Location, m.Map);
+            pet.IsStabled = false;
+        }
+
+        m.SendMessage("Your belongings have been returned to you.");
+        return true;
+    }
+
+    private static void StablePets(Mobile m, UndressedPlayer ud)
+    {
+        if (m.Mount != null)
+        {
+            m.Mount.Rider = null;
+        }
+
+        if (m.Followers == 0 || m is not PlayerMobile pm)
+        {
+            return;
+        }
+
+        var pets = new List<BaseCreature>();
+
+        foreach (var near in m.GetMobilesInRange(20))
+        {
+            if (near is BaseCreature bc && (bc.Summoned && bc.SummonMaster == m || bc.Controlled && bc.ControlMaster == m))
+            {
+                pets.Add(bc);
+            }
+        }
+
+        foreach (var pet in pets)
+        {
+            if (pet.Summoned)
+            {
+                pet.Delete();
+                continue;
+            }
+
+            ud.Pets.Add(pet);
+            pet.ControlTarget = null;
+            pet.ControlOrder = OrderType.Stay;
+            pet.Internalize();
+            pet.SetControlMaster(null);
+            pet.SummonMaster = null;
+            pet.IsStabled = true;
+            pm.Stabled.Add(pet);
+        }
+
+        if (pets.Count > 0)
+        {
+            m.SendMessage("Your pets have been stabled.");
+        }
+    }
+
+    public override void Serialize(IGenericWriter writer)
+    {
+        writer.WriteEncodedInt(0); // version
+        writer.WriteEncodedInt(_undressed.Count);
+
+        foreach (var (m, ud) in _undressed)
+        {
+            writer.Write(m);
+            writer.Write(ud.Bag);
+            writer.Write(ud.Worn);
+            writer.Write(ud.Pack);
+            writer.Write(ud.Pets);
+        }
+    }
+
+    public override void Deserialize(IGenericReader reader)
+    {
+        reader.ReadEncodedInt(); // version
+        var count = reader.ReadEncodedInt();
+
+        for (var i = 0; i < count; i++)
+        {
+            var m = reader.ReadEntity<Mobile>();
+            var ud = new UndressedPlayer { Bag = reader.ReadEntity<Bag>() };
+            ud.Worn.AddRange(reader.ReadEntityList<Item>());
+            ud.Pack.AddRange(reader.ReadEntityList<Item>());
+            ud.Pets.AddRange(reader.ReadEntityList<BaseCreature>());
+
+            if (m != null && ud.Bag != null)
+            {
+                _undressed[m] = ud;
+            }
+        }
+    }
+}
+
+// The event master: the way into whichever event is taking players.
+[SerializationGenerator(0)]
+public partial class EventNpc : BaseVendor
+{
+    private readonly List<SBInfo> _sbInfos = [];
+
+    [Constructible(AccessLevel.GameMaster)]
+    public EventNpc() : base("the event master") => EventSystem.Npcs.Add(this);
+
+    protected override List<SBInfo> SBInfos => _sbInfos;
+    public override VendorShoeType ShoeType => VendorShoeType.Sandals;
+
+    public override void InitSBInfo()
+    {
+    }
+
+    public override void InitOutfit()
+    {
+        base.InitOutfit();
+        AddItem(new Robe(Utility.RandomNeutralHue()));
+        AddItem(new WizardsHat(Utility.RandomNeutralHue()));
+        AddItem(new GnarledStaff());
+    }
+
+    [AfterDeserialization]
+    private void AfterDeserialization() => EventSystem.Npcs.Add(this);
+
+    public override void OnDelete()
+    {
+        EventSystem.Npcs.Remove(this);
+        base.OnDelete();
+    }
+
+    public override void AddCustomContextEntries(Mobile from, ref PooledRefList<ContextMenuEntry> list)
+    {
+        base.AddCustomContextEntries(from, ref list);
+
+        if (from.Alive && from is PlayerMobile)
+        {
+            list.Add(new TalkEntry());
+        }
+    }
+
+    private class TalkEntry : ContextMenuEntry
+    {
+        public TalkEntry() : base(6146) // Talk
+        {
+        }
+
+        public override void OnClick(Mobile from, IEntity target)
+        {
+            if (EventSystem.Open && EventSystem.JoinMethod != null)
+            {
+                EventSystem.JoinMethod(from);
+            }
+            else
+            {
+                (target as Mobile)?.SayTo(from, "Currently there is no game open.");
+            }
+        }
+    }
+}
diff --git a/Projects/UOContent/Custom/DFI/Games/RaceTrackData.cs b/Projects/UOContent/Custom/DFI/Games/RaceTrackData.cs
