+// Generated from DFI RUNUO Data/Custom Building/Output/RaceTrack.bin: item, x, y, z per tile, relative to the
+// crate stone.
+
+namespace Server.Custom.Dfi.CrateRace;
+
+public static class RaceTrackData
+{
+    public static readonly int[] Tiles =
+    [
+        222, -3, -31, 0, 222, -2, -31, 0, 222, -1, -31, 0, 222, 0, -31, 0, 222, 1, -31, 0, 222, 2, -31, 0,
+        222, 3, -31, 0, 222, 4, -31, 0, 222, 5, -31, 0, 222, 6, -31, 0, 222, 7, -31, 0, 222, 8, -31, 0,
+        222, 9, -31, 0, 222, 10, -31, 0, 222, 11, -31, 0, 222, 12, -31, 0, 222, 13, -31, 0, 222, 14, -31, 0,
+        222, 15, -31, 0, 222, 16, -31, 0, 222, 17, -31, 0, 222, 18, -31, 0, 222, 19, -31, 0, 222, 20, -31, 0,
+        222, 21, -31, 0, 221, 21, -30, 0, 221, 21, -29, 0, 221, 21, -28, 0, 221, 21, -27, 0, 221, 21, -26, 0,
+        221, 21, -25, 0, 221, 21, -24, 0, 221, 21, -23, 0, 221, 21, -22, 0, 222, -3, -21, 0, 222, -2, -21, 0,
+        222, -1, -21, 0, 222, 0, -21, 0, 222, 1, -21, 0, 222, 2, -21, 0, 222, 3, -21, 0, 222, 4, -21, 0,
+        222, 5, -21, 0, 222, 6, -21, 0, 222, 7, -21, 0, 222, 8, -21, 0, 222, 9, -21, 0, 222, 10, -21, 0,
