diff --git a/Projects/UOContent.Tests/Tests/Custom/DfiBombermanTests.cs b/Projects/UOContent.Tests/Tests/Custom/DfiBombermanTests.cs
new file mode 100644
index 000000000..16918db2b
--- /dev/null
+++ b/Projects/UOContent.Tests/Tests/Custom/DfiBombermanTests.cs
@@ -0,0 +1,230 @@
+using System;
+using System.Collections.Generic;
+using Server;
+using Server.Custom.Dfi.Bomberman;
+using Server.Items;
+using Server.Misc;
+using Server.Mobiles;
+using Server.Network;
+using Server.Tests.Network;
+using Xunit;
+
+namespace UOContent.Tests.Custom;
+
+[Collection("Sequential UOContent Tests")]
+public class DfiBombermanTests : IDisposable
+{
+    private static readonly Point3D StoneAt = new(5300, 1400, 0);
+
+    private readonly List<IEntity> _created = new();
+    private readonly List<NetState> _connections = new();
+
+    public DfiBombermanTests()
+    {
+        if (NameList.GetNameList("male") == null)
+        {
+            NameList.Configure();
+        }
+    }
+
+    public void Dispose()
+    {
+        foreach (var e in _created)
+        {
+            e?.Delete();
+        }
+
+        _created.Clear();
+
+        foreach (var ns in _connections)
+        {
+            ns.Dispose();
+        }
+
+        _connections.Clear();
+        BoardGameData.ResetScores(BombermanSettings.GameName);
+    }
+
+    private T Track<T>(T e) where T : IEntity
+    {
+        _created.Add(e);
+        return e;
+    }
+
+    private PlayerMobile Player()
+    {
+        var m = Track(new PlayerMobile());
+        m.Player = true;
+        m.Body = 0x190;
+        m.AddItem(new Backpack());
+        m.AddItem(new BankBox(m));
+        m.MoveToWorld(new Point3D(StoneAt.X - 1, StoneAt.Y - 1, StoneAt.Z), Map.Felucca);
+        // Players without a connection count as logged out and are dropped when the game starts. It is attached
+        // once the player is on the map, since a map change would want an account behind it.
+        var ns = PacketTestUtilities.CreateTestNetState();
+        _connections.Add(ns);
+        m.NetState = ns;
+        return m;
+    }
+
+    private BombermanControlItem Stone()
+    {
+        var stone = Track(new BombermanControlItem());
+        stone.MoveToWorld(StoneAt, Map.Felucca);
+        stone.ResetBoard();
+        return stone;
+    }
+
+    private static int Count<T>(BombermanControlItem stone) => stone.BackgroundItems.FindAll(p => p is T).Count;
+
+    [Fact]
+    public void Board_HasFloorEverywhereAndAGridOfWalls()
+    {
+        var stone = Stone();
+        var w = stone.Width;
+        var h = stone.Height;
+
+        Assert.Equal(BombermanSettings.DefaultBoardSize, w);
+        Assert.Equal(w * h, Count<BombermanFloorTile>(stone));
+        // The border, and a pillar on every even-even cell inside it.
+        Assert.Equal(2 * w + 2 * (h - 2) + (w - 3) / 2 * ((h - 3) / 2), Count<IndestructibleWall>(stone));
+        Assert.Equal(0, Count<DestructibleWall>(stone));
+    }
+
+    [Theory]
+    [InlineData(4, 11)]
+    [InlineData(30, 31)]
+    [InlineData(100, 65)]
+    public void Board_SizesAreOddAndBounded(int asked, int expected)
+    {
+        var stone = Stone();
+
+        stone.Width = asked;
+
+        Assert.Equal(expected, stone.Width);
+    }
+
+    [Fact]
+    public void Game_StartsWhenEnoughPlayersJoinAndTheLeaderIsReady()
+    {
+        var stone = Stone();
+        var a = Player();
+        var b = Player();
+        stone.CurrentMaxPlayers = 2;
+
+        stone.AddPlayer(a);
+        Assert.Equal(BoardGameState.Recruiting, stone.State);
+
+        stone.AddPlayer(b);
+        Assert.Equal(BoardGameState.Recruiting, stone.State);
+
+        stone.SetReady(true);
+        Assert.Equal(BoardGameState.Active, stone.State);
+
+        Assert.Equal(stone.StartPoint(0), a.Location);
+        Assert.Equal(stone.StartPoint(1), b.Location);
+        Assert.NotNull(a.Backpack.FindItemByType<BombBag>());
+        Assert.True(Count<DestructibleWall>(stone) > 0);
+
+        foreach (var wall in stone.BackgroundItems.FindAll(p => p is DestructibleWall))
+        {
+            var cell = ((DestructibleWall)wall).Cell;
+            Assert.False(stone.IsStartArea(cell.X, cell.Y));
+        }
+    }
+
+    [Fact]
+    public void Bombs_AreLimitedAndOnePerTile()
+    {
+        var stone = Stone();
+        var player = Player();
+        var bag = Track(new BombBag(stone, 1, 1) { Owner = player });
+        player.Backpack.DropItem(bag);
+
+        Assert.True(bag.Plant(player));
+        Assert.False(bag.Plant(player));
+
+        player.Location = new Point3D(player.X + 1, player.Y, player.Z);
+        Assert.False(bag.Plant(player));
+
+        bag.Apply(UpgradeKind.BombCount);
+        Assert.True(bag.Plant(player));
+        Assert.Equal(2, bag.Bombs.Count);
+    }
+
+    [Fact]
+    public void Upgrades_ImproveTheBag()
+    {
+        var stone = Stone();
+        var player = Player();
+        var bag = Track(new BombBag(stone, 1, 1) { Owner = player });
+        player.Backpack.DropItem(bag);
+
+        bag.Apply(UpgradeKind.BlastStrength);
+        bag.Apply(UpgradeKind.BaddaBoom);
+        bag.Apply(UpgradeKind.Detonator);
+        bag.Apply(UpgradeKind.Detonator);
+
+        Assert.Equal(2, bag.BombStrength);
+        Assert.True(bag.BaddaBoom);
+        Assert.NotNull(bag.Detonator);
+        Assert.Single(player.Backpack.Items, i => i is BombDetonator);
+    }
+
+    [Fact]
+    public void Blast_PutsOutTheOtherPlayerAndTheLastOneStandingWins()
+    {
+        var stone = Stone();
+        var a = Player();
+        var b = Player();
+        stone.CurrentMaxPlayers = 2;
+        stone.AddPlayer(a);
+        stone.AddPlayer(b);
+        stone.SetReady(true);
+
+        var bag = a.Backpack.FindItemByType<BombBag>();
+        b.Location = a.Location;
+
+        stone.CheckForVictims(a.Location, a.Map, bag);
+
+        Assert.DoesNotContain(b, stone.Players);
+        Assert.Null(b.Backpack.FindItemByType<BombBag>());
+        Assert.Equal(new Point3D(StoneAt.X - 1, StoneAt.Y - 1, StoneAt.Z), b.Location);
+
+        var scores = BoardGameData.GetScores(BombermanSettings.GameName);
+        Assert.Equal(BombermanSettings.KillScore, scores.Find(s => s.Player == a).Score);
+        Assert.Equal(1, scores.Find(s => s.Player == b).Losses);
+    }
+
+    [Fact]
+    public void Ending_ClearsTheBoardAndReturnsToInactive()
+    {
+        var stone = Stone();
+        var a = Player();
+        var b = Player();
+        stone.CurrentMaxPlayers = 2;
+        stone.AddPlayer(a);
+        stone.AddPlayer(b);
+        stone.SetReady(true);
+
+        stone.EndGame();
+
+        Assert.Equal(BoardGameState.Inactive, stone.State);
+        Assert.Empty(stone.Players);
+        Assert.Null(a.Backpack.FindItemByType<BombBag>());
+        Assert.Equal(0, Count<DestructibleWall>(stone));
+    }
+
+    [Fact]
+    public void Leaving_EmptiesTheGame()
+    {
+        var stone = Stone();
+        var a = Player();
+        stone.CurrentMaxPlayers = 3;
+
+        stone.AddPlayer(a);
+        stone.RemovePlayer(a);
+
+        Assert.Equal(BoardGameState.Inactive, stone.State);
+    }
+}
diff --git a/Projects/UOContent/Custom/DFI/Games/Bomberman.cs b/Projects/UOContent/Custom/DFI/Games/Bomberman.cs
new file mode 100644
index 000000000..30ce4d3ab
--- /dev/null
+++ b/Projects/UOContent/Custom/DFI/Games/Bomberman.cs
@@ -0,0 +1,1475 @@
+// Bomberman, from the "Solaris BoardGames" scripts DFI Network ran (DFI RUNUO Scripts/Custom/Opticon/BoardGames).
+// Two to eight players start at the corners and edges of a walled board, each with a bomb bag that plants a bomb
+// at their feet. Bombs go off after three seconds (or on a detonator), their blasts running along the rows and
+// chaining into other bombs; they break the destructible walls, which sometimes leave an upgrade (more bombs,
+// a stronger blast, speed, a detonator, or blasts that tear through walls). A player caught in a blast is out;
+// the last one standing wins. Scores are kept per player.
+//
+// The board is built beside the join stone from its settings; its pieces are not saved, the stone builds them
+// again after a restart.
+
+using System;
+using System.Collections.Generic;
+using ModernUO.Serialization;
+using Server.Collections;
+using Server.ContextMenus;
+using Server.Custom.Dfi.Bomberman;
+using Server.Gumps;
+using Server.Items;
+using Server.Mobiles;
+using Server.Network;
+using Server.Regions;
+
+namespace Server.Custom.Dfi.Bomberman
+{
+    public enum BoardGameState
+    {
+        Disabled,
+        Inactive,
+        Pending,
+        Recruiting,
+        Active,
+        GameOver
+    }
+
+    public enum BombermanStyle
+    {
+        Default,
+        Rocky,
+        Woodland,
+        Warehouse,
+        Ruins,
+        Graveyard,
+        Crystal
+    }
+
+    [Flags]
+    public enum BlastDirection
+    {
+        None = 0x0,
+        West = 0x1,
+        North = 0x2,
+        East = 0x4,
+        South = 0x8
+    }
+
+    public static class BombermanSettings
+    {
+        public const string GameName = "Bomberman";
+        public const int MaxBoardSize = 65;
+        public const int MinBoardSize = 11;
+        public const int DefaultBoardSize = 21;
+        public const double ObstacleChance = 0.7;
+        public const double UpgradeSpawnChance = .2;
+        public static readonly TimeSpan ExplodeDelay = TimeSpan.FromSeconds(3);
+        public static readonly TimeSpan BlastDelay = TimeSpan.FromMilliseconds(50);
+        public static readonly TimeSpan UpgradeDecay = TimeSpan.FromSeconds(20);
+        public const int KillScore = 1;
+        public const int DeathScore = -1;
+        public const int WinScore = 2;
+        public const int SuicideScore = -2;
+
+        public static int DestructibleWallID(BombermanStyle style) =>
+            style switch
+            {
+                BombermanStyle.Rocky     => Utility.RandomMinMax(0x1363, 0x136D),
+                BombermanStyle.Woodland  => Utility.RandomMinMax(0xCC8, 0xCC9),
+                BombermanStyle.Warehouse => Utility.RandomMinMax(0xE3C, 0xE3F),
+                BombermanStyle.Ruins     => Utility.RandomMinMax(0x3B7, 0x3BD),
+                BombermanStyle.Graveyard => Utility.RandomMinMax(0x1AD8, 0x1ADC),
+                BombermanStyle.Crystal   => Utility.RandomMinMax(0x2224, 0x222C),
+                _                        => 1900
+            };
+
+        public static int IndestructibleWallID(BombermanStyle style) =>
+            style switch
+            {
+                BombermanStyle.Rocky     => 0x177A,
+                BombermanStyle.Woodland  => Utility.RandomList(0xE57, 0xE59),
+                BombermanStyle.Warehouse => Utility.RandomList(0x720, 0x721),
+                BombermanStyle.Ruins     => Utility.RandomMinMax(0x3BE, 0x3C1),
+                BombermanStyle.Graveyard => Utility.RandomMinMax(0x1165, 0x1184),
+                BombermanStyle.Crystal   => Utility.RandomList(0x35EB, 0x35EC, 0x35EF, 0x35F6, 0x35F7),
+                _                        => 1801
+            };
+
+        public static int FloorTileID(BombermanStyle style) =>
+            style switch
+            {
+                BombermanStyle.Rocky     => Utility.RandomMinMax(0x53B, 0x53F),
+                BombermanStyle.Woodland  => Utility.RandomMinMax(0x177D, 0x1781),
+                BombermanStyle.Warehouse => Utility.RandomMinMax(0x4A9, 0x4AC),
+                BombermanStyle.Ruins     => Utility.RandomMinMax(0x525, 0x528),
+                BombermanStyle.Graveyard => Utility.RandomMinMax(0x515, 0x518),
+                BombermanStyle.Crystal   => Utility.RandomMinMax(0x579, 0x57E),
+                _                        => 0x496
+            };
+    }
+
+    public class BoardGamePlayerScore
+    {
+        public BoardGamePlayerScore(Mobile player) => Player = player;
+
+        public Mobile Player { get; }
+        public int Score;
+        public int Wins;
+        public int Losses;
+    }
+
+    // Scores per game, kept across restarts.
+    public class BoardGameData : GenericPersistence
+    {
+        private static readonly Dictionary<string, List<BoardGamePlayerScore>> _games = [];
+
+        public BoardGameData() : base("DfiBoardGames", 10)
+        {
+        }
+
+        public static void Configure()
+        {
+            _ = new BoardGameData();
+        }
+
+        public static List<BoardGamePlayerScore> GetScores(string game)
+        {
+            if (!_games.TryGetValue(game, out var list))
+            {
+                _games[game] = list = [];
+            }
+
+            return list;
+        }
+
+        public static BoardGamePlayerScore Get(string game, Mobile player)
+        {
+            var list = GetScores(game);
+            var score = list.Find(s => s.Player == player);
+
+            if (score == null)
+            {
+                list.Add(score = new BoardGamePlayerScore(player));
+            }
+
+            return score;
+        }
+
+        public static void ChangeScore(string game, Mobile player, int delta)
+        {
+            var score = Get(game, player);
+            score.Score = Math.Max(0, score.Score + delta);
+        }
+
+        public static void AddWin(string game, Mobile player) => Get(game, player).Wins++;
+        public static void AddLoss(string game, Mobile player) => Get(game, player).Losses++;
+        public static void ResetScores(string game) => _games.Remove(game);
+
+        public override void Serialize(IGenericWriter writer)
+        {
+            writer.WriteEncodedInt(0); // version
+            writer.WriteEncodedInt(_games.Count);
+
+            foreach (var (game, list) in _games)
+            {
+                writer.Write(game);
+                writer.WriteEncodedInt(list.Count);
+
+                foreach (var s in list)
+                {
+                    writer.Write(s.Player);
+                    writer.WriteEncodedInt(s.Score);
+                    writer.WriteEncodedInt(s.Wins);
+                    writer.WriteEncodedInt(s.Losses);
+                }
+            }
+        }
+
+        public override void Deserialize(IGenericReader reader)
+        {
+            reader.ReadEncodedInt(); // version
+            var games = reader.ReadEncodedInt();
+
+            for (var g = 0; g < games; g++)
+            {
+                var list = GetScores(reader.ReadString());
+                var count = reader.ReadEncodedInt();
+
+                for (var i = 0; i < count; i++)
+                {
+                    var player = reader.ReadEntity<Mobile>();
+                    var score = new BoardGamePlayerScore(player)
+                    {
+                        Score = reader.ReadEncodedInt(), Wins = reader.ReadEncodedInt(), Losses = reader.ReadEncodedInt()
+                    };
+
+                    if (player?.Deleted == false)
+                    {
+                        list.Add(score);
+                    }
+                }
+            }
+        }
+    }
