+    [SerializationGenerator(0)]
+    public partial class Bomb : GamePiece
+    {
+        private Item _topper;
+        private Timer _fuse;
+
+        public Bomb(BombBag bag) : base(0x2256, $"{bag.Owner?.Name}'s Bomb")
+        {
+            Hue = 1;
+            Bag = bag;
+            Planter = bag.Owner;
+            Strength = bag.BombStrength;
+            BaddaBoom = bag.BaddaBoom;
+
+            _topper = BaddaBoom
+                ? new Static(0x1858) { Hue = 1161, Name = "If you can read this, you are probably going to die..." }
+                : bag.Detonator != null
+                    ? new Static(0xF13) { Name = Name }
+                    : new Static(0x1430) { Hue = 1, Name = Name };
+
+            if (bag.Detonator == null)
+            {
+                _fuse = Timer.DelayCall(BombermanSettings.ExplodeDelay, () => Explode());
+            }
+        }
+
+        public BombBag Bag { get; }
+        public Mobile Planter { get; set; }
+        public int Strength { get; }
+        public bool BaddaBoom { get; }
+
+        public override void OnLocationChange(Point3D oldLocation)
+        {
+            base.OnLocationChange(oldLocation);
+            _topper?.MoveToWorld(new Point3D(X, Y, Z + 3), Map);
+        }
+
+        public void Explode(BlastDirection inhibit = BlastDirection.None)
+        {
+            if (Deleted || Map == null || Map == Map.Internal)
+            {
+                return;
+            }
+
+            _fuse?.Stop();
+            Bag?.Bombs.Remove(this);
+
+            var map = Map;
+            var location = Location;
+            Delete();
+
+            Effects.PlaySound(location, map, Utility.RandomList(0x11B, 0x305, 0x306, 0x307, 0x11C, 0x308, 0x11D, 0x309, 0x4CF, 0x11E, 0x207));
+            Effects.SendLocationEffect(new Point3D(location.X + 1, location.Y + 1, location.Z), map, 0x36CB, 10);
+
+            foreach (var dir in (BlastDirection[])[BlastDirection.West, BlastDirection.North, BlastDirection.East, BlastDirection.South])
+            {
+                if (dir != inhibit)
+                {
+                    BombBlast.Start(location, map, dir, Bag, Strength - 1, BaddaBoom);
+                }
+            }
+
+            Bag?.Control?.CheckForVictims(location, map, Bag);
+        }
+
+        public void Detonate() => Explode();
+
+        public override void OnAfterDelete()
+        {
+            _fuse?.Stop();
+            _topper?.Delete();
+            base.OnAfterDelete();
+        }
+    }
+
+    // A blast front: one tile at a time, every fifty milliseconds, until it runs out of strength or hits something.
+    public static class BombBlast
+    {
+        public static void Start(Point3D origin, Map map, BlastDirection dir, BombBag bag, int strength, bool baddaBoom)
+        {
+            var (dx, dy) = dir switch
+            {
+                BlastDirection.West  => (-1, 0),
+                BlastDirection.East  => (1, 0),
+                BlastDirection.North => (0, -1),
+                _                    => (0, 1)
+            };
+
+            var at = new Point3D(origin.X + dx, origin.Y + dy, origin.Z);
+            bag?.Control?.CheckForVictims(at, map, bag);
+            Timer.DelayCall(BombermanSettings.BlastDelay, () => Burn(at, map, dir, bag, strength, baddaBoom));
+        }
+
+        private static void Burn(Point3D at, Map map, BlastDirection dir, BombBag bag, int strength, bool baddaBoom)
+        {
+            if (map == null)
+            {
+                return;
+            }
+
+            var hitWall = false;
+            BombermanObstacle obstacle = null;
+            Bomb bomb = null;
+
+            foreach (var item in map.GetItemsAt(at))
+            {
+                if (item is BombermanObstacle o and not BombermanFloorTile)
+                {
+                    obstacle = o;
+                    break;
+                }
+
+                if (item is Bomb b && !b.Deleted)
+                {
+                    bomb = b;
+                    break;
+                }
+            }
+
+            if (obstacle != null)
+            {
+                if (obstacle.Destructible)
+                {
+                    obstacle.Destroy();
+                }
+                else
+                {
+                    hitWall = true;
+                    strength = 0;
+                }
+
+                if (!baddaBoom)
+                {
+                    strength = 0;
+                }
+            }
+            else if (bomb != null)
+            {
+                // The bomb this blast set off is credited to the bag that set it off.
+                bomb.Planter = bag?.Owner;
+                bomb.Explode(Reverse(dir));
+                strength = 0;
+            }
+
+            if (!hitWall)
+            {
+                Effects.SendLocationEffect(new Point3D(at.X + 1, at.Y + 1, at.Z), map, Utility.RandomList(0x36CB, 0x36BD, 0x36B0), 10);
+            }
+
+            bag?.Control?.CheckForVictims(at, map, bag);
+
+            if (!hitWall && strength > 0)
+            {
+                Start(at, map, dir, bag, strength - 1, baddaBoom);
+            }
+        }
+
+        public static BlastDirection Reverse(BlastDirection dir) =>
+            dir switch
+            {
+                BlastDirection.West  => BlastDirection.East,
+                BlastDirection.East  => BlastDirection.West,
+                BlastDirection.North => BlastDirection.South,
+                BlastDirection.South => BlastDirection.North,
+                _                    => BlastDirection.None
+            };
+    }
+
+    [SerializationGenerator(0)]
+    public partial class BombBag : Item
+    {
+        private Mobile _owner;
+
+        public BombBag(BombermanControlItem control, int maxBombs, int strength) : base(0xE76)
+        {
+            Control = control;
+            Hue = 1161;
+            Movable = false;
+            MaxBombs = maxBombs;
+            BombStrength = strength;
+            Active = true;
+        }
+
+        public override string DefaultName => "Bomb Bag";
+
+        public BombermanControlItem Control { get; }
+        public List<Bomb> Bombs { get; } = [];
+        public int MaxBombs { get; set; }
+        public int BombStrength { get; set; }
+        public bool BaddaBoom { get; set; }
+        public bool SpeedUpgraded { get; private set; }
+        public BombDetonator Detonator { get; set; }
+        public bool Active { get; set; }
+
+        public Mobile Owner
+        {
+            get => _owner;
+            set
+            {
+                _owner = value;
+                // No speed from other sources, so every player starts even.
+                _owner?.NetState.SendSpeedControl(SpeedControlSetting.Disable);
+            }
+        }
+
+        public override void OnDoubleClick(Mobile from) => Plant(from);
+
+        public bool Plant(Mobile from)
+        {
+            if (from != Owner || !IsChildOf(from.Backpack) || !Active)
+            {
+                from.SendMessage("You cannot use that");
+                return false;
+            }
+
+            if (from.Followers > 0)
+            {
+                from.SendMessage("You can't use this with pets!");
+                return false;
+            }
+
+            foreach (var item in from.Map.GetItemsAt(from.Location))
+            {
+                if (item is Bomb)
+                {
+                    from.SendMessage("There is a bomb at your feet already!");
+                    return false;
+                }
+            }
+
+            if (Bombs.Count >= MaxBombs)
+            {
+                from.SendMessage("You have too many bombs on the field.");
+                return false;
+            }
+
+            var bomb = new Bomb(this);
+            from.PlaySound(0x42);
+            bomb.MoveToWorld(from.Location, from.Map);
+            Bombs.Add(bomb);
+            from.SendMessage("Planting bomb!");
+            return true;
+        }
+
+        public void Apply(UpgradeKind kind)
+        {
+            switch (kind)
+            {
+                case UpgradeKind.BombCount:
+                    {
+                        MaxBombs++;
+                        break;
+                    }
+                case UpgradeKind.BlastStrength:
+                    {
+                        BombStrength++;
+                        break;
+                    }
+                case UpgradeKind.Speed:
+                    {
+                        SpeedUpgraded = true;
+                        Owner?.NetState.SendSpeedControl(SpeedControlSetting.Mount);
+                        break;
+                    }
+                case UpgradeKind.Detonator when Detonator == null:
+                    {
+                        Detonator = new BombDetonator(this);
+                        Owner?.Backpack?.DropItem(Detonator);
+                        break;
+                    }
+                case UpgradeKind.BaddaBoom:
+                    {
+                        BaddaBoom = true;
+                        break;
+                    }
+            }
+        }
+
+        public void DetonateFirstBomb()
+        {
+            if (Bombs.Count > 0)
+            {
+                Bombs[0].Detonate();
+            }
+        }
+
+        public override void OnAfterDelete()
+        {
+            foreach (var bomb in Bombs.ToArray())
+            {
+                bomb.Delete();
+            }
+
+            Detonator?.Delete();
+
+            if (SpeedUpgraded)
+            {
+                Owner?.NetState.SendSpeedControl(SpeedControlSetting.Disable);
+            }
+
+            base.OnAfterDelete();
+        }
+
+        [AfterDeserialization]
+        private void AfterDeserialization() => Timer.DelayCall(Delete);
+    }
+
+    [SerializationGenerator(0)]
+    public partial class BombDetonator : Item
+    {
+        public BombDetonator(BombBag bag) : base(0xFC1)
+        {
+            Bag = bag;
+            Hue = 1161;
+            Movable = false;
+        }
+
+        public override string DefaultName => "Detonator";
+
+        public BombBag Bag { get; }
+
+        public override void OnDoubleClick(Mobile from)
+        {
+            if (Bag?.Deleted != false || from != Bag.Owner || !IsChildOf(from.Backpack) || !Bag.Active)
+            {
+                from.SendMessage("You cannot use that");
+                return;
+            }
+
+            Bag.DetonateFirstBomb();
+        }
+
+        public override void OnAfterDelete()
+        {
+            if (Bag?.Deleted == false)
+            {
+                Bag.Detonator = null;
+            }
+
+            base.OnAfterDelete();
+        }
+
+        [AfterDeserialization]
+        private void AfterDeserialization() => Timer.DelayCall(Delete);
+    }
+}
