+        public void BuildBoard()
+        {
+            if (Deleted || Map == null || Map == Map.Internal)
+            {
+                return;
+            }
+
+            _region = new BombermanRegion(this, GameZone);
+            _region.Register();
+
+            var w = _boardWidth;
+            var h = _boardHeight;
+
+            for (var i = 0; i < w; i++)
+            {
+                for (var j = 0; j < h; j++)
+                {
+                    Add(new BombermanFloorTile(_style), i, j);
+
+                    if (i == 0 || i == w - 1 || j == 0 || j == h - 1 || i % 2 == 0 && j % 2 == 0)
+                    {
+                        Add(new IndestructibleWall(_style), i, j);
+                    }
+                    else if (State == BoardGameState.Active && !IsStartArea(i, j) && Utility.RandomDouble() < BombermanSettings.ObstacleChance)
+                    {
+                        Add(new DestructibleWall(_style) { Cell = new Point2D(i, j) }, i, j);
+                    }
+                }
+            }
+        }
+
+        // The corners and edge midpoints where players start are kept clear.
+        public bool IsStartArea(int i, int j)
+        {
+            var w = _boardWidth;
+            var h = _boardHeight;
+
+            return i < 3 && j < 3 || i > w - 4 && j < 3 || i < 3 && j > h - 4 || i > w - 4 && j > h - 4 ||
+                   j > h / 2 - 2 && j < h / 2 + 2 && (i < 3 || i > w - 4) ||
+                   i > w / 2 - 2 && i < w / 2 + 2 && (j < 3 || j > h - 4);
+        }
+
+        private void Add(BombermanObstacle piece, int x, int y)
+        {
+            piece.Place(this, x, y);
+            BackgroundItems.Add(piece);
+        }
+
+        public void SpawnUpgrade(Point2D cell)
+        {
+            var upgrade = new BombermanUpgrade(BombermanUpgrade.Roll(this));
+            upgrade.Place(this, cell.X, cell.Y, 3);
+            BackgroundItems.Add(upgrade);
+        }
+
+        public Point3D StartPoint(int index)
+        {
+            var w = _boardWidth;
+            var h = _boardHeight;
+
+            var (x, y) = index switch
+            {
+                0 => (1, 1),
+                1 => (w - 2, 1),
+                2 => (1, h - 2),
+                3 => (w - 2, h - 2),
+                4 => (w / 2, 1),
+                5 => (w - 2, h / 2),
+                6 => (w / 2, h - 2),
+                _ => (1, h / 2)
+            };
+
+            return new Point3D(BoardLocation.X + x, BoardLocation.Y + y, BoardLocation.Z);
+        }
+
+        public override void GetProperties(IPropertyList list)
+        {
+            base.GetProperties(list);
+            list.Add(1070722, $"Status: {State}"); // ~1_NOTHING~
+            list.Add(1060658, $"{"Cost to play"}\t{_costToPlay}"); // ~1_val~: ~2_val~
+        }
+
+        public override void GetContextMenuEntries(Mobile from, ref PooledRefList<ContextMenuEntry> list)
+        {
+            base.GetContextMenuEntries(from, ref list);
+            list.Add(new ScoresEntry());
+
+            if (from.AccessLevel >= AccessLevel.GameMaster)
+            {
+                list.Add(new ResetScoresEntry());
+            }
+        }
+
+        public bool CanUse(Mobile from)
+        {
+            if (from.NetState == null)
+            {
+                return false;
+            }
+
+            if (!from.InRange(this, 10))
+            {
+                from.SendMessage("You are out of range.");
+                return false;
+            }
+
+            if (from.Followers > 0)
+            {
+                from.SendMessage("You are not allowed to have pets in this game.");
+                return false;
+            }
+
+            if (!PayCost(from, false))
+            {
+                from.SendMessage("You lack the gold to play this game.");
+                return false;
+            }
+
+            return true;
+        }
+
+        // The fee comes from the backpack, or failing that the bank.
+        public bool PayCost(Mobile from, bool withdraw)
+        {
+            if (_costToPlay <= 0)
+            {
+                return true;
+            }
+
+            if (from.Backpack?.GetAmount(typeof(Gold)) >= _costToPlay)
+            {
+                return !withdraw || from.Backpack.ConsumeTotal(typeof(Gold), _costToPlay);
+            }
+
+            return withdraw ? Banker.Withdraw(from, _costToPlay) : Banker.GetBalance(from) >= _costToPlay;
+        }
+
+        public override void OnDoubleClick(Mobile from)
+        {
+            if (!CanUse(from))
+            {
+                return;
+            }
+
+            switch (State)
+            {
+                case BoardGameState.Disabled:
+                    {
+                        from.SendMessage("That game has been disabled by staff.");
+                        break;
+                    }
+                case BoardGameState.Inactive:
+                    {
+                        PendingPlayers.Add(from);
+                        State = BoardGameState.Pending;
+                        from.SendGump(new BombermanOfferGump(this, true), true);
+                        break;
+                    }
+                case BoardGameState.Pending:
+                    {
+                        from.SendMessage("This game is pending use from another player.  Please try again later.");
+                        break;
+                    }
+                case BoardGameState.Recruiting when Players.Contains(from):
+                    {
+                        from.SendGump(new BombermanAwaitGump(this), true);
+                        break;
+                    }
+                case BoardGameState.Recruiting when PendingPlayers.Count < CurrentMaxPlayers:
+                    {
+                        PendingPlayers.Add(from);
+                        from.SendGump(new BombermanOfferGump(this, false), true);
+                        break;
+                    }
+                case BoardGameState.Recruiting:
+                    {
+                        from.SendMessage("This game has enough players attempting to start a game.  Please try again later.");
+                        break;
+                    }
+                case BoardGameState.Active when !Players.Contains(from):
+                    {
+                        from.SendMessage("A game is already in progess.  Please try again later.");
+                        break;
+                    }
+                case BoardGameState.GameOver:
+                    {
+                        from.SendMessage("The last game has just ended.  Please try again later.");
+                        break;
+                    }
+            }
+        }
+
+        public void AddPlayer(Mobile m)
+        {
+            if (Players.Contains(m))
+            {
+                return;
+            }
+
+            Players.Add(m);
+            PublicOverheadMessage(MessageType.Regular, 1153, false, $"Adding {m.Name} to the game!");
+            State = BoardGameState.Recruiting;
+
+            if (Players.Count == 1)
+            {
+                SettingsReady = !_allowPlayerConfiguration;
+
+                if (_allowPlayerConfiguration)
+                {
+                    PublicOverheadMessage(MessageType.Regular, 1153, false, $"{m.Name} is now in charge of this game!");
+                    m.SendGump(new BombermanStyleGump(this), true);
+                }
+            }
+
+            if (Players.Count < CurrentMaxPlayers)
+            {
+                m.SendGump(new BombermanAwaitGump(this), true);
+                PublicOverheadMessage(MessageType.Regular, 1153, false, $"{CurrentMaxPlayers - Players.Count} more needed!");
+            }
+            else if (SettingsReady)
+            {
+                InitializeGame();
+            }
+            else
+            {
+                PublicOverheadMessage(MessageType.Regular, 1153, false, $"{Players[0].Name} needs to confirm style!");
+            }
+        }
+
+        public void RemovePlayer(Mobile m)
+        {
+            if (Players.Remove(m))
+            {
+                PublicOverheadMessage(MessageType.Regular, 1153, false, $"Removing {m.Name} from the game!");
+            }
+
+            PendingPlayers.Remove(m);
+            m.CloseGump<BombermanAwaitGump>();
+            m.CloseGump<BombermanStyleGump>();
+
+            if (Players.Count > 0)
+            {
+                PublicOverheadMessage(MessageType.Regular, 1153, false, $"{CurrentMaxPlayers - Players.Count} more needed!");
+            }
+            else if (State is BoardGameState.Pending or BoardGameState.Recruiting)
+            {
+                State = BoardGameState.Inactive;
+                PublicOverheadMessage(MessageType.Regular, 1153, false, "No more players... resetting.");
+            }
+        }
+
+        public void SetReady(bool ready)
+        {
+            SettingsReady = ready;
+
+            if (ready && Players.Count == CurrentMaxPlayers && State < BoardGameState.Active)
+            {
+                InitializeGame();
+            }
+        }
+
+        public void InitializeGame()
+        {
+            foreach (var player in Players.ToArray())
+            {
+                if (!CanUse(player))
+                {
+                    player.SendMessage("You can no longer enter the game, and have been removed from the list.");
+                    RemovePlayer(player);
+                    return;
+                }
+            }
+
+            PendingPlayers.Clear();
+            State = BoardGameState.Active;
+
+            foreach (var player in Players)
+            {
+                PayCost(player, true);
+                player.SendMessage("Game on!");
+                player.CloseGump<BombermanAwaitGump>();
+                player.CloseGump<BombermanStyleGump>();
+            }
+
+            ResetBoard();
+
+            for (var i = 0; i < Players.Count; i++)
+            {
+                var player = Players[i];
+                player.MoveToWorld(StartPoint(i), Map);
+
+                var bag = new BombBag(this, _defaultMaxBombs, _defaultBombStrength) { Owner = player, BaddaBoom = _defaultBaddaBoom };
+                BombBags.Add(bag);
+                player.Backpack.DropItem(bag);
+
+                if (_defaultDetonatorMode)
+                {
+                    bag.Apply(UpgradeKind.Detonator);
+                }
+            }
+        }
+
+        // Puts out every player standing on the spot, crediting the bag's owner.
+        public void CheckForVictims(Point3D location, Map map, BombBag source)
+        {
+            if (State != BoardGameState.Active || source == null)
+            {
+                return;
+            }
+
+            var victims = new List<Mobile>();
+
+            foreach (var m in map.GetMobilesInRange(location, 0))
+            {
+                if (Players.Contains(m))
+                {
+                    victims.Add(m);
+                }
+            }
+
+            foreach (var m in victims)
+            {
+                var killer = source.Owner;
+
+                if (m != killer)
+                {
+                    m.SendMessage($"You've been blown up by {killer?.Name}'s blast!");
+                    killer?.SendMessage($"You've blown {m.Name}!");
+
+                    if (_saveScore)
+                    {
+                        BoardGameData.ChangeScore(BombermanSettings.GameName, killer, BombermanSettings.KillScore);
+                        BoardGameData.ChangeScore(BombermanSettings.GameName, m, BombermanSettings.DeathScore);
+                    }
+
+                    PublicOverheadMessage(MessageType.Regular, 1153, false, $"{killer?.Name} has blown up {m.Name}!");
+                }
+                else
+                {
+                    m.SendMessage("You just blew yourself up!!");
+                    PublicOverheadMessage(MessageType.Regular, 1153, false, $"{m.Name} has just blown themself up!");
+
+                    if (_saveScore)
+                    {
+                        BoardGameData.ChangeScore(BombermanSettings.GameName, m, BombermanSettings.SuicideScore);
+                    }
+                }
+
+                if (_saveScore)
+                {
+                    BoardGameData.AddLoss(BombermanSettings.GameName, m);
+                }
+
+                m.PlaySound(m.Female ? 0x32E : 0x549);
+                Players.Remove(m);
+                m.Backpack?.FindItemByType<BombBag>()?.Delete();
+                m.MoveToWorld(new Point3D(X - 1, Y - 1, Z), Map);
+                m.SendGump(new BombermanResultGump(false), true);
+            }
+
+            if (victims.Count > 0)
+            {
+                _endCheck?.Stop();
+                _endCheck = Timer.DelayCall(TimeSpan.FromSeconds(1), CheckForWinner);
+            }
+        }
+
+        private void CheckForWinner()
+        {
+            if (State != BoardGameState.Active || Players.Count >= 2)
+            {
+                return;
+            }
+
+            State = BoardGameState.GameOver;
+
+            if (Players.Count == 1)
+            {
+                var winner = Players[0];
+                winner.SendGump(new BombermanResultGump(true), true);
+
+                if (_saveScore)
+                {
+                    BoardGameData.ChangeScore(BombermanSettings.GameName, winner, BombermanSettings.WinScore);
+                    BoardGameData.AddWin(BombermanSettings.GameName, winner);
+                }
+
+                var bag = winner.Backpack?.FindItemByType<BombBag>();
+
+                if (bag != null)
+                {
+                    bag.Active = false;
+                }
+
+                PublicOverheadMessage(MessageType.Regular, 1153, false, $"{winner.Name} wins the game!");
+            }
+            else
+            {
+                PublicOverheadMessage(MessageType.Regular, 1153, false, "It's a draw!");
+            }
+
+            _winner?.Stop();
+            _winner = Timer.DelayCall(WinDelay, EndGame);
+        }
+
+        public void EndGame()
+        {
+            _endCheck?.Stop();
+            _winner?.Stop();
+
+            foreach (var player in Players)
+            {
+                player.MoveToWorld(new Point3D(X - 1, Y - 1, Z), Map);
+                player.SendMessage("You've won the game!");
+            }
+
+            foreach (var bag in BombBags.ToArray())
+            {
+                bag.Delete();
+            }
+
+            BombBags.Clear();
+            Players.Clear();
+            PendingPlayers.Clear();
+            State = _isDisabled ? BoardGameState.Disabled : BoardGameState.Inactive;
+            ResetBoard();
+            InvalidateProperties();
+        }
+
+        public override void OnLocationChange(Point3D oldLocation)
+        {
+            base.OnLocationChange(oldLocation);
+            ResetBoard();
+        }
+
+        public override void OnMapChange()
+        {
+            base.OnMapChange();
+            ResetBoard();
+        }
+
+        [AfterDeserialization]
+        private void AfterDeserialization()
+        {
+            State = _isDisabled ? BoardGameState.Disabled : BoardGameState.Inactive;
+            Timer.DelayCall(ResetBoard);
+        }
+
+        public override void OnAfterDelete()
+        {
+            _endCheck?.Stop();
+            _winner?.Stop();
+
+            foreach (var bag in BombBags.ToArray())
+            {
+                bag.Delete();
+            }
+
+            WipeBoard();
+            base.OnAfterDelete();
+        }
+
+        private class ScoresEntry : ContextMenuEntry
+        {
+            public ScoresEntry() : base(6239, 10) // View scores
+            {
+            }
+
+            public override void OnClick(Mobile from, IEntity target) => from.SendGump(new BombermanScoresGump(0), true);
+        }
+
+        private class ResetScoresEntry : ContextMenuEntry
+        {
+            public ResetScoresEntry() : base(6162, 10) // Reset
+            {
+            }
+
+            public override void OnClick(Mobile from, IEntity target)
+            {
+                if (from.AccessLevel >= AccessLevel.GameMaster)
+                {
+                    from.SendGump(new BombermanResetScoresGump(), true);
+                }
+            }
+        }
+    }
+}
diff --git a/Projects/UOContent/Custom/DFI/Games/BombermanGumps.cs b/Projects/UOContent/Custom/DFI/Games/BombermanGumps.cs
new file mode 100644
index 000000000..3f0a029af
--- /dev/null
+++ b/Projects/UOContent/Custom/DFI/Games/BombermanGumps.cs
@@ -0,0 +1,321 @@
+// Bomberman's gumps, from the Solaris BoardGames scripts DFI Network ran (Base/Gumps, Bomberman/Gumps): the offer
+// to play, waiting for players, the leader's board settings, the result, the scores and the staff score reset.
+
+using System;
+using System.Collections.Generic;
+using Server.Gumps;
+using Server.Items;
+using Server.Network;
+
+namespace Server.Custom.Dfi.Bomberman;
+
+public abstract class BombermanGump : DynamicGump
+{
+    protected BombermanGump() : base(100, 100)
+    {
+    }
+
+    protected static void AddFrame(ref DynamicGumpBuilder builder, int width, int height)
+    {
+        builder.AddPage();
+        builder.AddBackground(0, 0, width, height, 9270);
+        builder.AddAlphaRegion(10, 10, width - 20, height - 20);
+        builder.AddLabel(40, 20, 1152, "Game:");
+        builder.AddLabel(140, 20, 1172, BombermanSettings.GameName);
+    }
+
+    public const string Description =
+        "Blow up walls and players with bombs.  Collect upgrades to improve your number of bombs, blast size, etc.";
+
+    public const string Rules =
+        "Each game can have up to eight players, and everyone starts in a corner or edge of the arena.  A bomb bag is placed in the players' backpacks.  Players use this bag to place bombs at their feet.  A bomb will detonate after some time, and has a limited blast size.  The number of bombs any player can place at any time is limited.<BR><BR>Players must blast at the breakable walls to navigate the arena.  While blasting, upgrades can be found which improve the blast size or number of bombs a player can place at once.  There is also a detonator upgrade that lets a player choose when they want their bombs to blow up.  Watch out for other players' blasts!  A bomb can trigger another bomb to go off, creating interesting chain reactions!<BR><BR>The game ends when there is only one player left standing.";
+}
+
+public class BombermanOfferGump : BombermanGump
+{
+    private readonly BombermanControlItem _control;
+    private readonly bool _choosePlayers;
+
+    public BombermanOfferGump(BombermanControlItem control, bool choosePlayers)
+    {
+        _control = control;
+        _choosePlayers = choosePlayers;
+    }
+
+    public override bool Singleton => true;
+
+    protected override void BuildLayout(ref DynamicGumpBuilder builder)
+    {
+        AddFrame(ref builder, 400, 500);
+        builder.AddLabel(40, 50, 1152, "Description:");
+        builder.AddHtml(40, 70, 300, 100, Description, background: true, scrollbar: true);
+        builder.AddLabel(40, 180, 1152, "Rules:");
+        builder.AddHtml(40, 200, 300, 150, Rules, background: true, scrollbar: true);
+
+        if (_control.CostToPlay > 0)
+        {
+            builder.AddLabel(40, 370, 1152, "Cost to play:");
+            builder.AddLabel(240, 370, 1172, $"{_control.CostToPlay} gold");
+        }
+
+        builder.AddLabel(40, 430, 1152, $"# of players ({BombermanControlItem.MinPlayers}-{BombermanControlItem.MaxPlayers}):");
+
+        if (_choosePlayers)
+        {
+            builder.AddLabel(60, 410, 1172, "Pick the number of players");
+            builder.AddImageTiled(240, 430, 30, 20, 0xBBC);
+            builder.AddTextEntry(242, 430, 26, 20, 0, 0, $"{_control.CurrentMaxPlayers}");
+        }
+        else
+        {
+            builder.AddLabel(240, 430, 1152, $"{_control.CurrentMaxPlayers}");
+        }
+
+        builder.AddLabel(40, 470, 1152, "Play this game?");
+        builder.AddButton(200, 460, 0xF7, 0xF8, 1);
+        builder.AddButton(300, 460, 0xF1, 0xF2, 0);
+    }
+
+    public override void OnResponse(NetState sender, in RelayInfo info)
+    {
+        var m = sender.Mobile;
+
+        if (info.ButtonID == 0)
+        {
+            _control.RemovePlayer(m);
+            m.SendMessage("You decide not to play this game");
+            return;
+        }
+
+        if (_choosePlayers)
+        {
+            if (!int.TryParse(info.GetTextEntry(0)?.Trim(), out var count) ||
+                count is < BombermanControlItem.MinPlayers or > BombermanControlItem.MaxPlayers)
+            {
+                m.SendMessage("Invalid number of players selected.  Please try again.");
+                m.SendGump(new BombermanOfferGump(_control, true), true);
+                return;
+            }
+
+            _control.CurrentMaxPlayers = count;
+        }
+
+        m.SendMessage("You have signed up for this game.");
+        _control.AddPlayer(m);
+    }
+}
+
+public class BombermanAwaitGump : BombermanGump
+{
+    private readonly BombermanControlItem _control;
+
+    public BombermanAwaitGump(BombermanControlItem control) => _control = control;
+
+    public override bool Singleton => true;
+
+    protected override void BuildLayout(ref DynamicGumpBuilder builder)
+    {
+        builder.SetNoClose();
+        AddFrame(ref builder, 400, 200);
+        builder.AddHtml(
+            40, 50, 320, 80,
+            "You are waiting for more players to join this game.  When there are enough, this window will automatically close and the game will start.",
+            background: true
+        );
+        builder.AddButton(160, 160, 0xF1, 0xF2, 1);
+    }
+
+    public override void OnResponse(NetState sender, in RelayInfo info)
+    {
+        if (info.ButtonID == 1)
+        {
+            _control.RemovePlayer(sender.Mobile);
+            sender.Mobile.SendMessage("You are no longer waiting to play this game.");
+        }
+    }
+}
+
+// The first player chooses the board's style and size, and says when to start.
+public class BombermanStyleGump : BombermanGump
+{
+    private const int Ready = 1000;
+
+    private readonly BombermanControlItem _control;
+
+    public BombermanStyleGump(BombermanControlItem control) => _control = control;
+
+    public override bool Singleton => true;
+
+    protected override void BuildLayout(ref DynamicGumpBuilder builder)
+    {
+        var styles = Enum.GetValues<BombermanStyle>();
+        var height = 220 + styles.Length * 20;
+
+        builder.AddPage();
+        builder.AddBackground(0, 0, 260, height, 9270);
+        builder.AddAlphaRegion(10, 10, 240, height - 20);
+        builder.AddLabel(20, 14, 1152, "Bomberman Board Style");
+
+        var y = 50;
+
+        foreach (var style in styles)
+        {
+            var button = _control.BoardStyle == style ? 0x2C92 : 0x2C88;
+            builder.AddButton(20, y += 20, button, button, (int)style + 1);
+            builder.AddLabel(40, y - 2, 1152, $"{style}");
+        }
+
+        builder.AddLabel(20, y += 30, 1152, "Width:");
+        builder.AddLabel(110, y, 1152, "Height:");
+
+        if (!_control.SettingsReady)
+        {
+            builder.AddImageTiled(70, y, 30, 20, 0xBBC);
+            builder.AddTextEntry(72, y, 26, 20, 0, 1, $"{_control.Width}");
+            builder.AddImageTiled(160, y, 30, 20, 0xBBC);
+            builder.AddTextEntry(162, y, 26, 20, 0, 2, $"{_control.Height}");
+        }
+        else
+        {
+            builder.AddLabel(70, y, 1152, $"{_control.Width}");
+            builder.AddLabel(160, y, 1152, $"{_control.Height}");
+        }
+
+        builder.AddLabel(20, y += 40, 1152, "Ready to start:");
+        var readyButton = _control.SettingsReady ? 0xD3 : 0xD2;
+        builder.AddButton(140, y, readyButton, readyButton, Ready);
+    }
+
+    public override void OnResponse(NetState sender, in RelayInfo info)
+    {
+        var m = sender.Mobile;
+
+        if (_control.Players.Count == 0 || _control.Players[0] != m || _control.State >= BoardGameState.Active)
+        {
+            return;
+        }
+
+        if (!_control.SettingsReady &&
+            int.TryParse(info.GetTextEntry(1)?.Trim(), out var w) && int.TryParse(info.GetTextEntry(2)?.Trim(), out var h) &&
+            (w != _control.Width || h != _control.Height))
+        {
+            _control.SetBoardSize(w, h);
+        }
+
+        if (info.ButtonID is > 0 and < Ready && !_control.SettingsReady)
+        {
+            _control.BoardStyle = (BombermanStyle)(info.ButtonID - 1);
+        }
+
+        if (info.ButtonID == Ready)
+        {
+            _control.SetReady(!_control.SettingsReady);
+        }
+
+        if (info.ButtonID != 0 && _control.State < BoardGameState.Active)
+        {
+            m.SendGump(new BombermanStyleGump(_control), true);
+        }
+    }
+}
+
+public class BombermanResultGump : BombermanGump
+{
+    private readonly bool _won;
+
+    public BombermanResultGump(bool won) => _won = won;
+
+    public override bool Singleton => true;
+
+    protected override void BuildLayout(ref DynamicGumpBuilder builder)
+    {
+        AddFrame(ref builder, 400, 120);
+        builder.AddLabel(40, 50, 1152, _won ? "Congratulations, you won the game!!" : "You've lost the game!");
+        builder.AddButton(160, 80, 0xF7, 0xF8, 0);
+    }
+}
+
+public class BombermanScoresGump : BombermanGump
+{
+    private const int PerPage = 15;
+    private readonly int _page;
+
+    public BombermanScoresGump(int page) => _page = Math.Max(0, page);
+
+    public override bool Singleton => true;
+
+    protected override void BuildLayout(ref DynamicGumpBuilder builder)
+    {
+        var scores = new List<BoardGamePlayerScore>(BoardGameData.GetScores(BombermanSettings.GameName));
+        scores.Sort((a, b) => b.Score.CompareTo(a.Score));
+
+        AddFrame(ref builder, 400, 140 + PerPage * 20);
+        builder.AddLabel(40, 50, 1152, "Scores");
+
+        if (scores.Count == 0)
+        {
+            builder.AddLabel(40, 80, 1152, "- NO SCORES SET YET -");
+            return;
+        }
+
+        builder.AddLabel(40, 80, 1152, "Name");
+        builder.AddLabel(190, 80, 1152, "Score");
+        builder.AddLabel(240, 80, 1152, "Wins");
+        builder.AddLabel(290, 80, 1152, "Losses");
+
+        var start = Math.Min(_page * PerPage, Math.Max(0, scores.Count - 1) / PerPage * PerPage);
+
+        for (var i = start; i < Math.Min(scores.Count, start + PerPage); i++)
+        {
+            var y = 100 + (i - start) * 20;
+            builder.AddLabel(40, y, 1152, scores[i].Player.Name);
+            builder.AddLabel(190, y, 1152, $"{scores[i].Score}");
+            builder.AddLabel(240, y, 1152, $"{scores[i].Wins}");
+            builder.AddLabel(290, y, 1152, $"{scores[i].Losses}");
+        }
+
+        if (start > 0)
+        {
+            builder.AddButton(40, 110 + PerPage * 20, 4014, 4015, 1);
+        }
+
+        if (start + PerPage < scores.Count)
+        {
+            builder.AddButton(320, 110 + PerPage * 20, 4005, 4006, 2);
+        }
+    }
+
+    public override void OnResponse(NetState sender, in RelayInfo info)
+    {
+        if (info.ButtonID is 1 or 2)
+        {
+            sender.Mobile.SendGump(new BombermanScoresGump(_page + (info.ButtonID == 1 ? -1 : 1)), true);
+        }
+    }
+}
+
+public class BombermanResetScoresGump : BombermanGump
+{
+    public override bool Singleton => true;
+
+    protected override void BuildLayout(ref DynamicGumpBuilder builder)
+    {
+        AddFrame(ref builder, 400, 200);
+        builder.AddHtml(
+            40, 50, 320, 80,
+            $"You are about to reset all the score data for {BombermanSettings.GameName}.  Once you do this, it cannot be undone.  Are you sure you wish to do this?",
+            background: true
+        );
+        builder.AddButton(100, 160, 0xF7, 0xF8, 1);
+        builder.AddButton(240, 160, 0xF1, 0xF2, 0);
+    }
+
+    public override void OnResponse(NetState sender, in RelayInfo info)
+    {
+        if (info.ButtonID == 1 && sender.Mobile.AccessLevel >= AccessLevel.GameMaster)
+        {
+            BoardGameData.ResetScores(BombermanSettings.GameName);
+            sender.Mobile.SendMessage("Score data has been reset.");
+        }
+    }
+}
